def convex_hull_2d(points: np.ndarray) -> np.ndarray:
    return stl_geometry.convex_hull_2d(points)


def _coerce_opt_flag(value) -> bool:
    if isinstance(value, bool):
        return value
    return str(value).strip() in {"*", "1", "true", "True", "yes", "on"}


def _coerce_bounds(value) -> tuple[float, float] | None:
    if value is None:
        return None
    if isinstance(value, (list, tuple)) and len(value) == 2:
        return (float(value[0]), float(value[1]))
    return None


def _compact_surface_attr_name(value: object) -> str:
    return re.sub(r"[^a-z0-9]", "", str(value).strip().lower())


def _canonical_advanced_surface_attr(value: object) -> str | None:
    return ADVANCED_SURFACE_ATTR_ALIASES.get(_compact_surface_attr_name(value))


def _advanced_surface_attrs_from_spec(spec: dict) -> dict[str, object]:
    attrs: dict[str, object] = {}
    for source_key in ("advanced", "advanced_attrs", "surface_attrs"):
        source = spec.get(source_key)
        if not isinstance(source, dict):
            continue
        for key, value in source.items():
            attr = _canonical_advanced_surface_attr(key)
            if attr is not None:
                attrs[attr] = value
    for key, value in spec.items():
        if str(key).strip().lower() == "element":
            continue
        attr = _canonical_advanced_surface_attr(key)
        if attr is not None:
            attrs[attr] = value
    return attrs


def _normalize_advanced_surface_value(attr: str, value):
    if attr in {"AspherData", "ZNK"}:
        try:
            array = np.asarray(value, dtype=float).ravel()
        except Exception:
            return value
        minimum = 200 if attr == "AspherData" else 36
        if array.size < minimum:
            array = np.pad(array, (0, minimum - array.size), mode="constant")
        return array
    if attr == "Error_map":
        try:
            return _error_map_literal(value)
        except Exception:
            return value
    if attr == "Mask_Shape":
        try:
            return _decode_mask_shape_value(value)
        except Exception:
            return value
    if attr == BEAM_SPLITTER_ADVANCED_ATTR:
        return _normalize_beam_splitter_settings(value)
    if attr == DIFFUSE_SCATTER_ADVANCED_ATTR:
        return _normalize_diffuse_scatter_settings(value)
    if attr == ELEMENT_ADVANCED_ATTR:
        return _normalize_element_metadata(value)
    if attr == SCENE_TARGET_ADVANCED_ATTR:
        return _normalize_scene_target_settings(value)
    if attr == SCENE_PLACEMENT_ADVANCED_ATTR:
        return normalize_scene_placement_settings(value)
    if attr == "Solid_3d_stl":
        return _normalize_optical_solid_path_value(value)
    if attr == "OpticalSolidFaces":
        return normalize_optical_solid_face_metadata(value)
    if attr == DRAWING_PROPERTIES_ADVANCED_ATTR:
        return normalize_drawing_properties(value)
    return value


def _decode_mask_shape_value(value):
    if not isinstance(value, dict):
        return value
    kind = str(value.get("kind", "")).strip().lower()
    if kind not in {"mask_shape", "mask", "mask_preset"}:
        return value
    preset = str(value.get("preset", value.get("name", ""))).strip().lower()
    _load_3d_backends()
    if pv is None:
        return value
    extent = max(float(value.get("extent", value.get("diameter", 50.0))), 1.0)
    block = pv.MultiBlock()
    if preset == "ronchi":
        period = max(float(value.get("period", extent / 20.0)), 1e-6)
        duty_cycle = min(max(float(value.get("duty_cycle", 0.5)), 0.02), 0.98)
        line_width = period * duty_cycle
        start = -0.5 * extent
        stop = 0.5 * extent
        positions = np.arange(start, stop + period, period)
        for position in positions:
            block.append(
                pv.Plane(
                    center=[float(position), 0.0, 0.0],
                    direction=[0.0, 0.0, 1.0],
                    i_size=float(line_width),
                    j_size=float(extent),
                    i_resolution=1,
                    j_resolution=1,
                )
            )
        return block
    if preset == "spider":
        arms = max(int(value.get("arms", 4)), 1)
        arm_width = max(float(value.get("arm_width", extent * 0.035)), 1e-6)
        hub_radius = max(float(value.get("hub_radius", extent * 0.08)), 0.0)
        for index in range(arms):
            angle = float(index) * 360.0 / float(arms)
            plane = pv.Plane(
                center=[0.0, 0.0, 0.0],
                direction=[0.0, 0.0, 1.0],
                i_size=float(extent),
                j_size=float(arm_width),
                i_resolution=1,
                j_resolution=1,
            )
            try:
                plane.rotate_z(angle, point=(0.0, 0.0, 0.0), inplace=True)
            except Exception:
                pass
            block.append(plane)
        if hub_radius > 0.0:
            try:
                block.append(
                    pv.Disc(
                        center=(0.0, 0.0, 0.0),
                        inner=0.0,
                        outer=float(hub_radius),
                        normal=(0.0, 0.0, 1.0),
                        r_res=2,
                        c_res=48,
                    )
                )
            except Exception:
                pass
        return block
    return value


def _normalize_native_variable_name(value: object) -> str:
    text = str(value).strip()
    compact = _compact_surface_attr_name(text)
    aliases = {
        "r": "Rc",
        "rc": "Rc",
        "radius": "Rc",
        "curvature": "Rc",
        "thick": "Thickness",
        "thickness": "Thickness",
        "k": "k",
        "conic": "k",
        "conicconstant": "k",
    }
    return aliases.get(compact, text)


def _native_variable_names(value: object) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return []
        if text[0:1] in {"[", "(", "{"}:
            try:
                parsed = ast.literal_eval(text)
            except Exception:
                parsed = None
            if parsed is not None and parsed is not value:
                return _native_variable_names(parsed)
        raw_parts = re.split(r"[\s,;]+", text)
    elif isinstance(value, (list, tuple, set)):
        names: list[str] = []
        for item in value:
            names.extend(_native_variable_names(item))
        return _dedupe_preserve_order(names)
    else:
        raw_parts = [str(value)]
    names = []
    for part in raw_parts:
        name = _normalize_native_variable_name(part)
        if _compact_surface_attr_name(name) in {"", "none", "empty", "enpty"}:
            continue
        names.append(name)
    return _dedupe_preserve_order(names)


def _parse_float_sequence_text(text: str) -> list[float]:
    raw = str(text or "").strip()
    if not raw:
        return []
    parsed = None
    if raw[0:1] in {"[", "(", "{"}:
        try:
            parsed = ast.literal_eval(raw)
        except Exception:
            parsed = None
    if parsed is not None:
        if isinstance(parsed, (int, float)):
            return [float(parsed)]
        if isinstance(parsed, (list, tuple, set)):
            return [float(item) for item in parsed]
        raise ValueError("Expected a number list.")

    values: list[float] = []
    for token in re.split(r"[\s,;]+", raw):
        token = token.strip()
        if not token:
            continue
        if ":" in token:
            parts = [part.strip() for part in token.split(":") if part.strip()]
            if len(parts) not in {2, 3}:
                raise ValueError(f"Invalid range token: {token!r}")
            start = float(parts[0])
            stop = float(parts[1])
            step = float(parts[2]) if len(parts) == 3 else (1.0 if stop >= start else -1.0)
            if abs(step) <= 1e-12:
                raise ValueError("Range step cannot be zero.")
            direction = 1.0 if step > 0 else -1.0
            current = start
            guard = 0
            while (current - stop) * direction <= 1e-9:
                values.append(float(current))
                current += step
                guard += 1
                if guard > 1000:
                    raise ValueError("Range expands to too many values.")
            continue
        values.append(float(token))
    return _dedupe_float_values(values)


def _dedupe_float_values(values: list[float], *, decimals: int = 9) -> list[float]:
    ordered: list[float] = []
    seen: set[float] = set()
    for value in values:
        numeric = float(value)
        if not np.isfinite(numeric):
            continue
        key = round(numeric, decimals)
        if key in seen:
            continue
        seen.add(key)
        ordered.append(numeric)
    return ordered


def _format_float_sequence(values: object) -> str:
    try:
        sequence = _parse_float_sequence_text(str(values)) if isinstance(values, str) else [float(item) for item in values]
    except Exception:
        return ""
    return ", ".join(f"{float(value):g}" for value in sequence)


def _dedupe_preserve_order(values: list[str]) -> list[str]:
    ordered: list[str] = []
    seen: set[str] = set()
    for value in values:
        key = _compact_surface_attr_name(value)
        if not key or key in seen:
            continue
        ordered.append(value)
        seen.add(key)
    return ordered


def _native_variable_names_from_spec(spec: dict) -> list[str]:
    attrs = _advanced_surface_attrs_from_spec(spec)
    names = _native_variable_names(attrs.get("Var"))
    if _coerce_opt_flag(spec.get("optimize_rc", spec.get("opt_rc", ""))):
        names.append("Rc")
    if _coerce_opt_flag(spec.get("optimize_thickness", spec.get("opt_thickness", ""))):
        names.append("Thickness")
    return _dedupe_preserve_order(names)


def _row_native_variable_names(row: SurfaceRow) -> list[str]:
    return _native_variable_names((row.advanced or {}).get("Var"))


def _native_variable_matches(candidate: object, parameter: object) -> bool:
    return (
        _compact_surface_attr_name(_normalize_native_variable_name(candidate))
        == _compact_surface_attr_name(_normalize_native_variable_name(parameter))
    )


def _literal_editor_text(value) -> tuple[str, bool]:
    literal = _layout_literal_value(value)
    if literal is _UNSERIALIZABLE_LAYOUT_VALUE:
        return f"<non-literal {type(value).__module__}.{type(value).__qualname__}>", False
    return pformat(literal, width=100), True


def _parse_literal_editor_text(text: str):
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return ast.literal_eval(stripped)
    except Exception:
        return stripped


def _finite_numeric_array(value) -> np.ndarray:
    arr = np.asarray(value, dtype=float)
    if arr.size == 0:
        raise ValueError("empty array")
    if not np.all(np.isfinite(arr)):
        raise ValueError("contains non-finite values")
    return arr


def _error_map_space_scalar(value) -> float:
    arr = _finite_numeric_array(value).ravel()
    if arr.size == 1:
        spacing = float(arr[0])
    else:
        positive = arr[arr > 0.0]
        if positive.size != arr.size:
            raise ValueError("SPACE entries must be positive")
        if not np.allclose(positive, float(np.median(positive)), rtol=1e-6, atol=1e-12):
            raise ValueError("SPACE must be a scalar or equal x/y spacing values")
        spacing = float(np.median(positive))
    if spacing <= 0.0:
        raise ValueError("SPACE must be positive")
    return spacing


def _error_map_arrays(value) -> tuple[np.ndarray, np.ndarray, np.ndarray, float]:
    if not isinstance(value, (list, tuple)) or len(value) != 4:
        raise ValueError("Error_map must be [X, Y, Z, SPACE]")
    x_values, y_values, z_values, space = value
    x_arr = _finite_numeric_array(x_values).astype(float, copy=False).ravel()
    y_arr = _finite_numeric_array(y_values).astype(float, copy=False).ravel()
    z_arr = _finite_numeric_array(z_values).astype(float, copy=False).ravel()
    if x_arr.size != y_arr.size or x_arr.size != z_arr.size:
        raise ValueError(f"X/Y/Z sample counts must match; got {x_arr.size}, {y_arr.size}, {z_arr.size}")
    if x_arr.size < 3:
        raise ValueError("at least three X/Y/Z samples are required")
    if not np.any(z_arr != 0.0):
        raise ValueError("Z samples are all zero; clear Error_map instead of storing a nominal zero map")
    return x_arr, y_arr, z_arr, _error_map_space_scalar(space)


def _error_map_literal(value) -> list[object]:
    x_arr, y_arr, z_arr, spacing = _error_map_arrays(value)
    return [x_arr.tolist(), y_arr.tolist(), z_arr.tolist(), spacing]


def _positive_unique_steps(values: np.ndarray) -> np.ndarray:
    unique_values = np.unique(np.asarray(values, dtype=float).ravel())
    if unique_values.size < 2:
        return np.array([], dtype=float)
    steps = np.diff(np.sort(unique_values))
    scale = max(float(np.max(np.abs(unique_values))), 1.0)
    return steps[steps > (scale * 1e-12)]


def _infer_error_map_spacing(x_values: np.ndarray, y_values: np.ndarray) -> float:
    steps = np.concatenate((_positive_unique_steps(x_values), _positive_unique_steps(y_values)))
    if steps.size == 0:
        return 1.0
    return float(np.median(steps))


def _error_map_from_xyz_columns(columns: np.ndarray, *, source: str) -> list[object]:
    arr = np.asarray(columns, dtype=float)
    if arr.ndim != 2 or arr.shape[1] < 3:
        raise ValueError(f"{source} must contain x, y, z columns")
    xyz = arr[:, :3]
    if not np.all(np.isfinite(xyz)):
        raise ValueError(f"{source} contains non-finite x/y/z values")
    spacing = _infer_error_map_spacing(xyz[:, 0], xyz[:, 1])
    return _error_map_literal([xyz[:, 0], xyz[:, 1], xyz[:, 2], spacing])


def _error_map_from_z_matrix(z_values: np.ndarray, *, source: str) -> list[object]:
    z_arr = np.asarray(z_values, dtype=float)
    if z_arr.ndim != 2:
        raise ValueError(f"{source} must be a 2D Z matrix")
    if min(z_arr.shape) < 2:
        raise ValueError(f"{source} Z matrix must have at least 2 rows and 2 columns")
    if not np.all(np.isfinite(z_arr)):
        raise ValueError(f"{source} contains non-finite Z values")
    y_indices, x_indices = np.indices(z_arr.shape, dtype=float)
    return _error_map_literal([x_indices.ravel(), y_indices.ravel(), z_arr.ravel(), 1.0])


def _npz_value(data: np.lib.npyio.NpzFile, *aliases: str):
    lower_keys = {str(key).strip().lower(): key for key in data.files}
    for alias in aliases:
        key = lower_keys.get(alias.lower())
        if key is not None:
            return data[key]
    return None


def _load_error_map_npz(path: Path) -> list[object]:
    with np.load(path, allow_pickle=False) as data:
        x_values = _npz_value(data, "X", "x", "x_values", "xvalues")
        y_values = _npz_value(data, "Y", "y", "y_values", "yvalues")
        z_values = _npz_value(data, "Z", "z", "z_values", "zvalues")
        if x_values is None or y_values is None or z_values is None:
            raise ValueError(".npz error maps must contain X, Y, and Z arrays")
        spacing = _npz_value(data, "SPACE", "space", "spacing", "pitch")
        if spacing is None:
            spacing = _infer_error_map_spacing(np.asarray(x_values, dtype=float), np.asarray(y_values, dtype=float))
        return _error_map_literal([x_values, y_values, z_values, spacing])


def _load_error_map_npy(path: Path) -> list[object]:
    arr = np.load(path, allow_pickle=False)
    if arr.dtype.fields:
        names = {str(name).strip().lower(): name for name in arr.dtype.names or ()}
        if {"x", "y", "z"}.issubset(names):
            columns = np.column_stack([arr[names["x"]], arr[names["y"]], arr[names["z"]]])
            return _error_map_from_xyz_columns(columns, source=path.name)
        raise ValueError(".npy structured arrays must have x, y, and z fields")
    data = np.asarray(arr, dtype=float)
    if data.ndim == 3 and data.shape[0] >= 3:
        spacing = _infer_error_map_spacing(data[0], data[1])
        return _error_map_literal([data[0], data[1], data[2], spacing])
    if data.ndim == 2 and data.shape[1] == 3:
        return _error_map_from_xyz_columns(data, source=path.name)
    if data.ndim == 2:
        return _error_map_from_z_matrix(data, source=path.name)
    raise ValueError(".npy error maps must be x/y/z columns, stacked X/Y/Z grids, or a 2D Z matrix")


def _first_data_line(path: Path) -> str:
    with path.open("r", encoding="utf-8-sig", errors="ignore") as handle:
        for line in handle:
            stripped = line.strip()
            if stripped and not stripped.startswith("#"):
                return stripped
    return ""


def _load_error_map_text(path: Path) -> list[object]:
    first_line = _first_data_line(path)
    if not first_line:
        raise ValueError(f"{path.name} is empty")
    delimiter = "," if "," in first_line else None
    has_header = bool(re.search(r"[A-Za-z]", first_line))
    if has_header:
        data = np.genfromtxt(path, delimiter=delimiter, names=True, comments="#", dtype=float, encoding=None)
        names = {str(name).strip().lower(): name for name in (data.dtype.names or ())}
        if not {"x", "y", "z"}.issubset(names):
            raise ValueError("headered error-map text files must include x, y, and z columns")
        if data.shape == ():
            data = np.asarray([data], dtype=data.dtype)
        columns = np.column_stack([data[names["x"]], data[names["y"]], data[names["z"]]])
        if "space" in names:
            spacing_values = np.asarray(data[names["space"]], dtype=float).ravel()
            spacing = spacing_values if spacing_values.size else _infer_error_map_spacing(columns[:, 0], columns[:, 1])
            return _error_map_literal([columns[:, 0], columns[:, 1], columns[:, 2], spacing])
        return _error_map_from_xyz_columns(columns, source=path.name)

    data = np.genfromtxt(path, delimiter=delimiter, comments="#", dtype=float)
    arr = np.asarray(data, dtype=float)
    if arr.ndim == 1:
        if arr.size < 3:
            raise ValueError(f"{path.name} must contain x/y/z columns or a 2D Z matrix")
        arr = arr.reshape(1, -1)
    if arr.ndim == 2 and arr.shape[1] == 3:
        return _error_map_from_xyz_columns(arr, source=path.name)
    if arr.ndim == 2:
        return _error_map_from_z_matrix(arr, source=path.name)
    raise ValueError(f"{path.name} must contain x/y/z columns or a 2D Z matrix")


def _load_error_map_file(path: Path | str) -> list[object]:
    resolved = Path(path).expanduser()
    suffix = resolved.suffix.lower()
    if suffix == ".npz":
        return _load_error_map_npz(resolved)
    if suffix == ".npy":
        return _load_error_map_npy(resolved)
    if suffix in {".csv", ".txt", ".dat", ".tsv"}:
        return _load_error_map_text(resolved)
    raise ValueError(f"Unsupported error-map format: {resolved.suffix or resolved.name}")


def _error_map_summary(value) -> str:
    try:
        x_arr, y_arr, z_arr, spacing = _error_map_arrays(value)
    except Exception as exc:
        return f"Invalid Error_map: {exc}"
    z_rms = float(np.sqrt(np.mean(np.square(z_arr))))
    return (
        f"{x_arr.size} samples; "
        f"X {float(np.min(x_arr)):.6g}..{float(np.max(x_arr)):.6g} mm, "
        f"Y {float(np.min(y_arr)):.6g}..{float(np.max(y_arr)):.6g} mm, "
        f"Z {float(np.min(z_arr)):.6g}..{float(np.max(z_arr)):.6g} mm, "
        f"RMS {z_rms:.6g} mm, SPACE {spacing:.6g} mm."
    )


def _validate_coating_table(value) -> list[str]:
    coating = value
    if not isinstance(coating, (list, tuple)) or len(coating) != 4:
        return ["Coating must be [R, A, W, THETA]."]
    r_table, a_table, wavelengths, angles = coating
    if all(isinstance(item, (list, tuple, np.ndarray)) and len(item) == 0 for item in coating):
        return []
    messages: list[str] = []
    try:
        r_arr = _finite_numeric_array(r_table)
        a_arr = _finite_numeric_array(a_table)
        w_arr = _finite_numeric_array(wavelengths).ravel()
        theta_arr = _finite_numeric_array(angles).ravel()
    except Exception as exc:
        return [f"Coating contains invalid numeric data: {exc}."]
    expected_shape = (theta_arr.size, w_arr.size)
    if r_arr.shape != expected_shape:
        messages.append(f"Coating R table shape {r_arr.shape} should be {expected_shape} = len(THETA) x len(W).")
    if a_arr.shape != expected_shape:
        messages.append(f"Coating A table shape {a_arr.shape} should be {expected_shape} = len(THETA) x len(W).")
    if np.any((r_arr < 0.0) | (r_arr > 1.0)):
        messages.append("Coating R values should be in [0, 1].")
    if np.any((a_arr < 0.0) | (a_arr > 1.0)):
        messages.append("Coating A values should be in [0, 1].")
    if r_arr.shape == a_arr.shape and np.any((r_arr + a_arr) > 1.0 + 1e-9):
        messages.append("Coating R + A should not exceed 1.")
    if np.any(w_arr <= 0.0):
        messages.append("Coating wavelengths must be positive microns.")
    if np.any(np.diff(w_arr) < 0.0):
        messages.append("Coating wavelengths should be sorted ascending.")
    if np.any(np.diff(theta_arr) < 0.0):
        messages.append("Coating incidence angles should be sorted ascending.")
    return messages


def _validate_coating_met(value) -> list[str]:
    try:
        coating_met = float(value)
    except Exception as exc:
        return [f"CoatingMet must be an integer metal index: {exc}."]
    if not np.isfinite(coating_met) or int(coating_met) != coating_met:
        return ["CoatingMet must be an integer metal index."]
    if coating_met < 0:
        return ["CoatingMet should not be negative."]
    return []


def _validate_drawing_properties(value) -> list[str]:
    return validate_drawing_properties(value)


def _normalize_diffuse_scatter_settings(value) -> dict[str, object]:
    settings = dict(DIFFUSE_SCATTER_DEFAULT_SETTINGS)
    if isinstance(value, dict):
        incoming = dict(value)
        if "reflectance" not in incoming:
            for alias in ("albedo", "diffuse_reflectance", "rho"):
                if alias in incoming:
                    incoming["reflectance"] = incoming.get(alias)
                    break
        if "sample_count" not in incoming:
            for alias in ("samples", "ray_count", "branch_count", "scatter_rays"):
                if alias in incoming:
                    incoming["sample_count"] = incoming.get(alias)
                    break
        if "max_scatter_angle_deg" not in incoming:
            for alias in ("cone_angle_deg", "hemisphere_angle_deg", "max_angle_deg"):
                if alias in incoming:
                    incoming["max_scatter_angle_deg"] = incoming.get(alias)
                    break
        if "max_branch_depth" not in incoming:
            for alias in ("max_scatter_depth", "max_depth"):
                if alias in incoming:
                    incoming["max_branch_depth"] = incoming.get(alias)
                    break
        if "target_surface" not in incoming:
            for alias in ("guided_target_surface", "target_surface_index", "target"):
                if alias in incoming:
                    incoming["target_surface"] = incoming.get(alias)
                    break
        if "target_radius_scale" not in incoming:
            for alias in ("guided_target_radius_scale", "target_radius_factor", "target_scale"):
                if alias in incoming:
                    incoming["target_radius_scale"] = incoming.get(alias)
                    break
        if "lobe_exponent" not in incoming:
            for alias in ("cosine_exponent", "phong_exponent", "gloss_exponent", "specular_exponent"):
                if alias in incoming:
                    incoming["lobe_exponent"] = incoming.get(alias)
                    break
        if "roughness_deg" not in incoming:
            for alias in ("sigma_deg", "sigma", "roughness", "surface_roughness_deg"):
                if alias in incoming:
                    incoming["roughness_deg"] = incoming.get(alias)
                    break
        if "backend_model" not in incoming:
            for alias in ("brdf_model", "pyscatmech_model", "backend_brdf_model"):
                if alias in incoming:
                    incoming["backend_model"] = incoming.get(alias)
                    break
        if "backend_parameters" not in incoming:
            for alias in ("brdf_parameters", "pyscatmech_parameters", "backend_params"):
                if alias in incoming:
                    incoming["backend_parameters"] = incoming.get(alias)
                    break
        settings.update(incoming)
    model = str(settings.get("model", "Lambertian") or "Lambertian").strip() or "Lambertian"
    if model.lower() in {"lambert", "lambertian diffuse", "diffuse"}:
        model = "Lambertian"
    elif model.lower() in {"cosine lobe", "cosine-lobe", "glossy", "phong", "specular lobe", "specular-lobe"}:
        model = "Cosine Lobe"
    elif model.lower() in {"oren-nayar", "oren nayar", "rough diffuse", "rough-diffuse"}:
        model = "Oren-Nayar"
    elif model.lower() in {"pyscatmech brdf", "pyscatmech", "scatmech", "brdf", "measured brdf"}:
        model = "pySCATMECH BRDF"
    backend = str(settings.get("backend", "Built-in") or "Built-in").strip() or "Built-in"
    if "pyscatmech" in backend.lower():
        backend = "pySCATMECH"
    else:
        backend = "Built-in"
    if model == "pySCATMECH BRDF":
        backend = "pySCATMECH"
    settings["model"] = model
    settings["backend"] = backend
    settings["backend_model"] = str(
        settings.get("backend_model", DIFFUSE_SCATTER_DEFAULT_SETTINGS["backend_model"])
        or DIFFUSE_SCATTER_DEFAULT_SETTINGS["backend_model"]
    ).strip() or str(DIFFUSE_SCATTER_DEFAULT_SETTINGS["backend_model"])
    try:
        settings["backend_parameters"] = normalize_pyscatmech_parameters(
            settings.get("backend_parameters", DIFFUSE_SCATTER_DEFAULT_SETTINGS["backend_parameters"])
        )
    except Exception:
        settings["backend_parameters"] = dict(DIFFUSE_SCATTER_DEFAULT_SETTINGS["backend_parameters"])
    for key in ("reflectance", "max_scatter_angle_deg", "min_branch_power"):
        try:
            settings[key] = float(settings.get(key, DIFFUSE_SCATTER_DEFAULT_SETTINGS[key]))
        except Exception:
            settings[key] = float(DIFFUSE_SCATTER_DEFAULT_SETTINGS[key])
    try:
        settings["sample_count"] = int(float(settings.get("sample_count", DIFFUSE_SCATTER_DEFAULT_SETTINGS["sample_count"])))
    except Exception:
        settings["sample_count"] = int(DIFFUSE_SCATTER_DEFAULT_SETTINGS["sample_count"])
    try:
        settings["max_branch_depth"] = int(float(settings.get("max_branch_depth", DIFFUSE_SCATTER_DEFAULT_SETTINGS["max_branch_depth"])))
    except Exception:
        settings["max_branch_depth"] = int(DIFFUSE_SCATTER_DEFAULT_SETTINGS["max_branch_depth"])
    target_value = settings.get("target_surface", None)
    target_surface = None
    if target_value is not None:
        try:
            target_text = str(target_value).strip()
            if target_text and target_text.lower() not in {"none", "auto", "off", "disabled"}:
                if target_text.upper().startswith("S"):
                    target_text = target_text[1:]
                target_text = target_text.split(":", 1)[0].strip()
                target_surface = int(float(target_text))
        except Exception:
            target_surface = None
    settings["target_surface"] = target_surface
    try:
        settings["target_radius_scale"] = float(settings.get("target_radius_scale", DIFFUSE_SCATTER_DEFAULT_SETTINGS["target_radius_scale"]))
    except Exception:
        settings["target_radius_scale"] = float(DIFFUSE_SCATTER_DEFAULT_SETTINGS["target_radius_scale"])
    try:
        settings["lobe_exponent"] = float(settings.get("lobe_exponent", DIFFUSE_SCATTER_DEFAULT_SETTINGS["lobe_exponent"]))
    except Exception:
        settings["lobe_exponent"] = float(DIFFUSE_SCATTER_DEFAULT_SETTINGS["lobe_exponent"])
    try:
        settings["roughness_deg"] = float(settings.get("roughness_deg", DIFFUSE_SCATTER_DEFAULT_SETTINGS["roughness_deg"]))
    except Exception:
        settings["roughness_deg"] = float(DIFFUSE_SCATTER_DEFAULT_SETTINGS["roughness_deg"])
    settings["reflectance"] = min(max(float(settings["reflectance"]), 0.0), 1.0)
    settings["max_scatter_angle_deg"] = min(max(float(settings["max_scatter_angle_deg"]), 0.0), 90.0)
    settings["min_branch_power"] = max(float(settings["min_branch_power"]), 0.0)
    settings["sample_count"] = max(1, min(int(settings["sample_count"]), 257))
    settings["max_branch_depth"] = max(1, min(int(settings["max_branch_depth"]), 32))
    if not np.isfinite(float(settings["target_radius_scale"])):
        settings["target_radius_scale"] = float(DIFFUSE_SCATTER_DEFAULT_SETTINGS["target_radius_scale"])
    settings["target_radius_scale"] = min(max(float(settings["target_radius_scale"]), 0.01), 4.0)
    if not np.isfinite(float(settings["lobe_exponent"])):
        settings["lobe_exponent"] = float(DIFFUSE_SCATTER_DEFAULT_SETTINGS["lobe_exponent"])
    settings["lobe_exponent"] = min(max(float(settings["lobe_exponent"]), 0.0), 10000.0)
    if not np.isfinite(float(settings["roughness_deg"])):
        settings["roughness_deg"] = float(DIFFUSE_SCATTER_DEFAULT_SETTINGS["roughness_deg"])
    settings["roughness_deg"] = min(max(float(settings["roughness_deg"]), 0.0), 90.0)
    settings["polarization"] = str(
        settings.get("polarization", DIFFUSE_SCATTER_DEFAULT_SETTINGS["polarization"])
        or DIFFUSE_SCATTER_DEFAULT_SETTINGS["polarization"]
    )
    return settings


def _validate_diffuse_scatter_settings(value) -> list[str]:
    settings = _normalize_diffuse_scatter_settings(value)
    messages: list[str] = []
    if settings["model"] not in {"Lambertian", "Cosine Lobe", "Oren-Nayar", "pySCATMECH BRDF"}:
        messages.append("DiffuseScatter supports model='Lambertian', 'Oren-Nayar', 'Cosine Lobe', or 'pySCATMECH BRDF'.")
    if not 0.0 <= float(settings["reflectance"]) <= 1.0:
        messages.append("DiffuseScatter reflectance must be in [0, 1].")
    if int(settings["sample_count"]) < 1:
        messages.append("DiffuseScatter sample_count must be at least 1.")
    if not 0.0 <= float(settings["max_scatter_angle_deg"]) <= 90.0:
        messages.append("DiffuseScatter max_scatter_angle_deg must be in [0, 90].")
    if float(settings["min_branch_power"]) < 0.0:
        messages.append("DiffuseScatter min_branch_power must not be negative.")
    if int(settings["max_branch_depth"]) < 1:
        messages.append("DiffuseScatter max_branch_depth must be at least 1.")
    if settings.get("target_surface") is not None and int(settings["target_surface"]) < 0:
        messages.append("DiffuseScatter target_surface must be None or a non-negative surface index.")
    if float(settings.get("target_radius_scale", 1.0)) <= 0.0:
        messages.append("DiffuseScatter target_radius_scale must be positive.")
    if float(settings.get("lobe_exponent", 0.0)) < 0.0:
        messages.append("DiffuseScatter lobe_exponent must not be negative.")
    if not 0.0 <= float(settings.get("roughness_deg", 0.0)) <= 90.0:
        messages.append("DiffuseScatter roughness_deg must be in [0, 90].")
    if str(settings.get("backend", "Built-in")) == "pySCATMECH" and not str(settings.get("backend_model", "")).strip():
        messages.append("DiffuseScatter backend_model is required when backend='pySCATMECH'.")
    return messages


def _diffuse_scatter_summary(value) -> str:
    settings = _normalize_diffuse_scatter_settings(value)
    target_text = "unguided" if settings.get("target_surface") is None else f"target=S{int(settings['target_surface'])}"
    model_detail = f"n={float(settings['lobe_exponent']):.6g}"
    if settings["model"] == "Oren-Nayar":
        model_detail = f"sigma={float(settings['roughness_deg']):.6g} deg"
    if settings["backend"] == "pySCATMECH":
        model_detail = f"model={settings['backend_model']}"
    return (
        f"{settings['model']} {settings['backend']}, R={float(settings['reflectance']):.6g}, "
        f"samples={int(settings['sample_count'])}, cone={float(settings['max_scatter_angle_deg']):.6g} deg, "
        f"minP={float(settings['min_branch_power']):.3g}, depth={int(settings['max_branch_depth'])}, "
        f"{model_detail}, {target_text}"
    )


def _normalize_beam_splitter_settings(value) -> dict[str, object]:
    settings = dict(BEAM_SPLITTER_DEFAULT_SETTINGS)
    if isinstance(value, dict):
        incoming = dict(value)
        if "split_mode" not in incoming and "mode" in incoming:
            mode_text = str(incoming.get("mode", "")).strip().lower()
            if mode_text in {"monte carlo", "probabilistic", "probability", "stochastic", "coating"}:
                incoming["split_mode"] = "Monte Carlo coating split"
            elif "coating" in mode_text and any(token in mode_text for token in ("deterministic", "table", "fixed")):
                incoming["split_mode"] = "Deterministic coating table"
            elif any(token in mode_text for token in ("fresnel", "polarization", "polarisation", "p/s")):
                incoming["split_mode"] = "Deterministic Fresnel P/S"
            else:
                incoming["split_mode"] = "Deterministic paths"
        if "absorption" not in incoming and "loss" in incoming:
            incoming["absorption"] = incoming.get("loss")
        if "max_branch_depth" not in incoming and "max_split_depth" in incoming:
            incoming["max_branch_depth"] = incoming.get("max_split_depth")
        if "polarization_p_fraction" not in incoming:
            for alias in ("p_polarization_fraction", "p_fraction", "pfrac", "p_power_fraction"):
                if alias in incoming:
                    incoming["polarization_p_fraction"] = incoming.get(alias)
                    break
        if "polarization_s_phase_deg" not in incoming:
            for alias in ("s_phase_deg", "jones_s_phase_deg", "polarization_phase_deg", "relative_s_phase_deg"):
                if alias in incoming:
                    incoming["polarization_s_phase_deg"] = incoming.get(alias)
                    break
        if "transmit_s_phase_deg" not in incoming:
            for alias in ("transmit_retardance_deg", "transmit_s_retardance_deg", "t_s_phase_deg"):
                if alias in incoming:
                    incoming["transmit_s_phase_deg"] = incoming.get(alias)
                    break
        if "reflect_s_phase_deg" not in incoming:
            for alias in ("reflect_retardance_deg", "reflect_s_retardance_deg", "r_s_phase_deg"):
                if alias in incoming:
                    incoming["reflect_s_phase_deg"] = incoming.get(alias)
                    break
        if "reflectance" not in incoming and "transmittance" in incoming:
            try:
                transmittance = float(incoming.get("transmittance", 0.5))
                absorption = float(incoming.get("absorption", incoming.get("loss", 0.0)))
                incoming["reflectance"] = 1.0 - transmittance - absorption
            except Exception:
                pass
        settings.update(incoming)
    mode = str(settings.get("split_mode", BEAM_SPLITTER_DEFAULT_SETTINGS["split_mode"])).strip()
    if mode == "Deterministic branches (future)":
        mode = "Deterministic paths"
    mode_key = re.sub(r"[^a-z0-9]+", "", mode.lower())
    mode_aliases = {
        "deterministiccoating": "Deterministic coating table",
        "deterministiccoatingtable": "Deterministic coating table",
        "coatingtable": "Deterministic coating table",
        "coatingtablesplit": "Deterministic coating table",
        "fresnel": "Deterministic Fresnel P/S",
        "deterministicfresnel": "Deterministic Fresnel P/S",
        "deterministicfresnelps": "Deterministic Fresnel P/S",
        "fresnelps": "Deterministic Fresnel P/S",
        "ps": "Deterministic Fresnel P/S",
        "deterministicps": "Deterministic Fresnel P/S",
        "polarization": "Deterministic Fresnel P/S",
        "polarisation": "Deterministic Fresnel P/S",
        "deterministicpolarization": "Deterministic Fresnel P/S",
        "deterministicpolarisation": "Deterministic Fresnel P/S",
        "deterministicpolarizationfresnel": "Deterministic Fresnel P/S",
        "deterministicpolarisationfresnel": "Deterministic Fresnel P/S",
        "deterministicbranches": "Deterministic paths",
        "deterministicpaths": "Deterministic paths",
        "ideal": "Deterministic paths",
        "plate": "Deterministic paths",
        "montecarlo": "Monte Carlo coating split",
        "montecarlocoatingsplit": "Monte Carlo coating split",
        "probabilistic": "Monte Carlo coating split",
        "stochastic": "Monte Carlo coating split",
    }
    mode = mode_aliases.get(mode_key, mode)
    if mode not in BEAM_SPLITTER_SPLIT_MODES:
        mode = BEAM_SPLITTER_DEFAULT_SETTINGS["split_mode"]
    settings["split_mode"] = mode
    for key in (
        "reflectance",
        "absorption",
        "polarization_p_fraction",
        "polarization_s_phase_deg",
        "transmit_phase_deg",
        "reflect_phase_deg",
        "transmit_s_phase_deg",
        "reflect_s_phase_deg",
        "min_branch_power",
    ):
        try:
            settings[key] = float(settings.get(key, BEAM_SPLITTER_DEFAULT_SETTINGS[key]))
        except Exception:
            settings[key] = float(BEAM_SPLITTER_DEFAULT_SETTINGS[key])
    try:
        settings["max_branch_depth"] = int(float(settings.get("max_branch_depth", BEAM_SPLITTER_DEFAULT_SETTINGS["max_branch_depth"])))
    except Exception:
        settings["max_branch_depth"] = int(BEAM_SPLITTER_DEFAULT_SETTINGS["max_branch_depth"])
    return settings


def _beam_splitter_uses_coating_table(settings) -> bool:
    mode = str(_normalize_beam_splitter_settings(settings)["split_mode"]).strip().lower()
    return "coating table" in mode


def _beam_splitter_uses_fresnel_polarization(settings) -> bool:
    mode = str(_normalize_beam_splitter_settings(settings)["split_mode"]).strip().lower()
    return "fresnel" in mode or "polarization" in mode or "polarisation" in mode


def _coating_table_has_data(value) -> bool:
    if _validate_coating_table(value):
        return False
    try:
        r_table, a_table, wavelengths, angles = value
        r_arr = np.asarray(r_table, dtype=float)
        a_arr = np.asarray(a_table, dtype=float)
        w_arr = np.asarray(wavelengths, dtype=float).ravel()
        theta_arr = np.asarray(angles, dtype=float).ravel()
    except Exception:
        return False
    return r_arr.size > 0 and a_arr.size > 0 and w_arr.size > 0 and theta_arr.size > 0


def _beam_splitter_coating_for_settings(settings, existing_coating=None) -> list[object]:
    normalized = _normalize_beam_splitter_settings(settings)
    if _beam_splitter_uses_coating_table(normalized) and _coating_table_has_data(existing_coating):
        return existing_coating
    return _beam_splitter_coating_from_settings(normalized)


def _validate_beam_splitter_settings(value) -> list[str]:
    settings = _normalize_beam_splitter_settings(value)
    messages: list[str] = []
    reflectance = float(settings["reflectance"])
    absorption = float(settings["absorption"])
    polarization_p_fraction = float(settings["polarization_p_fraction"])
    polarization_s_phase = float(settings["polarization_s_phase_deg"])
    transmit_s_phase = float(settings["transmit_s_phase_deg"])
    reflect_s_phase = float(settings["reflect_s_phase_deg"])
    min_branch_power = float(settings["min_branch_power"])
    max_branch_depth = int(settings["max_branch_depth"])
    if not 0.0 <= reflectance <= 1.0:
        messages.append("BeamSplitter reflectance must be in [0, 1].")
    if not 0.0 <= absorption <= 1.0:
        messages.append("BeamSplitter absorption must be in [0, 1].")
    if reflectance + absorption > 1.0 + 1e-12:
        messages.append("BeamSplitter reflectance + absorption must not exceed 1.")
    if not np.isfinite(polarization_p_fraction) or not 0.0 <= polarization_p_fraction <= 1.0:
        messages.append("BeamSplitter polarization_p_fraction must be in [0, 1].")
    if not np.isfinite(polarization_s_phase):
        messages.append("BeamSplitter polarization_s_phase_deg must be finite.")
    if not np.isfinite(transmit_s_phase):
        messages.append("BeamSplitter transmit_s_phase_deg must be finite.")
    if not np.isfinite(reflect_s_phase):
        messages.append("BeamSplitter reflect_s_phase_deg must be finite.")
    if min_branch_power < 0.0 or not np.isfinite(min_branch_power):
        messages.append("BeamSplitter min path power must be a non-negative finite value.")
    if max_branch_depth < 1:
        messages.append("BeamSplitter max path depth must be at least 1.")
    return messages


def _beam_splitter_coating_from_settings(settings) -> list[object]:
    normalized = _normalize_beam_splitter_settings(settings)
    reflectance = min(max(float(normalized["reflectance"]), 0.0), 1.0)
    absorption = min(max(float(normalized["absorption"]), 0.0), 1.0 - reflectance)
    wavelengths = [0.45, 0.55, 0.65]
    angles = [0.0, 45.0, 70.0]
    r_table = [[reflectance for _w in wavelengths] for _theta in angles]
    a_table = [[absorption for _w in wavelengths] for _theta in angles]
    return [r_table, a_table, wavelengths, angles]


def _beam_splitter_summary(value) -> str:
    settings = _normalize_beam_splitter_settings(value)
    reflectance = float(settings["reflectance"])
    absorption = float(settings["absorption"])
    transmittance = max(1.0 - reflectance - absorption, 0.0)
    prefix = "fallback " if _beam_splitter_uses_coating_table(settings) else ""
    p_fraction = float(settings["polarization_p_fraction"])
    s_phase = float(settings["polarization_s_phase_deg"])
    transmit_s_phase = float(settings["transmit_s_phase_deg"])
    reflect_s_phase = float(settings["reflect_s_phase_deg"])
    show_polarization = (
        _beam_splitter_uses_fresnel_polarization(settings)
        or abs(p_fraction - float(BEAM_SPLITTER_DEFAULT_SETTINGS["polarization_p_fraction"])) > 1e-12
        or abs(s_phase) > 1e-12
        or abs(transmit_s_phase) > 1e-12
        or abs(reflect_s_phase) > 1e-12
    )
    p_summary = (
        f", Pfrac={p_fraction:.3g}, Sphase={s_phase:.3g} deg, "
        f"Tret={transmit_s_phase:.3g} deg, Rret={reflect_s_phase:.3g} deg"
        if show_polarization
        else ""
    )
    return (
        f"{prefix}R/T/A={reflectance:.6g}/{transmittance:.6g}/{absorption:.6g}, "
        f"mode={settings['split_mode']}{p_summary}, minP={float(settings['min_branch_power']):.3g}, "
        f"depth={int(settings['max_branch_depth'])}"
    )


def _normalize_element_metadata(value) -> dict[str, object]:
    metadata: dict[str, object] = {
        "element_id": "",
        "element_name": "",
        "leg_id": "",
        "arm_role": ELEMENT_ARM_ROLE_DEFAULT,
        "parent_splitter": "",
        "branch_selector": "",
        "branch_path": "",
        "arm_distance": 0.0,
        "local_decenter_x": 0.0,
        "local_decenter_y": 0.0,
        "local_tilt_x": 0.0,
        "local_tilt_y": 0.0,
        "local_tilt_z": 0.0,
    }
    incoming = dict(value) if isinstance(value, dict) else {}
    metadata.update(incoming)

    role_aliases = {
        "": ELEMENT_ARM_ROLE_DEFAULT,
        "none": ELEMENT_ARM_ROLE_DEFAULT,
        "unassigned": ELEMENT_ARM_ROLE_DEFAULT,
        "common": "Common",
        "shared": "Common",
        "transmit": "Transmit",
        "transmitted": "Transmit",
        "transmission": "Transmit",
        "reflect": "Reflect",
        "reflected": "Reflect",
        "reflection": "Reflect",
        "return": "Return",
        "detector": "Detector",
        "image": "Detector",
    }
    role_key = re.sub(r"[^a-z0-9]", "", str(metadata.get("arm_role", "")).strip().lower())
    metadata["arm_role"] = role_aliases.get(role_key, ELEMENT_ARM_ROLE_DEFAULT)

    selector = str(metadata.get("branch_selector", "") or "").strip().lower()
    if selector in {"auto", "none", "default"}:
        selector = ""
    metadata["branch_selector"] = selector

    leg_id = str(metadata.get("leg_id", "") or "").strip().lower()
    if leg_id in {"auto", "none", "default"}:
        leg_id = ""
    metadata["leg_id"] = leg_id

    for key in ("element_id", "element_name", "parent_splitter", "branch_path"):
        metadata[key] = str(metadata.get(key, "") or "").strip()
    for key in ELEMENT_METADATA_NUMERIC_FIELDS:
        try:
            value_float = float(metadata.get(key, 0.0))
        except Exception:
            value_float = 0.0
        metadata[key] = value_float if np.isfinite(value_float) else 0.0
    return metadata


def _element_metadata_is_default(metadata: dict[str, object]) -> bool:
    normalized = _normalize_element_metadata(metadata)
    if str(normalized["arm_role"]) != ELEMENT_ARM_ROLE_DEFAULT:
        return False
    if any(
        str(normalized.get(key, "") or "").strip()
        for key in ("element_id", "element_name", "leg_id", "parent_splitter", "branch_selector", "branch_path")
    ):
        return False
    return all(abs(float(normalized.get(key, 0.0))) <= 1e-12 for key in ELEMENT_METADATA_NUMERIC_FIELDS)


def _element_metadata_summary(value) -> str:
    metadata = _normalize_element_metadata(value)
    role = str(metadata["arm_role"])
    selector = str(metadata.get("branch_selector", "") or "").strip()
    leg_id = str(metadata.get("leg_id", "") or "").strip()
    parent = str(metadata.get("parent_splitter", "") or "").strip()
    branch_path = str(metadata.get("branch_path", "") or "").strip()
    distance = float(metadata.get("arm_distance", 0.0))
    parts = [role]
    if leg_id:
        parts.append(f"path={leg_id}")
    if parent:
        parts.append(f"parent={parent}")
    if selector:
        parts.append(f"selector={selector}")
    if branch_path:
        parts.append(f"branch={KrakenLayoutEditor._branch_path_compact_detail(branch_path)}")
    if abs(distance) > 1e-12:
        parts.append(f"d={distance:.6g} mm")
    return ", ".join(parts)


def _normalize_detector_settings(value) -> dict[str, object]:
    settings = dict(DETECTOR_DEFAULT_SETTINGS)
    if isinstance(value, dict):
        settings.update(value)
    for key in ("active_width_mm", "active_height_mm", "pixel_pitch_um"):
        try:
            number = float(settings.get(key, 0.0))
        except Exception:
            number = 0.0
        settings[key] = max(number, 0.0) if np.isfinite(number) else 0.0
    bins = str(settings.get("bins", "") or "").strip()
    if bins.lower() in {"auto", "default", "none"}:
        bins = ""
    if bins:
        try:
            bins = str(int(np.clip(int(float(bins)), 4, 512)))
        except Exception:
            bins = ""
    settings["bins"] = bins
    return settings


def _normalize_scene_target_role(value: object) -> str:
    role = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "auto": "",
        "from_surface": "",
        "auto/from_surface": "",
        "target": "analysis_target",
        "analysis": "analysis_target",
        "analysis_target_only": "analysis_target",
        "object": "object_reference",
        "object_ref": "object_reference",
        "object_target_proxy": "object_target",
        "diffuse_object": "object_target",
    }
    role = aliases.get(role, role)
    return role if role in SCENE_TARGET_ROLE_VALUES else ""


def _normalize_scene_target_settings(value) -> dict[str, object]:
    settings = dict(SCENE_TARGET_DEFAULT_SETTINGS)
    if isinstance(value, dict):
        settings.update(value)
    settings["role"] = _normalize_scene_target_role(settings.get("role"))
    settings["label"] = str(settings.get("label", "") or "").strip()
    return settings


def _scene_target_settings_is_default(settings: dict[str, object]) -> bool:
    normalized = _normalize_scene_target_settings(settings)
    return not str(normalized.get("role", "") or "").strip() and not str(normalized.get("label", "") or "").strip()


def _normalize_scene_target_editor_kind(value: object) -> str:
    text = str(value or "").strip()
    for key, label in SCENE_TARGET_EDITOR_KIND_LABELS.items():
        if text == label:
            return key
    key = text.lower().replace("-", "_").replace(" ", "_").replace("/", "_")
    aliases = {
        "": "auto",
        "auto_from_surface": "auto",
        "auto": "auto",
        "analysis": "analysis_target",
        "analysis_target": "analysis_target",
        "target": "analysis_target",
        "scene_target": "analysis_target",
        "detector": "detector",
        "image": "detector",
        "object_target": "object_target",
        "object": "object_target",
        "diffuse": "diffuse_object",
        "diffuse_object": "diffuse_object",
        "aperture": "aperture",
    }
    return aliases.get(key, "auto")


def _scene_target_role_for_editor_kind(kind: object) -> str:
    normalized = _normalize_scene_target_editor_kind(kind)
    if normalized == "auto":
        return ""
    if normalized == "diffuse_object":
        return "object_target"
    return normalized


def _normalize_scene_normal_target_kind(value: object) -> str:
    text = str(value or "").strip()
    for key, label in SCENE_NORMAL_TARGET_LABELS.items():
        if text == label:
            return key
    key = text.lower().replace("-", "_").replace(" ", "_").replace("/", "_")
    aliases = {
        "": "detector",
        "active": "active_target",
        "active_target": "active_target",
        "analysis_target": "active_target",
        "target": "active_target",
        "targsurf": "active_target",
        "detector": "detector",
        "image": "detector",
        "sensor": "detector",
        "object": "object",
        "object_reference": "object",
        "object_target": "object",
        "diffuse_object": "object",
    }
    return aliases.get(key, "detector")


def _detector_settings_is_default(settings: dict[str, object]) -> bool:
    normalized = _normalize_detector_settings(settings)
    return (
        abs(float(normalized.get("active_width_mm", 0.0))) <= 1e-12
        and abs(float(normalized.get("active_height_mm", 0.0))) <= 1e-12
        and abs(float(normalized.get("pixel_pitch_um", 0.0))) <= 1e-12
        and not str(normalized.get("bins", "") or "").strip()
    )


def _normalize_path_filter_label(value: object) -> str:
    return normalize_branch_throughput_filter_label(value)


def _is_all_path_filter(value: object) -> bool:
    return _normalize_path_filter_label(value) == ANALYSIS_PATH_FILTER_DEFAULT


def _normalize_coherent_sum_mode(value: object) -> str:
    return normalize_coherent_sum_mode(value)


def _metal_catalog_type_for_path(path: Path | str) -> int:
    try:
        with Path(path).expanduser().open("r", encoding="utf-8", errors="ignore") as handle:
            for _ in range(8):
                line = handle.readline()
                if not line:
                    break
                if line.strip().lower() == "wl,n":
                    return 1
    except Exception:
        pass
    return 0


def _normalize_metal_catalog_specs(value) -> list[dict[str, object]]:
    if not isinstance(value, (list, tuple)):
        return []
    normalized: list[dict[str, object]] = []
    seen: set[tuple[str, str]] = set()
    for item in value:
        if isinstance(item, dict):
            path_value = item.get("path", item.get("file", item.get("filename", "")))
            name_value = item.get("name", "")
            type_value = item.get("type", item.get("format", None))
        else:
            path_value = item
            name_value = ""
            type_value = None
        path_text = str(path_value or "").strip()
        if not path_text:
            continue
        path = Path(path_text).expanduser()
        name = str(name_value or path.stem).strip() or path.stem
        if path.name.lower() == DEFAULT_METAL_CATALOG_PATH.name.lower() and name.lower() == DEFAULT_METAL_CATALOG_NAME.lower():
            continue
        try:
            catalog_type = int(type_value) if type_value is not None else _metal_catalog_type_for_path(path)
        except Exception:
            catalog_type = _metal_catalog_type_for_path(path)
        catalog_type = 1 if catalog_type == 1 else 0
        token = (str(path), name.lower())
        if token in seen:
            continue
        seen.add(token)
        normalized.append({"name": name, "path": str(path), "type": catalog_type})
    return normalized


def _metal_catalog_entries(catalogs) -> list[dict[str, object]]:
    return [
        {
            "name": DEFAULT_METAL_CATALOG_NAME,
            "path": str(DEFAULT_METAL_CATALOG_PATH),
            "type": 0,
            "builtin": True,
        },
        *_normalize_metal_catalog_specs(catalogs),
    ]


def _metal_catalog_signature(catalogs) -> tuple[tuple[str, str, int], ...]:
    return tuple(
        (str(item["name"]), str(item["path"]), int(item["type"]))
        for item in _normalize_metal_catalog_specs(catalogs)
    )


def _metal_catalogs_from_row_specs(row_specs: list[dict]) -> list[dict[str, object]]:
    for spec in row_specs:
        catalogs = spec.get("_metal_catalogs")
        if catalogs is not None:
            return _normalize_metal_catalog_specs(catalogs)
    return []


def _load_metal_catalogs_into_setup(setup, catalogs) -> None:
    loaded_names = {str(name).strip().lower() for name in getattr(setup, "Name_met", [])}
    for catalog in _normalize_metal_catalog_specs(catalogs):
        path = Path(str(catalog["path"])).expanduser()
        if not path.exists():
            raise FileNotFoundError(f"Metal catalog not found: {path}")
        name = str(catalog["name"]).strip() or path.stem
        if name.lower() in loaded_names:
            continue
        setup.LoadMetal(str(path), name, int(catalog["type"]))
        loaded_names.add(name.lower())


def _available_stock_lens_catalogs() -> dict[str, Path]:
    catalogs: dict[str, Path] = {}
    for label, path in STOCK_LENS_CATALOG_SPECS:
        if path.exists():
            catalogs[label] = path
    return catalogs


def _load_stock_lens_catalog(path: Path | str) -> dict:
    resolved = str(Path(path).expanduser().resolve())
    cached = _STOCK_LENS_CATALOG_CACHE.get(resolved)
    if isinstance(cached, dict):
        return cached
    with io.StringIO() as stdout_buf, redirect_stdout(stdout_buf):
        catalog = Kos.zmf2dict([resolved])
    _STOCK_LENS_CATALOG_CACHE[resolved] = catalog
    return catalog


def _catalog_surface_keys(catalog_item: dict) -> list[str]:
    def _surface_number(key: str) -> int:
        try:
            return int(str(key).split()[-1])
        except Exception:
            return 0

    return sorted((key for key in catalog_item if str(key).startswith("SUFR")), key=_surface_number)


def _stock_lens_summary(part_number: str, catalog_item: dict) -> dict[str, object]:
    surface_keys = _catalog_surface_keys(catalog_item)
    diameters = []
    for key in surface_keys:
        try:
            diameter = float(catalog_item[key].get("Diameter", 0.0))
        except Exception:
            diameter = 0.0
        if diameter > 0.0:
            diameters.append(diameter)
    return {
        "part_number": str(part_number),
        "description": str(catalog_item.get("description", "") or "").strip(),
        "surface_count": len(surface_keys),
        "diameter": max(diameters) if diameters else 0.0,
    }


def _known_glass_names() -> set[str]:
    global _KNOWN_GLASS_NAMES_CACHE
    if _KNOWN_GLASS_NAMES_CACHE is None:
        try:
            setup = _shared_setup()
            _KNOWN_GLASS_NAMES_CACHE = {str(name).strip().upper() for name in getattr(setup, "NAMES", [])}
        except Exception:
            _KNOWN_GLASS_NAMES_CACHE = set()
    return _KNOWN_GLASS_NAMES_CACHE


def _glass_nd_vd_from_setup(glass: str) -> tuple[float, float] | None:
    try:
        setup = _shared_setup()
        names = np.asarray(getattr(setup, "NAMES", []))
        wanted = str(glass).strip().upper()
        for index, name in enumerate(names):
            if str(name).strip().upper() != wanted:
                continue
            nm = list(getattr(setup, "NM", [])[index])
            if len(nm) >= 4:
                return float(nm[2]), float(nm[3])
    except Exception:
        return None
    return None


def _stock_lens_trace_glass(glass: str, catalog_surface: dict) -> tuple[str, str | None]:
    glass_text = str(glass or "AIR").strip()
    if not glass_text:
        return "AIR", None
    compact = glass_text.split(",", 1)[0].strip().upper()
    if compact in {"AIR", "MIRROR", "GRIN", "NVK", "___BLANK"}:
        return glass_text, None
    if compact in _known_glass_names():
        nd_vd = _glass_nd_vd_from_setup(compact)
        if nd_vd is not None:
            nd, vd = nd_vd
            return (
                f"nvk,{nd:.12g},{vd:.12g},0",
                f"Catalog glass {glass_text} was converted to n/V data from KrakenOS catalogs for robust stock-lens tracing.",
            )
        return glass_text, None
    refractive_index = catalog_surface.get("Refractive_index")
    abbe_num = catalog_surface.get("Abbe_num")
    if refractive_index is not None and abbe_num is not None:
        fallback = f"___BLANK,1,0,{float(refractive_index):.12g},{float(abbe_num):.12g},0,0,0,0,0,0"
        return fallback, f"Catalog glass {glass_text} was converted to embedded ___BLANK n/V data."
    fallback = "nvk,1.5,50,0"
    return fallback, f"Catalog glass {glass_text} is not in KrakenOS glass catalogs; using approximate n=1.5, V=50."


def _validate_error_map(value) -> list[str]:
    try:
        _error_map_arrays(value)
    except Exception as exc:
        return [f"Error_map contains invalid data: {exc}."]
    return []


def _validate_custom_extra_data(value) -> list[str]:
    if value is None or (isinstance(value, str) and value == "None"):
        return []
    try:
        if np.all(np.asarray(value, dtype=object) == 0):
            return []
    except Exception:
        pass
    try:
        decoded = decode_custom_surface_value(value)
    except Exception as exc:
        return [f"ExtraData preset cannot be decoded: {exc}."]
    if isinstance(decoded, np.ndarray):
        return []
    if not isinstance(decoded, (list, tuple)) or len(decoded) != 2:
        return ["ExtraData must be a zero/default value, [callable, params], or a supported preset dict."]
    func, params = decoded
    if not callable(func):
        return ["ExtraData first item must be callable after decoding."]
    try:
        result = np.asarray(func(np.asarray([0.0, 1.0]), np.asarray([0.0, -1.0]), params), dtype=float)
    except Exception as exc:
        return [f"ExtraData callable failed a preview evaluation: {exc}."]
    if result.size == 0 or not np.all(np.isfinite(result)):
        return ["ExtraData callable returned empty or non-finite preview values."]
    return []


def _validate_uda(value) -> list[str]:
    try:
        decoded = decode_custom_surface_value(value)
    except Exception as exc:
        return [f"UDA preset cannot be decoded: {exc}."]
    if decoded is None or (isinstance(decoded, str) and decoded == "None"):
        return []
    if not isinstance(decoded, (list, tuple)) or len(decoded) != 2:
        return ["UDA must be 'None', [px, py], or a supported preset dict."]
    try:
        px = _finite_numeric_array(decoded[0]).ravel()
        py = _finite_numeric_array(decoded[1]).ravel()
    except Exception as exc:
        return [f"UDA polygon contains invalid numeric data: {exc}."]
    if px.size != py.size:
        return [f"UDA px/py length mismatch: {px.size} vs {py.size}."]
    if px.size < 4:
        return ["UDA polygon should contain at least 4 points including closure."]
    return []


def _validate_optical_solid_virtual_planes(metadata) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    warnings_out: list[str] = []
    normalized = normalize_optical_solid_face_metadata(metadata)
    planes = [plane for plane in list(normalized.get("virtual_planes", []) or []) if isinstance(plane, dict)]
    seen_ids: set[str] = set()
    for plane in planes:
        record = normalize_optical_solid_virtual_plane_record(plane)
        plane_id = str(record.get("plane_id", "") or "").strip() or "VP?"
        if plane_id in seen_ids:
            errors.append(f"OpticalSolidFaces virtual plane {plane_id} is duplicated.")
        seen_ids.add(plane_id)
        normal = np.asarray(record.get("normal", (0.0, 0.0, 1.0)), dtype=float).reshape(3)
        point = np.asarray(record.get("point", (0.0, 0.0, 0.0)), dtype=float).reshape(3)
        if not np.all(np.isfinite(point)):
            errors.append(f"OpticalSolidFaces virtual plane {plane_id} point is not finite.")
        if not np.all(np.isfinite(normal)) or float(np.linalg.norm(normal)) <= 1e-12:
            errors.append(f"OpticalSolidFaces virtual plane {plane_id} normal is not finite/non-zero.")
        if float(record.get("aperture_mm", 0.0) or 0.0) <= 0.0:
            warnings_out.append(f"OpticalSolidFaces virtual plane {plane_id} has no positive aperture; preview size may be ambiguous.")
        if _normalize_optical_solid_virtual_plane_kind(record.get("kind")) == OPTICAL_SOLID_VIRTUAL_PLANE_KIND_SPLITTER:
            source_sides = [side for side in list(record.get("source_sides", []) or []) if _normalize_optical_solid_face_side(side) != OPTICAL_SOLID_FACE_SIDE_DEFAULT]
            if len(source_sides) < 2:
                warnings_out.append(f"OpticalSolidFaces virtual plane {plane_id} has no saved source side pair.")
    return errors, warnings_out


def _validate_advanced_surface_inputs(
    advanced: dict[str, object],
    extra_data,
    uda,
) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    warnings_out: list[str] = []
    if "Coating" in advanced:
        errors.extend(_validate_coating_table(advanced["Coating"]))
    if "CoatingMet" in advanced:
        errors.extend(_validate_coating_met(advanced["CoatingMet"]))
    if DRAWING_PROPERTIES_ADVANCED_ATTR in advanced:
        errors.extend(_validate_drawing_properties(advanced[DRAWING_PROPERTIES_ADVANCED_ATTR]))
    if BEAM_SPLITTER_ADVANCED_ATTR in advanced:
        errors.extend(_validate_beam_splitter_settings(advanced[BEAM_SPLITTER_ADVANCED_ATTR]))
    if DIFFUSE_SCATTER_ADVANCED_ATTR in advanced:
        errors.extend(_validate_diffuse_scatter_settings(advanced[DIFFUSE_SCATTER_ADVANCED_ATTR]))
    if ELEMENT_ADVANCED_ATTR in advanced:
        _normalize_element_metadata(advanced[ELEMENT_ADVANCED_ATTR])
    if "OpticalSolidFaces" in advanced:
        metadata = normalize_optical_solid_face_metadata(advanced["OpticalSolidFaces"])
        functions = [
            _normalize_optical_solid_face_function(face.get("function"), legacy_role=face.get("role"))
            for face in list(metadata.get("faces", []) or [])
            if _normalize_optical_solid_face_function(face.get("function"), legacy_role=face.get("role"))
            != OPTICAL_SOLID_FACE_FUNCTION_DEFAULT
        ]
        sides = [
            _normalize_optical_solid_face_side(face.get("side_2d"))
            for face in list(metadata.get("faces", []) or [])
            if _normalize_optical_solid_face_side(face.get("side_2d")) != OPTICAL_SOLID_FACE_SIDE_DEFAULT
        ]
        if functions and not sides:
            warnings_out.append("OpticalSolidFaces has optical functions but no 2D side labels.")
        if sides and not functions:
            warnings_out.append("OpticalSolidFaces has 2D side labels but no optical functions.")
        plane_errors, plane_warnings = _validate_optical_solid_virtual_planes(metadata)
        errors.extend(plane_errors)
        warnings_out.extend(plane_warnings)
    if "Error_map" in advanced:
        errors.extend(_validate_error_map(advanced["Error_map"]))
    if "SPECIAL_SURF_FUNC" in advanced:
        value = advanced["SPECIAL_SURF_FUNC"]
        if isinstance(value, str):
            warnings_out.append("SPECIAL_SURF_FUNC is a string reference; it is preserved but not previewed.")
        elif not callable(value) and not isinstance(value, (list, tuple)):
            warnings_out.append("SPECIAL_SURF_FUNC is not callable/list-like; KrakenOS may reject it.")
    errors.extend(_validate_custom_extra_data(extra_data))
    errors.extend(_validate_uda(uda))
    return errors, warnings_out


def _read_zemax_text(path: Path) -> str:
    payload = path.read_bytes()
    for encoding in ("utf-16", "utf-8-sig", "utf-8", "latin-1"):
        try:
            text = payload.decode(encoding)
        except UnicodeDecodeError:
            continue
        if "SURF" in text and ("\n" in text or "\r" in text):
            return text
    raise ValueError(f"{path.name} does not look like a text Zemax .zmx file.")


def _zemax_float(text: str, default: float = 0.0) -> float:
    try:
        value = float(str(text).strip())
    except Exception:
        return float(default)
    if not np.isfinite(value):
        return float(default)
    return float(value)


def _zemax_round(value: float, digits: int = 10) -> float:
    if not np.isfinite(value):
        return 0.0
    rounded = round(float(value), digits)
    return 0.0 if abs(rounded) < 1e-12 else rounded


def _zemax_glass_from_tokens(tokens: list[str]) -> tuple[str, str | None]:
    if not tokens:
        return "AIR", None
    name = str(tokens[0]).strip().strip('"') or "AIR"
    compact = name.upper()
    if compact in {"AIR", "MIRROR", "GRIN", "NVK", "___BLANK"}:
        if compact == "___BLANK" and len(tokens) >= 5:
            try:
                nd = float(tokens[3])
                vd = float(tokens[4])
                if np.isfinite(nd) and np.isfinite(vd) and nd > 0.0:
                    return f"___BLANK,1,0,{nd:.12g},{vd:.12g},0,0,0,0,0,0", f"Zemax embedded glass {name} preserved as ___BLANK n/V data."
            except Exception:
                pass
        return name, None
    if compact in _known_glass_names():
        return name, None
    if len(tokens) >= 5:
        try:
            nd = float(tokens[3])
            vd = float(tokens[4])
            if np.isfinite(nd) and np.isfinite(vd) and nd > 0.0:
                return f"nvk,{nd:.12g},{vd:.12g},0", f"Zemax glass {name} converted to embedded n/V data."
        except Exception:
            pass
    return name, f"Zemax glass {name} was not found in KrakenOS catalogs and had no embedded n/V fallback."


def _load_zemax_zmx_data(path: Path) -> dict:
    """Load a sequential Zemax text prescription into Kraken layout dictionaries."""
    text = _read_zemax_text(path)
    unit_scale_by_name = {"MM": 1.0, "IN": 25.4, "CM": 10.0, "M": 1000.0}
    title = path.stem.replace("_", " ").title()
    unit_name = "MM"
    enpd = 0.0
    x_fields: list[float] = []
    y_fields: list[float] = []
    primary_wavelength_index = None
    wavelengths: dict[int, float] = {}
    surfaces: list[dict[str, object]] = []
    current: dict[str, object] | None = None

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        parts = line.split()
        key = parts[0].upper()
        if key == "NAME":
            candidate = " ".join(parts[1:]).strip()
            if candidate:
                title = candidate
            continue
        if key == "UNIT" and len(parts) > 1:
            unit_name = parts[1].upper()
            continue
        if key == "ENPD" and len(parts) > 1:
            enpd = _zemax_float(parts[1])
            continue
        if key == "XFLN":
            x_fields = [_zemax_float(value) for value in parts[1:]]
            continue
        if key == "YFLN":
            y_fields = [_zemax_float(value) for value in parts[1:]]
            continue
        if key == "PWAV" and len(parts) > 1:
            try:
                primary_wavelength_index = int(float(parts[1]))
            except Exception:
                primary_wavelength_index = None
            continue
        if key == "WAVM" and len(parts) > 2:
            try:
                wavelengths[int(float(parts[1]))] = _zemax_float(parts[2], 0.55)
            except Exception:
                pass
            continue
        if key == "SURF" and len(parts) > 1:
            if current is not None:
                surfaces.append(current)
            try:
                index = int(float(parts[1]))
            except Exception:
                index = len(surfaces)
            current = {
                "index": index,
                "stop": False,
                "type": "STANDARD",
                "curv": 0.0,
                "coni": 0.0,
                "disz": "0",
                "glass": "AIR",
                "glass_note": None,
                "diam": 0.0,
                "coating": "",
                "parms": {},
                "unsupported": [],
            }
            continue
        if current is None:
            continue
        if key == "STOP":
            current["stop"] = True
        elif key == "TYPE" and len(parts) > 1:
            current["type"] = parts[1].upper()
        elif key == "CURV" and len(parts) > 1:
            current["curv"] = _zemax_float(parts[1])
        elif key == "CONI" and len(parts) > 1:
            current["coni"] = _zemax_float(parts[1])
        elif key == "PARM" and len(parts) > 2:
            try:
                parm_index = int(float(parts[1]))
                if parm_index > 0:
                    current.setdefault("parms", {})[parm_index] = _zemax_float(parts[2])
            except Exception:
                current.setdefault("unsupported", []).append(line)
        elif key in {"XDAT", "YDAT", "SQAP", "CLAP", "OBDC", "ELIP", "APER", "TILT", "DECX", "DECY"}:
            current.setdefault("unsupported", []).append(line)
        elif key == "DISZ" and len(parts) > 1:
            current["disz"] = parts[1]
        elif key == "GLAS" and len(parts) > 1:
            glass, glass_note = _zemax_glass_from_tokens([part.strip('"') for part in parts[1:]])
            current["glass"] = glass
            current["glass_note"] = glass_note
        elif key == "COAT" and len(parts) > 1:
            current["coating"] = parts[1].strip('"')
        elif key == "DIAM" and len(parts) > 1:
            current["diam"] = _zemax_float(parts[1])
    if current is not None:
        surfaces.append(current)
    if len(surfaces) < 2:
        raise ValueError(f"No sequential SURF records were found in {path.name}. Only text .zmx prescriptions are supported.")

    unit_scale = unit_scale_by_name.get(unit_name, 1.0)
    nonzero_diameters = [2.0 * _zemax_float(str(surface.get("diam", 0.0))) * unit_scale for surface in surfaces if _zemax_float(str(surface.get("diam", 0.0))) > 0.0]
    default_diameter = _zemax_round(nonzero_diameters[0] if nonzero_diameters else 25.0)
    last_index = int(surfaces[-1].get("index", len(surfaces) - 1))
    object_at_infinity = str(surfaces[0].get("disz", "")).strip().upper().startswith("INFINITY")
    rows: list[dict[str, object]] = []
    stop_diameter = 0.0

    for surface in surfaces:
        index = int(surface.get("index", 0))
        curv = _zemax_float(str(surface.get("curv", 0.0)))
        rc = 0.0 if abs(curv) < 1e-12 else unit_scale / curv
        conic = _zemax_float(str(surface.get("coni", 0.0)))
        disz = str(surface.get("disz", "0")).strip()
        thickness = 100.0 if disz.upper().startswith("INFINITY") else _zemax_float(disz) * unit_scale
        diameter = 2.0 * _zemax_float(str(surface.get("diam", 0.0))) * unit_scale
        if diameter <= 0.0:
            diameter = default_diameter
        glass = str(surface.get("glass", "AIR") or "AIR").strip() or "AIR"
        if index == 0:
            surface_type = "Object"
            name = "Object"
            glass = "AIR"
        elif index == last_index:
            surface_type = "Image"
            name = "Image"
            glass = "AIR"
        elif bool(surface.get("stop", False)):
            surface_type = "Aperture"
            name = "Stop"
            glass = "AIR"
            stop_diameter = max(stop_diameter, diameter)
        else:
            surface_type = "Standard"
            name = f"S{index:02d} {glass}" if glass != "AIR" else f"S{index:02d} Air Gap"
        advanced: dict[str, object] = {}
        parms = surface.get("parms", {})
        if isinstance(parms, dict) and parms:
            max_parm = max(int(key) for key in parms)
            aspher = [0.0] * max(max_parm, 1)
            for parm_index, value in sorted(parms.items()):
                if int(parm_index) > 0:
                    aspher[int(parm_index) - 1] = _zemax_float(str(value))
            if any(abs(float(value)) > 1e-15 for value in aspher):
                advanced["AspherData"] = aspher
        notes = []
        coating = str(surface.get("coating", "") or "").strip()
        if coating:
            notes.append(f"Zemax coating: {coating}")
        glass_note = str(surface.get("glass_note", "") or "").strip()
        if glass_note:
            notes.append(glass_note)
        surface_type_name = str(surface.get("type", "") or "").strip().upper()
        if surface_type_name and surface_type_name != "STANDARD":
            notes.append(f"Zemax surface TYPE {surface_type_name} imported as {surface_type}.")
        unsupported = list(surface.get("unsupported", []) or [])
        if unsupported:
            notes.append("Unparsed Zemax aperture/transform data preserved in this note: " + " | ".join(str(item) for item in unsupported[:6]))
        if notes:
            advanced["Note"] = " ".join(notes)
        rows.append(
            {
                "surface": surface_type,
                "name": name,
                "rc": _zemax_round(rc),
                "k": _zemax_round(conic),
                "axicon": 0.0,
                "thickness": _zemax_round(thickness),
                "diameter": _zemax_round(diameter),
                "tilt_x": 0.0,
                "tilt_y": 0.0,
                "tilt_z": 0.0,
                "desp_x": 0.0,
                "desp_y": 0.0,
                "desp_z": 0.0,
                "axis_move": 0.0,
                "glass": glass,
                "optimize_rc": False,
                "optimize_rc_bounds": None,
                "optimize_thickness": False,
                "optimize_thickness_bounds": None,
                "advanced": advanced,
            }
        )

    primary_wavelength = wavelengths.get(primary_wavelength_index or -1)
    if primary_wavelength is None and wavelengths:
        primary_wavelength = wavelengths[min(wavelengths)]
    if primary_wavelength is None:
        primary_wavelength = 0.55
    max_field = max([abs(value) for value in [*x_fields, *y_fields]] or [0.0])
    field_count = max(len(y_fields), len(x_fields), 1)
    aperture_value = enpd * unit_scale if enpd > 0.0 else stop_diameter
    settings = {
        "object_mode": "Infinity" if object_at_infinity else "Finite",
        "display_orientation": "YZ",
        "wavelength": f"{primary_wavelength:g}",
        "ray_count": "21",
        "ray_height_factor": "0.8",
        "source_model": SOURCE_MODEL_DEFAULT,
        "pupil_pattern": PUPIL_PATTERN_DEFAULT,
        "source_radius": "5.0",
        "source_cone_angle": "0.0",
        "gaussian_input_mode": GAUSSIAN_INPUT_MODE_DEFAULT,
        "gaussian_waist_radius": "0.5",
        "gaussian_waist_offset": "0.0",
        "gaussian_beam_diameter": "1.0",
        "gaussian_full_divergence": "1.0",
        "gaussian_waist_side": GAUSSIAN_WAIST_SIDE_DEFAULT,
        "gaussian_m2": "1.0",
        "pupil_rad": "0.0",
        "pupil_theta": "0.0",
        "source_power": "1.0",
        "source_seed": "1",
        "source_x": "0.0",
        "source_y": "0.0",
        "source_z": "0.0",
        "source_l": "0.0",
        "source_m": "0.0",
        "source_n": "1.0",
        "source_angular_weight": SOURCE_ANGULAR_WEIGHT_DEFAULT,
        "analysis_surface": "Auto",
        "aperture_type": "EPD",
        "aperture_value": f"{_zemax_round(aperture_value):g}",
        "spot_view_mode": "Grid",
        "wavefront_style": WAVEFRONT_STYLE_DEFAULT,
        "tolerance_compare_view": TOLERANCE_COMPARE_VIEW_DEFAULT,
        "show_clipped_rays": True,
        "show_cardinals": True,
        "show_physical_distances": False,
        "field_type": "Angle",
        "field_value": f"{max_field:g}",
        "field_count": str(field_count),
        "atmos_plot_mode": ATMOS_PLOT_MODE_DEFAULT,
        "image_diameter_mode": "Auto",
        "trace_mode": "Auto",
        "folded_detector_policy": FOLDED_DETECTOR_POLICY_DEFAULT,
        "nonseq_target_surface": "Auto",
        "nonseq_ns_limit": "200",
        "nonseq_energy_probability": False,
        "analysis_mode": "none",
        "analysis_modes": [],
        "layout_preview_mode": "none",
        "auto_save_plot": False,
        "external_camera": "None",
        "camera_overlay_mode": "Off",
        "optimization_workers": "Auto",
        "selected_operands": ["Spot RMS"],
        "operands": {
            "Spot RMS": {"weight": "1", "target": "0", "wavelength": f"{primary_wavelength:g}", "field": "0", "surface": "Auto"},
            "MTF @ freq": {
                "weight": "1",
                "target": "0.5",
                "wavelength": f"{primary_wavelength:g}",
                "field": "0",
                "field_x": "0",
                "field_y": "0",
                "surface": "Auto",
                "frequency": "50",
                "mtf_mode": "Average",
                "mtf_algorithm": "Diffraction FFT",
            },
        },
    }
    return {"title": title, "surfaces": rows, "settings": settings, "unit": unit_name}


