    def _on_control_stack_configure(self, _event=None) -> None:
        if not hasattr(self, "control_canvas"):
            return
        self.control_canvas.configure(scrollregion=self.control_canvas.bbox("all"))

    def _on_control_canvas_configure(self, event=None) -> None:
        if not hasattr(self, "control_canvas") or not hasattr(self, "control_stack_window"):
            return
        width = self.control_canvas.winfo_width() if event is None else int(event.width)
        self.control_canvas.itemconfigure(self.control_stack_window, width=max(width, 1))

    def _on_left_panel_mousewheel(self, event=None):
        canvas = getattr(self, "control_canvas", None)
        if canvas is None or event is None:
            return None
        try:
            pointer_x = canvas.winfo_pointerx()
            pointer_y = canvas.winfo_pointery()
            canvas_x = canvas.winfo_rootx()
            canvas_y = canvas.winfo_rooty()
            inside_canvas = (
                canvas_x <= pointer_x < canvas_x + canvas.winfo_width()
                and canvas_y <= pointer_y < canvas_y + canvas.winfo_height()
            )
        except Exception:
            return None
        if not inside_canvas:
            return None
        try:
            bbox = canvas.bbox("all")
            if not bbox or int(bbox[3] - bbox[1]) <= canvas.winfo_height():
                return "break"
        except Exception:
            pass

        delta = 0
        if getattr(event, "num", None) == 4:
            delta = -1
        elif getattr(event, "num", None) == 5:
            delta = 1
        else:
            wheel_delta = int(getattr(event, "delta", 0) or 0)
            if wheel_delta:
                delta = -max(1, abs(wheel_delta) // 120) if wheel_delta > 0 else max(1, abs(wheel_delta) // 120)
        if delta:
            try:
                canvas.yview_scroll(delta, "units")
            except Exception:
                return None
            return "break"
        return None

    def _update_field_status_hint(self) -> None:
        if not hasattr(self, "status_hint_var"):
            return
        note = self.field_mode_note_var.get().strip() if hasattr(self, "field_mode_note_var") else ""
        warning = self.field_warning_var.get().strip() if hasattr(self, "field_warning_var") else ""
        summary = self.field_summary_var.get().strip() if hasattr(self, "field_summary_var") else ""
        summary = summary.replace("\n", " | ")
        sampling_note = ""
        try:
            if self._current_source_model() == SOURCE_MODEL_DEFAULT and not self._field_sampling_is_active():
                basis, unit, _span = self._field_sampling_basis_span()
                sampling_note = f"Field samples: NA while {basis} span is 0 {unit}."
        except Exception:
            sampling_note = ""
        parts = [part for part in (note, sampling_note, warning, summary) if part]
        self.status_hint_var.set("  ||  ".join(parts))

    def _main_optimization_panel(self) -> MainOptimizationPanel:
        panel = self.__dict__.get("_main_optimization_panel_instance")
        if panel is None:
            panel = MainOptimizationPanel(self, operand_specs=OPERAND_REGISTRY.values())
            self._main_optimization_panel_instance = panel
        return panel

    def _build_optimization_panel(self, parent) -> None:
        self._main_optimization_panel().build(parent)

    def _build_results_panel(self, parent) -> None:
        self._main_information_panel().build(parent)

    def _bind_deferred_refresh(self, widget: tk.Widget) -> None:
        widget.bind("<FocusIn>", self._begin_history_capture, add="+")
        widget.bind("<FocusOut>", self._mark_plot_update_pending, add="+")
        widget.bind("<Return>", self._mark_plot_update_pending, add="+")
        widget.bind("<KP_Enter>", self._mark_plot_update_pending, add="+")

    def _bind_deferred_manual_update(self, widget: tk.Widget, *, sync_fields: bool = False) -> None:
        def _on_commit(_event=None):
            if sync_fields:
                self._sync_object_controls()
            else:
                self._sync_left_mode_controls()
            self._mark_plot_update_pending()

        widget.bind("<FocusIn>", self._begin_history_capture, add="+")
        widget.bind("<FocusOut>", _on_commit, add="+")
        widget.bind("<Return>", _on_commit, add="+")
        widget.bind("<KP_Enter>", _on_commit, add="+")

    def _invalidate_preview_scene_trace(self, reason: str = "") -> None:
        self._preview_scene_trace_dirty = True
        self._last_preview_trace_signature = None
        if reason:
            try:
                self.append_debug(f"Preview trace invalidated: {reason}")
            except Exception:
                pass

    def _invalidate_optical_solid_face_assignment_trace(
        self,
        row_index: int | None = None,
        face_id: str = "",
        function: str = "",
    ) -> None:
        reason_bits = ["CAD/STL face assignment"]
        if row_index is not None:
            try:
                reason_bits.append(f"S{int(row_index)}")
            except Exception:
                pass
        face_text = str(face_id or "").strip()
        if face_text:
            reason_bits.append(face_text)
        function_text = _optical_solid_face_function_display(function) if function else ""
        if function_text:
            reason_bits.append(function_text)
        self._invalidate_preview_scene_trace(" ".join(reason_bits))
        self.last_system = None
        self.last_rays = None
        self._last_scene_bundle = None
        self._last_live_step_overlay_trace_rows = None
        self._last_live_step_overlay_trace_records = []
        self._last_live_step_overlay_scene_bundle = None
        self._live_step_overlay_trace_plan_cache = {}

    def _mark_plot_update_pending(self, _event=None) -> None:
        self._commit_history_capture()
        self._invalidate_preview_scene_trace()
        self._sync_trace_state_badge()
        if hasattr(self, "status_var"):
            self.status_var.set("Display settings changed. Click Update.")
        self._schedule_open3d_live_refresh("left panel edit")

    def _schedule_open3d_live_refresh(self, reason: str, *, delay_ms: int = 220) -> bool:
        inspector = getattr(self, "_three_d_inspector", None)
        if inspector is None:
            return False
        try:
            if not inspector.winfo_exists():
                self._three_d_inspector = None
                return False
        except Exception:
            self._three_d_inspector = None
            return False
        try:
            return bool(inspector.schedule_live_refresh(reason, delay_ms=delay_ms))
        except Exception as exc:
            self.append_debug(f"Open 3D live refresh scheduling failed: {exc}")
            return False

    def _on_display_plane_changed(self, _event=None) -> None:
        self._commit_history_capture()
        if hasattr(self, "display_orientation_var"):
            self.display_orientation_var.set(normalize_projection_plane(self.display_orientation_var.get()))
        self._sync_trace_state_badge()
        if hasattr(self, "status_var"):
            self.status_var.set("2D plane changed. Refreshing layout.")
        try:
            self.after_idle(self.refresh_plot)
        except Exception:
            self._mark_plot_update_pending()

    def _apply_operand_control_visibility(self, label: str) -> None:
        spec = self._merit_spec_for_label(label)
        if spec is None:
            return
        visible_controls = set(spec.controls)
        widget_groups = self.operand_control_widgets.get(label, {})
        for control_name, widgets in widget_groups.items():
            for widget in widgets:
                if control_name in visible_controls:
                    widget.grid()
                else:
                    widget.grid_remove()

    def _update_operand_setup_visibility(self) -> None:
        if not hasattr(self, "merit_mode_list"):
            return
        self._commit_history_capture()
        selected = {self.merit_mode_list.get(i) for i in self.merit_mode_list.curselection()}
        for label, frame in self.operand_setup_frames.items():
            visible = label in selected
            if visible:
                frame.grid()
            else:
                frame.grid_remove()

    def _pane_present(self, widget: tk.Widget) -> bool:
        if not hasattr(self, "main_pane"):
            return False
        widget_name = str(widget)
        return widget_name in {str(pane) for pane in self.main_pane.panes()}

    def toggle_left_sidebar(self) -> None:
        if not hasattr(self, "left_sidebar_host"):
            return
        if self._pane_present(self.left_sidebar_host):
            self.main_pane.forget(self.left_sidebar_host)
            self.left_restore_frame.grid()
            self._left_sidebar_collapsed = True
            message = "Left controls hidden."
        else:
            self.left_restore_frame.grid_remove()
            self.main_pane.insert(0, self.left_sidebar_host, weight=0)
            self._left_sidebar_collapsed = False
            message = "Left controls shown."
        self._initial_layout_passes = 40
        self._set_initial_pane_layout(force=True)
        if hasattr(self, "status_var"):
            self.status_var.set(message)

    def toggle_right_sidebar(self) -> None:
        if not hasattr(self, "right_sidebar_host"):
            return
        if self._pane_present(self.right_sidebar_host):
            self.main_pane.forget(self.right_sidebar_host)
            self.right_restore_frame.grid()
            self._right_sidebar_collapsed = True
            message = "Right panels hidden."
        else:
            self.right_restore_frame.grid_remove()
            self.main_pane.add(self.right_sidebar_host, weight=1)
            self._right_sidebar_collapsed = False
            message = "Right panels shown."
        self._initial_layout_passes = 40
        self._set_initial_pane_layout(force=True)
        if hasattr(self, "status_var"):
            self.status_var.set(message)

    def _set_initial_pane_layout(self, force: bool = False) -> None:
        self.update_idletasks()
        total_width = self.main_pane.winfo_width()
        if total_width < 500:
            self.after(100, self._set_initial_pane_layout)
            return
        try:
            left_visible = hasattr(self, "left_sidebar_host") and self._pane_present(self.left_sidebar_host)
            right_visible = hasattr(self, "right_sidebar_host") and self._pane_present(self.right_sidebar_host)
            left_width = max(240, min(360, int(total_width * 0.20)))
            right_width = max(300, min(460, int(total_width * 0.23)))
            if left_visible and right_visible:
                center_min = max(360, int(total_width * 0.42))
                side_total = left_width + right_width
                side_limit = max(240, total_width - center_min)
                if side_total > side_limit:
                    scale = max(0.35, side_limit / max(side_total, 1))
                    left_width = max(180, int(left_width * scale))
                    right_width = max(220, int(right_width * scale))
                self.main_pane.sashpos(0, left_width)
                self.main_pane.sashpos(1, max(left_width + 250, total_width - right_width))
            elif left_visible:
                self.main_pane.sashpos(0, left_width)
            elif right_visible:
                self.main_pane.sashpos(0, max(250, total_width - right_width))

            if hasattr(self, "center_panel"):
                total_height = self.center_panel.winfo_height()
                if total_height >= 360:
                    self.center_panel.sashpos(0, int(total_height * 0.36))
            if not force:
                self._initial_layout_passes += 1
        except Exception:
            self.after(100, self._set_initial_pane_layout)

    def _maybe_refresh_initial_pane_layout(self, _event=None) -> None:
        if self._initial_layout_passes >= 40:
            return
        self.after(100, self._set_initial_pane_layout)

    def _layout_menu_category(self, name: str) -> str:
        return layout_menu_category(name, self.layout_files.get(name))

    def _example_menu_category(self, name: str) -> str:
        return example_menu_category(name, self.example_files.get(name))

    def _refresh_selector_menus(self) -> None:
        if self.layout_menu is not None:
            self.layout_menu.delete(0, "end")
            self._layout_category_menus = []
            if self.layout_names:
                categories = {category: [] for category in LAYOUT_CATEGORY_ORDER}
                for name in self.layout_names:
                    category = self._layout_menu_category(name)
                    categories.setdefault(category, []).append(name)
                for category, names in categories.items():
                    if not names:
                        continue
                    submenu = tk.Menu(self.layout_menu, tearoff=0)
                    self._layout_category_menus.append(submenu)
                    for name in names:
                        submenu.add_command(
                            label=name,
                            command=lambda value=name: self.load_layout_by_name(value),
                        )
                    self.layout_menu.add_cascade(label=category, menu=submenu)
            else:
                self.layout_menu.add_command(label="No common layouts found", state="disabled")

        self._refresh_insert_component_menu()

        if self.machine_vision_menu is not None:
            self.machine_vision_menu.delete(0, "end")
            if self.machine_vision_names:
                for name in self.machine_vision_names:
                    self.machine_vision_menu.add_command(
                        label=name,
                        command=lambda value=name: self.load_layout_by_name(value),
                    )
            else:
                self.machine_vision_menu.add_command(label="No machine-vision layouts found", state="disabled")

        if self.example_menu is not None:
            self.example_menu.delete(0, "end")
            self._example_category_menus = []
            self._zemax_example_category_menus = []
            if self.example_names:
                categories = {category: [] for category in EXAMPLE_CATEGORY_ORDER}
                for name in self.example_names:
                    category = self._example_menu_category(name)
                    categories.setdefault(category, []).append(name)
                for category, names in categories.items():
                    if not names:
                        continue
                    submenu = tk.Menu(self.example_menu, tearoff=0)
                    self._example_category_menus.append(submenu)
                    for name in names:
                        submenu.add_command(
                            label=name,
                            command=lambda value=name: self.load_example_by_name(value),
                        )
                    self.example_menu.add_cascade(label=category, menu=submenu)
            if self.example_names and self.zemax_example_files:
                self.example_menu.add_separator()
            if self.zemax_example_files:
                self._refresh_zemax_example_menu(self.example_menu)
            elif not self.example_names:
                self.example_menu.add_command(label="No examples found", state="disabled")

    def _insertable_common_layout_names(self) -> list[str]:
        names: list[str] = []
        for name in self.layout_names:
            path = self.layout_files.get(name)
            if path is None:
                continue
            info: dict[str, object] = {}
            try:
                info = _load_python_data(path)
            except Exception:
                info = {}
            if self._is_insertable_common_layout(name, [], info):
                names.append(name)
        return sorted(names, key=str.lower)

    def _refresh_insert_component_menu(self) -> None:
        menu = self._insert_component_menu
        if menu is None:
            return
        menu.delete(0, "end")
        names = self._insertable_common_layout_names()
        if not names:
            menu.add_command(label="No insertable common components found", state="disabled")
            return
        for name in names:
            menu.add_command(
                label=name,
                command=lambda value=name: self.insert_layout_component_by_name(value),
            )

    def _refresh_zemax_example_menu(self, parent_menu: tk.Menu) -> None:
        zemax_menu = tk.Menu(parent_menu, tearoff=0)
        self._zemax_example_category_menus.append(zemax_menu)
        if not self.zemax_example_files:
            zemax_menu.add_command(label=f"No .zmx files found in {ZEMAX_ATTACHMENT_DIR}", state="disabled")
            parent_menu.add_cascade(label="Zemax Prescriptions (attachment)", menu=zemax_menu)
            return

        grouped: dict[str, list[tuple[str, Path]]] = {}
        for label, path in self.zemax_example_files.items():
            try:
                relative = path.relative_to(ZEMAX_ATTACHMENT_DIR)
            except ValueError:
                relative = Path(label)
            group = relative.parent.as_posix() if relative.parent != Path(".") else "Top Level"
            grouped.setdefault(group, []).append((relative.name, path))

        for group in sorted(grouped, key=lambda value: (value != "Top Level", value.lower())):
            submenu = tk.Menu(zemax_menu, tearoff=0)
            self._zemax_example_category_menus.append(submenu)
            for item_label, path in sorted(grouped[group], key=lambda item: item[0].lower()):
                submenu.add_command(
                    label=item_label,
                    command=lambda value=path: self.load_zemax_example_file(value),
                )
            zemax_menu.add_cascade(label=group, menu=submenu)
        parent_menu.add_cascade(label="Zemax Prescriptions (attachment)", menu=zemax_menu)

    def load_layouts(self) -> None:
        discovered = _discover_layouts(LAYOUTS_DIR, default_layout_title=DEFAULT_LAYOUT_TITLE)
        self.layout_files = dict(discovered.layout_files)
        self.machine_vision_files = dict(discovered.machine_vision_files)
        self.layout_names = list(discovered.layout_names)
        self.machine_vision_names = list(discovered.machine_vision_names)
        self.layout_var.set("Common Optical Layout")
        self.machine_vision_var.set("Machine Vision Lens")
        self._refresh_selector_menus()

    def load_examples(self) -> None:
        discovered = _discover_examples(EXAMPLES_DIR, ZEMAX_TESTING_DIR)
        self.example_files = dict(discovered.example_files)
        self.example_names = list(discovered.example_names)
        self.zemax_example_files = dict(discovered.zemax_example_files)
        self.example_var.set("Examples")
        self._refresh_selector_menus()

    def set_analysis_mode(self, mode: str) -> None:
        self.selected_analysis_modes = [] if mode == "none" else [mode]
        self.analysis_mode = self.selected_analysis_modes[0] if self.selected_analysis_modes else "none"
        self.secondary_analysis_mode = None
        self._sync_analysis_mode_buttons()
        mode_label_map = {
            "none": "2D",
            "spot": "Spot",
            "psf": "PSF",
            "psf_map": "PSFMap",
            "rms": "RMS",
            "field_curvature": "FC/Dist",
            "relative_illumination": "Illum",
            "polarization": "Polarization",
            "lateral_color": "LatClr",
            "detector_map": "DetMap",
            "coherent_detector": "CohDet",
            "branch_field": "BField",
            "diffraction_detector": "Diffr",
            "field_map": "FieldMap",
            "illum_map": "IllumMap",
            "wavefront_map": "WfeMap",
            "atmosphere": "Atmos",
            "pupil": "Pupil",
            "seidel": "Seidel",
            "wavefront": "Wavefront",
            "zernike": "Zernike",
            "interferogram": "Interferogram",
            "tolerance_compare": "TolCmp",
            "mtf": "MTF",
        }
        mode_label = mode_label_map.get(mode, mode or "2D")
        if hasattr(self, "status_var"):
            self.status_var.set(f"Analysis mode set to {mode_label}. Click Update.")
        self.append_progress(f"Mode selected: {mode_label} (pending update).")

    def set_layout_preview_mode(self, mode: str) -> None:
        self.layout_preview_mode = "none"
        if hasattr(self, "layout_preview_mode_var"):
            self.layout_preview_mode_var.set(self.layout_preview_mode)
        mode_label = "2D"
        if hasattr(self, "status_var"):
            self.status_var.set(f"Layout mode set to {mode_label}. Click Update.")
        self.append_progress(f"Layout mode selected: {mode_label} (pending update).")

    def _requested_trace_mode(self) -> str:
        trace_mode_var = self.__dict__.get("trace_mode_var")
        if trace_mode_var is None:
            value = str(self.__dict__.get("trace_mode", "Auto")).strip()
        else:
            value = str(trace_mode_var.get()).strip()
        if value in {"Auto", "Sequential", "Folded Preview", "Non-Sequential Preview"}:
            return value
        return "Auto"

    def _resolved_trace_mode(self, *, system=None) -> dict[str, object]:
        requested = self._requested_trace_mode()
        can_folded = self._can_build_folded_layout() and bool(self.rows)
        intent = resolve_trace_intent(
            self.rows,
            {
                "source_model": self._current_source_model(),
                "scene_sources": getattr(self, "layout_scene_source_specs", []),
            },
            requested=requested,
            can_folded=can_folded,
            ns_trace_available=system is None or hasattr(system, "NsTrace"),
            has_physical_source=self._current_source_model() != SOURCE_MODEL_DEFAULT,
            nonseq_energy_probability=self._current_nonseq_energy_probability(),
            nonseq_target_surface_index=self._current_nonseq_target_surface_index(),
        )
        return intent.as_dict()

    def _sync_trace_state_badge(self, trace_state: dict[str, object] | None = None) -> None:
        badge_var = self.__dict__.get("trace_state_badge_var")
        if badge_var is None:
            return
        if trace_state is None:
            try:
                trace_state = self._resolved_trace_mode(system=self.last_system)
            except Exception:
                trace_state = {"requested": self._requested_trace_mode(), "active": "Unknown"}
        requested = str(trace_state.get("requested", "Auto") or "Auto")
        active = str(trace_state.get("active", "") or "")
        if active and requested != active:
            label = f"{requested} -> {active}"
        else:
            label = active or requested
        try:
            badge_var.set(f"Scene: {label}")
        except Exception:
            pass

    def _on_trace_mode_changed(self, _event=None) -> None:
        self.trace_mode = self._requested_trace_mode()
        trace_state = self._resolved_trace_mode()
        active = str(trace_state.get("active", "Sequential"))
        self._sync_trace_state_badge(trace_state)
        if hasattr(self, "status_var"):
            self.status_var.set(f"Trace mode set to {self.trace_mode} -> {active}. Click Update.")
        self.append_progress(f"Trace mode selected: {self.trace_mode} -> {active} (pending update).")

    def _current_nonseq_ns_limit(self) -> int:
        var = self.__dict__.get("nonseq_ns_limit_var")
        try:
            value = int(float(var.get())) if var is not None else 200
        except Exception:
            value = 200
        return max(1, min(int(value), 100000))

    def _current_nonseq_energy_probability(self) -> bool:
        var = self.__dict__.get("nonseq_energy_probability_var")
        try:
            return bool(var.get()) if var is not None else False
        except Exception:
            return False

    @staticmethod
    def _normalize_folded_detector_policy_label(value: object) -> str:
        text = str(value or "").strip()
        if text in FOLDED_DETECTOR_POLICY_VALUES:
            return text
        normalized = text.lower().replace("-", " ").replace("_", " ")
        if normalized in {"display", "display path", "display compatibility", "compatibility", "legacy", "authoritative"}:
            return FOLDED_DETECTOR_POLICY_DISPLAY
        return FOLDED_DETECTOR_POLICY_DEFAULT

    def _current_folded_detector_policy_label(self) -> str:
        var = self.__dict__.get("folded_detector_policy_var")
        value = str(var.get()).strip() if var is not None else FOLDED_DETECTOR_POLICY_DEFAULT
        return self._normalize_folded_detector_policy_label(value)

    def _current_folded_detector_policy(self) -> str:
        if self._current_folded_detector_policy_label() == FOLDED_DETECTOR_POLICY_DISPLAY:
            return FOLDED_TERMINAL_POLICY_DISPLAY_COMPATIBILITY
        return FOLDED_TERMINAL_POLICY_TRACE_EVENTS

    def _folded_detector_policy_control_enabled(self) -> bool:
        try:
            trace_state = self._resolved_trace_mode()
            return bool(trace_state.get("use_folded")) or self._can_build_folded_layout()
        except Exception:
            return False

    def _current_nonseq_target_surface_index(self) -> int | None:
        var = self.__dict__.get("nonseq_target_surface_var")
        value = str(var.get()).strip() if var is not None else "Auto"
        if not value or value == "Auto":
            return None
        try:
            index = int(value.split(":", 1)[0].strip())
        except Exception:
            return None
        if 0 <= index < len(self.rows):
            return index
        return None

    def _apply_nonseq_trace_settings(self, system):
        old_energy = getattr(system, "energy_probability", 0)
        old_limit = getattr(system, "NsLimit", 200)
        old_target = getattr(system, "Targ_Surf", len(self.rows))
        try:
            system.energy_probability = 1 if self._current_nonseq_energy_probability() else 0
            system.NsLimit = self._current_nonseq_ns_limit()
            target_index = self._current_nonseq_target_surface_index()
            if target_index is None:
                if hasattr(system, "TargSurfRest"):
                    system.TargSurfRest()
                else:
                    system.Targ_Surf = getattr(system, "n", len(self.rows))
            elif hasattr(system, "TargSurf"):
                system.TargSurf(int(target_index))
            else:
                system.Targ_Surf = int(target_index) + 1
        except Exception as exc:
            self.append_debug(f"Non-sequential trace settings ignored: {_short_error_message(exc)}")

        def restore() -> None:
            try:
                system.energy_probability = old_energy
                system.NsLimit = old_limit
                system.Targ_Surf = old_target
            except Exception:
                pass

        return restore

    def _on_source_model_changed(self, _event=None) -> None:
        source_model = self._current_source_model()
        if source_model == SOURCE_MODEL_DEFAULT:
            pattern = self._current_pupil_pattern_label()
            detail = f"pupil pattern {pattern}"
            if pattern == "R-theta":
                detail = f"{detail}, r {self._current_pupil_rad():.6g}, theta {self._current_pupil_theta():.6g} deg"
        elif source_model == "Gaussian beam":
            try:
                beam = self._current_gaussian_beam_input()
                detail = (
                    f"Gaussian beam, w0 {float(beam.waist_radius_mm):.6g} mm, "
                    f"waist offset {float(beam.waist_offset_mm):.6g} mm, "
                    f"M2 {float(beam.m2):.6g}"
                )
            except Exception as exc:
                detail = f"Gaussian beam input invalid: {_short_error_message(exc)}"
        elif source_model == "Collimated disk source":
            ox, oy, oz = self._current_source_origin()
            cone_deg = self._current_source_cone_angle()
            cone_note = f", cone {cone_deg:.6g} deg" if cone_deg > 1e-12 else ""
            detail = (
                f"Collimated disk source, radius {self._current_source_radius():.6g} mm, "
                f"origin ({ox:.6g}, {oy:.6g}, {oz:.6g}) mm{cone_note}"
            )
        elif source_model == "Random point cone":
            ox, oy, oz = self._current_source_origin()
            detail = (
                f"Random point cone, cone {self._current_source_cone_angle():.6g} deg, "
                f"origin ({ox:.6g}, {oy:.6g}, {oz:.6g}) mm"
            )
        else:
            ox, oy, oz = self._current_source_origin()
            weight_note = ""
            weight = self._current_source_angular_weight()
            if source_model in {"Random circle source", "Random square source"} and weight != SOURCE_ANGULAR_WEIGHT_DEFAULT:
                weight_note = f", {weight}"
            detail = (
                f"{source_model}, radius {self._current_source_radius():.6g} mm, "
                f"cone {self._current_source_cone_angle():.6g} deg{weight_note}, "
                f"origin ({ox:.6g}, {oy:.6g}, {oz:.6g}) mm"
            )
        if hasattr(self, "status_var"):
            self.status_var.set(f"Source model set to {detail}. Click Update.")
        self._update_source_summary()
        self._sync_left_mode_controls()
        self.append_progress(f"Source model selected: {detail} (pending update).")
        self._mark_plot_update_pending()

    def _main_scene_source_manager_dialog(self) -> MainSceneSourceManagerDialog:
        dialog = self.__dict__.get("_main_scene_source_manager_dialog_instance")
        if dialog is None:
            dialog = MainSceneSourceManagerDialog(
                self,
                source_model_values=SOURCE_MODEL_VALUES,
                source_model_default=SOURCE_MODEL_DEFAULT,
                source_direction_preset_values=SOURCE_DIRECTION_PRESET_VALUES,
                source_angular_weight_default=SOURCE_ANGULAR_WEIGHT_DEFAULT,
                source_angular_weight_values=SOURCE_ANGULAR_WEIGHT_VALUES,
                source_row_order_default=SOURCE_ROW_ORDER_DEFAULT,
                source_row_order_before_object=SOURCE_ROW_ORDER_BEFORE_OBJECT,
                source_row_order_after_object=SOURCE_ROW_ORDER_AFTER_OBJECT,
                normalize_source_row_order=normalize_source_row_order,
            )
            self._main_scene_source_manager_dialog_instance = dialog
        return dialog

    def open_scene_source_manager(
        self,
        selected_source_id: str | None = None,
        *,
        aim_row_index: int | None = None,
        aim_face_id: str = "",
    ) -> None:
        self._main_scene_source_manager_dialog().open_scene_source_manager(
            selected_source_id=selected_source_id,
            aim_row_index=aim_row_index,
            aim_face_id=aim_face_id,
        )


    def toggle_analysis_mode(self, mode: str) -> None:
        current = list(self.selected_analysis_modes)
        if mode in current:
            current.remove(mode)
        else:
            current.append(mode)
            if len(current) > 2:
                current = current[-2:]
        self.selected_analysis_modes = current
        self.analysis_mode = current[0] if current else "none"
        self.secondary_analysis_mode = current[1] if len(current) > 1 else None
        self._sync_analysis_mode_buttons()
        self._sync_left_mode_controls()
        label = " + ".join(self._analysis_mode_label(m) for m in current) if current else "2D"
        if hasattr(self, "status_var"):
            self.status_var.set(f"Analysis selection set to {label}. Click Update.")
        self.append_progress(f"Analysis selection updated: {label} (pending update).")

    def _sync_analysis_mode_buttons(self) -> None:
        if hasattr(self, "layout_preview_mode_var"):
            self.layout_preview_mode_var.set(self.layout_preview_mode)
        for mode, var in getattr(self, "analysis_mode_vars", {}).items():
            var.set(mode in self.selected_analysis_modes)

    def _analysis_mode_label(self, mode: str) -> str:
        return analysis_mode_label(mode)

    def _manual_update_plot(self) -> None:
        # Commit any pending inline table edit before refreshing.
        if self.editor is not None:
            row_id = self._editor_row_id
            field = self._editor_field
            if row_id is not None and field is not None:
                self._finish_edit(row_id, field, quiet=True)
        self._sync_object_controls()
        mode = (self.layout_preview_mode or "none").strip()
        if self.selected_analysis_modes:
            mode_label = " + ".join(self._analysis_mode_label(item) for item in self.selected_analysis_modes)
        else:
            mode_label = self._analysis_mode_label(mode)
        modes_with_internal_progress = {
            "psf",
            "psf_map",
            "pupil",
            "seidel",
            "wavefront",
            "zernike",
            "field_curvature",
            "relative_illumination",
            "lateral_color",
            "field_map",
            "illum_map",
            "wavefront_map",
            "atmosphere",
            "interferogram",
            "tolerance_compare",
            "mtf",
        }
        if any(item in modes_with_internal_progress for item in self.selected_analysis_modes):
            self.append_progress(f"Display update requested ({mode_label}).")
            self.refresh_plot()
            self.append_progress(f"Display update completed ({mode_label}).")
            return
        self._begin_analysis_progress("Display update")
        self._update_analysis_progress(f"Refreshing {mode_label}", 1, 2)
        self.refresh_plot()
        self._update_analysis_progress("Rendering", 2, 2)
        self._finish_analysis_progress("Display update", success=True)

    def _open_plot_axis_once(self, target_ax) -> None:
        if target_ax not in {self.ax, self._analysis_ax, *self._analysis_axes}:
            return
        now = time.monotonic()
        if now - self._last_viewer_open_time < 0.4:
            return
        self._last_viewer_open_time = now
        self._open_high_res_plot_in_system_viewer(target_ax)

    def _plot_hover_hint_text(self, target_ax, x_display: float | None = None, y_display: float | None = None) -> str:
        if target_ax is self.ax:
            if x_display is not None and y_display is not None:
                ray_index = self._find_layout_pick_ray(float(x_display), float(y_display))
                if ray_index is not None:
                    return self._ray_terminal_hint_text(ray_index)
                row_index = self._find_layout_pick_row(float(x_display), float(y_display))
                if row_index is not None and 0 <= int(row_index) < len(self.rows):
                    row = self.rows[int(row_index)]
                    name = str(getattr(row, "name", "") or getattr(row, "surface", "") or "").strip()
                    return f"S{int(row_index)} {name}: click to select"
            return "Click surface to select, ray to inspect; empty area opens viewer"
        if target_ax is not None:
            return "Click to open in viewer"
        return ""

    def _on_plot_canvas_motion(self, event) -> None:
        target_ax = getattr(event, "inaxes", None)
        if target_ax not in self._hover_hint_artists:
            target_ax = None
        x_display = getattr(event, "x", None)
        y_display = getattr(event, "y", None)
        message = self._plot_hover_hint_text(target_ax, x_display, y_display)
        if target_ax is not None:
            self._set_hover_hint_text(target_ax, message)
        if target_ax is self.ax and message and message != self._last_plot_hover_message:
            self._last_plot_hover_message = message
            if message.startswith("Ray "):
                self.status_var.set(message)
        if target_ax is self._hover_axis:
            if hasattr(self, "canvas"):
                self.canvas.draw_idle()
            return
        self._set_hover_axis(target_ax)

    def _on_plot_canvas_leave(self, _event=None) -> None:
        self._last_plot_hover_message = ""
        self._set_hover_axis(None)

    def _on_plot_widget_click(self, event) -> str | None:
        try:
            self.canvas.draw()
            renderer = self.figure.canvas.get_renderer()
            widget = self.canvas.get_tk_widget()
            x_display = float(event.x)
            y_display = float(widget.winfo_height() - event.y)
            if self.ax is not None and self.ax in self.figure.axes:
                if self.ax.get_window_extent(renderer).contains(x_display, y_display):
                    ray_index = self._find_layout_pick_ray(x_display, y_display)
                    if ray_index is not None:
                        self._select_ray_inspector_ray(ray_index)
                        return "break"
                    row_index = self._find_layout_pick_row(x_display, y_display)
                    if row_index is not None:
                        self._select_table_row(row_index)
                        return "break"
                    self._open_plot_axis_once(self.ax)
                    return "break"
            for axis in self._analysis_axes or ([self._analysis_ax] if self._analysis_ax is not None else []):
                if axis is not None and axis in self.figure.axes:
                    if axis.get_window_extent(renderer).contains(x_display, y_display):
                        self._open_plot_axis_once(axis)
                        return "break"
        except Exception as exc:
            self.append_debug(f"Plot viewer dispatch failed: {exc}")
        return None

    @staticmethod
    def _convex_hull_2d(points: np.ndarray) -> np.ndarray:
        pts = np.asarray(points, dtype=float)
        if pts.ndim != 2 or pts.shape[1] != 2:
            return np.empty((0, 2), dtype=float)
        pts = pts[np.all(np.isfinite(pts), axis=1)]
        if pts.shape[0] <= 2:
            return pts
        pts = np.unique(np.round(pts, decimals=6), axis=0)
        if pts.shape[0] <= 2:
            return pts

        def cross(o, a, b) -> float:
            return float((a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]))

        ordered = sorted((float(x), float(y)) for x, y in pts)
        lower: list[tuple[float, float]] = []
        for p in ordered:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0.0:
                lower.pop()
            lower.append(p)
        upper: list[tuple[float, float]] = []
        for p in reversed(ordered):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0.0:
                upper.pop()
            upper.append(p)
        hull = lower[:-1] + upper[:-1]
        return np.asarray(hull, dtype=float)

    def _clear_layout_selection_overlay(self) -> None:
        for artist in self._layout_selection_artists:
            try:
                artist.remove()
            except Exception:
                pass
        self._layout_selection_artists = []

    def _project_layout_points(self, points: np.ndarray) -> np.ndarray:
        pts = np.asarray(points, dtype=float)
        if pts.ndim != 2 or pts.shape[1] < 3:
            return np.empty((0, 2), dtype=float)
        proj_x, proj_y = self._project_xy(pts[:, 2], pts[:, 1])
        return np.column_stack((proj_x, proj_y))

    def _project_layout_polyline(self, z_values, y_values) -> np.ndarray:
        z_arr = np.asarray(z_values, dtype=float).reshape(-1)
        y_arr = np.asarray(y_values, dtype=float).reshape(-1)
        if z_arr.size == 0 or y_arr.size == 0 or z_arr.size != y_arr.size:
            return np.empty((0, 2), dtype=float)
        mask = np.isfinite(z_arr) & np.isfinite(y_arr)
        if not np.any(mask):
            return np.empty((0, 2), dtype=float)
        proj_x, proj_y = self._project_xy(z_arr[mask], y_arr[mask])
        return np.column_stack((proj_x, proj_y))

    def _current_camera_model(self) -> str:
        camera_model_var = self.__dict__.get("camera_model_var")
        if camera_model_var is None:
            return CAMERA_NONE_LABEL
        name = camera_model_var.get().strip()
        return name if name == CAMERA_NONE_LABEL or camera_record(name) is not None else CAMERA_NONE_LABEL

    def _current_camera_record(self) -> dict[str, object] | None:
        return camera_record(self._current_camera_model())

    def _current_camera_front_to_sensor_mm(self) -> float:
        record = self._current_camera_record()
        if record is None:
            return 0.0
        try:
            value = float(record.get("camera_front_to_sensor_mm", 0.0))
        except Exception:
            return 0.0
        return max(value, 0.0) if np.isfinite(value) else 0.0

    def _current_external_camera_name(self) -> str:
        if not hasattr(self, "external_camera_var"):
            return "None"
        name = self.external_camera_var.get().strip()
        return name if name in EXTERNAL_CAMERA_MODELS else "None"

    def _current_external_camera_spec(self) -> dict[str, object] | None:
        return _external_camera_spec(self._current_external_camera_name())

    def _load_external_camera_mesh(self) -> pv.DataSet | None:
        _load_3d_backends()
        if pv is None:
            raise RuntimeError("PyVista is required for CAD mesh import")
        spec = self._current_external_camera_spec()
        if spec is None:
            return None
        source_path = Path(spec["path"])
        if not source_path.exists():
            raise FileNotFoundError(f"External camera file not found: {source_path}")
        solid_indices = tuple(int(index) for index in spec.get("outer_solids", ()) if isinstance(index, (int, float)))
        cache_key = f"{source_path}|{solid_indices}"
        cached = self._external_cad_mesh_cache.get(cache_key)
        if cached is not None:
            return cached.copy(deep=True)
        mesh_path = source_path
        kind = str(spec.get("kind", "")).lower()
        if kind == "step":
            if solid_indices:
                mesh_path = _cached_outer_cad_mesh_path(source_path, solid_indices)
                if not mesh_path.exists():
                    _extract_step_outer_subset_to_stl(source_path, mesh_path, solid_indices)
            else:
                mesh_path = _cached_cad_mesh_path(source_path)
                if not mesh_path.exists():
                    _convert_step_to_stl(source_path, mesh_path)
        mesh = pv.read(mesh_path)
        try:
            mesh = mesh.extract_surface().copy(deep=True)
        except Exception:
            mesh = mesh.copy(deep=True)
        self._external_cad_mesh_cache[cache_key] = mesh
        return mesh.copy(deep=True)

    def _load_external_camera_reference(self) -> dict[str, object] | None:
        spec = self._current_external_camera_spec()
        if spec is None:
            return None
        source_path = Path(spec["path"])
        if not source_path.exists():
            raise FileNotFoundError(f"External camera file not found: {source_path}")
        solid_indices = tuple(int(index) for index in spec.get("outer_solids", ()) if isinstance(index, (int, float)))
        if str(spec.get("kind", "")).lower() != "step" or not solid_indices:
            return None
        cache_key = f"{source_path}|ref|{solid_indices}"
        cached = self._external_cad_reference_cache.get(cache_key)
        if cached is not None:
            return dict(cached)
        ref_path = _cached_cad_reference_path(source_path, solid_indices)
        if ref_path.exists():
            ref_data = json.loads(ref_path.read_text(encoding="utf-8"))
        else:
            ref_data = _extract_step_reference(source_path, ref_path, solid_indices)
        self._external_cad_reference_cache[cache_key] = dict(ref_data)
        return dict(ref_data)

    def _load_external_camera_section_profile(self) -> dict[str, object] | None:
        spec = self._current_external_camera_spec()
        if spec is None:
            return None
        source_path = Path(spec["path"])
        if not source_path.exists():
            raise FileNotFoundError(f"External camera file not found: {source_path}")
        solid_indices = tuple(int(index) for index in spec.get("outer_solids", ()) if isinstance(index, (int, float)))
        if str(spec.get("kind", "")).lower() != "step" or not solid_indices:
            return None
        cache_key = f"{source_path}|section|{solid_indices}"
        cached = self._external_cad_section_cache.get(cache_key)
        if cached is not None:
            return dict(cached)
        section_path = _cached_cad_section_path(source_path, solid_indices)
        if section_path.exists():
            section_data = json.loads(section_path.read_text(encoding="utf-8"))
        else:
            section_data = _extract_step_section_profile(source_path, section_path, solid_indices)
        self._external_cad_section_cache[cache_key] = dict(section_data)
        return dict(section_data)

    def _current_image_plane_z(self) -> float:
        if not self.rows:
            return 0.0
        z_pos = 0.0
        for row in self.rows[:-1]:
            z_pos += float(row.thickness)
        return z_pos + float(self.rows[-1].desp_z) if self.rows[-1].surface == "Image" else z_pos

    def _row_z_positions(self) -> list[float]:
        z_positions: list[float] = [0.0]
        z_pos = 0.0
        for row in self.rows[:-1]:
            z_pos += float(row.thickness)
            z_positions.append(z_pos)
        while len(z_positions) < len(self.rows):
            z_positions.append(z_pos)
        return z_positions

    def _lens_front_datum_z(self) -> float:
        z_positions = self._row_z_positions()
        for index, row in enumerate(self.rows):
            name = (row.name or "").strip().lower()
            if "front" in name and ("datum" in name or "edge" in name):
                return float(z_positions[index])
        for index, row in enumerate(self.rows):
            if row.surface not in {"Object", "Image", "Aperture"}:
                return float(z_positions[index])
        return 0.0

    def _load_step_mesh(self, source_path: Path, *, largest_component: bool = False):
        _load_3d_backends()
        if pv is None:
            raise RuntimeError("PyVista is required for STEP import")
        source_path = Path(source_path).expanduser()
        if not source_path.exists():
            raise FileNotFoundError(f"STEP file not found: {source_path}")
        cache_prefix = "step-largest" if largest_component else "step"
        cache_key = f"{cache_prefix}:{source_path.resolve()}"
        cached = self._external_cad_mesh_cache.get(cache_key)
        if cached is not None:
            return cached.copy(deep=True)
        stl_path = _cached_cad_mesh_path(source_path)
        if not stl_path.exists() or stl_path.stat().st_size <= 0:
            _convert_step_to_stl(source_path, stl_path)
        mesh = pv.read(stl_path).extract_surface(algorithm="dataset_surface").copy(deep=True)
        if largest_component:
            mesh = self._largest_connected_step_component(mesh)
        self._external_cad_mesh_cache[cache_key] = mesh.copy(deep=True)
        return mesh

    def _largest_connected_step_component(self, mesh):
        if mesh is None or int(getattr(mesh, "n_points", 0)) == 0:
            return mesh
        try:
            connected = mesh.connectivity("all")
            region_ids = np.asarray(connected.cell_data.get("RegionId", []), dtype=int)
            if region_ids.size == 0:
                return mesh
            counts = np.bincount(region_ids)
            if counts.size <= 1:
                return mesh
            largest_region = int(np.argmax(counts))
            part = connected.threshold(
                [largest_region, largest_region],
                scalars="RegionId",
                preference="cell",
            )
            part = part.extract_surface(algorithm="dataset_surface").copy(deep=True)
            if int(getattr(part, "n_points", 0)) > 0:
                self.append_debug(
                    f"STEP CAD component filter | kept region {largest_region} "
                    f"({int(counts[largest_region])}/{int(np.sum(counts))} cells)"
                )
                return part
        except Exception as exc:
            self.append_debug(f"STEP CAD component filter skipped: {exc}")
        return mesh

    def _step_primary_cylinder_axis(self, source_path: Path) -> np.ndarray | None:
        source_path = Path(source_path).expanduser()
        cache_key = f"step-axis:{source_path.resolve()}"
        cached = self._external_cad_mesh_cache.get(cache_key)
        if cached is not None:
            return np.asarray(cached, dtype=float).copy()
        try:
            from OCC.Core.BRepAdaptor import BRepAdaptor_Surface
            from OCC.Core.GeomAbs import GeomAbs_Cylinder
            from OCC.Core.STEPControl import STEPControl_Reader
            from OCC.Core.TopAbs import TopAbs_FACE
            from OCC.Core.TopExp import TopExp_Explorer
        except Exception as exc:
            self.append_debug(f"STEP cylinder-axis extraction unavailable: {exc}")
            return None
        try:
            reader = STEPControl_Reader()
            if reader.ReadFile(str(source_path)) != 1:
                return None
            reader.TransferRoots()
            shape = reader.OneShape()
            explorer = TopExp_Explorer(shape, TopAbs_FACE)
            axes: list[tuple[float, np.ndarray]] = []
            while explorer.More():
                face = explorer.Current()
                surface = BRepAdaptor_Surface(face)
                if surface.GetType() == GeomAbs_Cylinder:
                    cylinder = surface.Cylinder()
                    direction = cylinder.Axis().Direction()
                    vector = np.array([direction.X(), direction.Y(), direction.Z()], dtype=float)
                    norm = float(np.linalg.norm(vector))
                    radius = float(cylinder.Radius())
                    if norm > 1e-12 and np.isfinite(radius) and radius > 1.0:
                        axes.append((radius, vector / norm))
                explorer.Next()
            if not axes:
                return None
            reference = axes[0][1]
            weighted = np.zeros(3, dtype=float)
            for radius, vector in axes:
                if float(np.dot(reference, vector)) < 0.0:
                    vector = -vector
                weighted += max(radius, 1.0) * vector
            norm = float(np.linalg.norm(weighted))
            if norm <= 1e-12:
                return None
            axis = weighted / norm
            self._external_cad_mesh_cache[cache_key] = axis.copy()
            self.append_debug(
                "STEP CAD cylinder axis | {name} | axis=({x:.6f},{y:.6f},{z:.6f}) | cylinders={count}".format(
                    name=source_path.name,
                    x=float(axis[0]),
                    y=float(axis[1]),
                    z=float(axis[2]),
                    count=len(axes),
                )
            )
            return axis
        except Exception as exc:
            self.append_debug(f"STEP cylinder-axis extraction failed: {exc}")
            return None

    def _cad_mesh_aligned_to_optical_axis(
        self,
        mesh,
        *,
        source_axis,
        front_face: str,
        target_front_z: float,
        label: str,
        roll_deg: float = 0.0,
        x_rotation_deg: float = 0.0,
        y_rotation_deg: float = 0.0,
        axis_offset_xy: tuple[float, float] | None = None,
        placement_offset_xyz: tuple[float, float, float] | None = None,
    ):
        if mesh is None or int(getattr(mesh, "n_points", 0)) == 0:
            return None
        mesh = mesh.copy(deep=True)
        pts = np.asarray(mesh.points, dtype=float)
        if pts.ndim != 2 or pts.shape[0] == 0 or pts.shape[1] < 3:
            return None
        axis_vector = None
        try:
            vector_candidate = np.asarray(source_axis, dtype=float)
            if vector_candidate.shape == (3,):
                norm = float(np.linalg.norm(vector_candidate))
                if norm > 1e-12:
                    axis_vector = vector_candidate / norm
        except Exception:
            axis_vector = None
        axis_text = "vector" if axis_vector is not None else str(source_axis).strip().lower()
        working_pts = pts
        if axis_vector is not None:
            reference = np.array([0.0, 0.0, 1.0], dtype=float)
            if abs(float(np.dot(reference, axis_vector))) > 0.9:
                reference = np.array([0.0, 1.0, 0.0], dtype=float)
            transverse_u = np.cross(reference, axis_vector)
            transverse_u /= max(float(np.linalg.norm(transverse_u)), 1e-12)
            transverse_v = np.cross(axis_vector, transverse_u)
            transverse_v /= max(float(np.linalg.norm(transverse_v)), 1e-12)
            centered = pts - np.mean(pts, axis=0)
            working_pts = np.column_stack(
                [
                    centered @ transverse_u,
                    centered @ transverse_v,
                    centered @ axis_vector,
                ]
            )
            axis_index = 2
        elif axis_text.startswith("pca"):
            centered = pts - np.mean(pts, axis=0)
            cov = centered.T @ centered / max(int(centered.shape[0]), 1)
            eig_vals, eig_vecs = np.linalg.eigh(cov)
            order = np.argsort(eig_vals)[::-1]
            eig_vecs = eig_vecs[:, order]
            working_pts = centered @ eig_vecs
            try:
                axis_index = int(axis_text.replace("pca", "") or "0")
            except ValueError:
                axis_index = 0
            axis_index = max(0, min(axis_index, 2))
        else:
            axis_index = {"x": 0, "y": 1, "z": 2}.get(axis_text, 2)
        transverse_axes = [index for index in (0, 1, 2) if index != axis_index]
        src_min = np.min(pts, axis=0)
        src_max = np.max(pts, axis=0)
        work_min = np.min(working_pts, axis=0)
        work_max = np.max(working_pts, axis=0)
        transverse_center = 0.5 * (work_min[transverse_axes] + work_max[transverse_axes])
        optical_values = working_pts[:, axis_index]
        face = str(front_face).strip().lower()
        front_value = float(np.min(optical_values) if face == "min" else np.max(optical_values))
        aligned = np.empty_like(pts)
        aligned[:, 0] = working_pts[:, transverse_axes[0]] - float(transverse_center[0])
        aligned[:, 1] = working_pts[:, transverse_axes[1]] - float(transverse_center[1])
        if face == "min":
            aligned[:, 2] = optical_values - front_value
        else:
            aligned[:, 2] = front_value - optical_values
        offset_x = offset_y = 0.0
        if axis_offset_xy is not None:
            try:
                offset_x = float(axis_offset_xy[0])
                offset_y = float(axis_offset_xy[1])
            except Exception:
                offset_x = offset_y = 0.0
            aligned[:, 0] -= offset_x
            aligned[:, 1] -= offset_y
        try:
            x_rotation = float(x_rotation_deg)
        except Exception:
            x_rotation = 0.0
        if abs(x_rotation) > 1e-9:
            angle = np.deg2rad(x_rotation)
            cos_a = float(np.cos(angle))
            sin_a = float(np.sin(angle))
            # X flips should turn the imported component in place, not hinge it
            # around the datum/front edge used for optical placement.
            pivot_y = 0.5 * (float(np.min(aligned[:, 1])) + float(np.max(aligned[:, 1])))
            pivot_z = 0.5 * (float(np.min(aligned[:, 2])) + float(np.max(aligned[:, 2])))
            y_vals = aligned[:, 1].copy() - pivot_y
            z_vals = aligned[:, 2].copy() - pivot_z
            aligned[:, 1] = pivot_y + (cos_a * y_vals) - (sin_a * z_vals)
            aligned[:, 2] = pivot_z + (sin_a * y_vals) + (cos_a * z_vals)
        try:
            y_rotation = float(y_rotation_deg)
        except Exception:
            y_rotation = 0.0
        if abs(y_rotation) > 1e-9:
            angle = np.deg2rad(y_rotation)
            cos_a = float(np.cos(angle))
            sin_a = float(np.sin(angle))
            pivot_x = 0.5 * (float(np.min(aligned[:, 0])) + float(np.max(aligned[:, 0])))
            pivot_z = 0.5 * (float(np.min(aligned[:, 2])) + float(np.max(aligned[:, 2])))
            x_vals = aligned[:, 0].copy() - pivot_x
            z_vals = aligned[:, 2].copy() - pivot_z
            aligned[:, 0] = pivot_x + (cos_a * x_vals) + (sin_a * z_vals)
            aligned[:, 2] = pivot_z + (-sin_a * x_vals) + (cos_a * z_vals)
        try:
            roll = float(roll_deg)
        except Exception:
            roll = 0.0
        if abs(roll) > 1e-9:
            angle = np.deg2rad(roll)
            cos_a = float(np.cos(angle))
            sin_a = float(np.sin(angle))
            x_vals = aligned[:, 0].copy()
            y_vals = aligned[:, 1].copy()
            aligned[:, 0] = (cos_a * x_vals) - (sin_a * y_vals)
            aligned[:, 1] = (sin_a * x_vals) + (cos_a * y_vals)
        aligned[:, 2] += float(target_front_z)
        placement_offset = np.zeros(3, dtype=float)
        if placement_offset_xyz is not None:
            try:
                placement_offset = np.asarray(placement_offset_xyz, dtype=float).reshape(-1)[:3]
                if placement_offset.size < 3 or not np.all(np.isfinite(placement_offset)):
                    placement_offset = np.zeros(3, dtype=float)
            except Exception:
                placement_offset = np.zeros(3, dtype=float)
            aligned[:, :3] += placement_offset[:3]
        mesh.points = aligned
        try:
            axis_label = (
                "vector=({:.6f},{:.6f},{:.6f})".format(*[float(value) for value in axis_vector])
                if axis_vector is not None
                else axis_text
            )
            self.append_debug(
                "STEP CAD transform | {label} | axis={axis} | front={front} | rot_x={rot_x:.1f} | rot_y={rot_y:.1f} | roll_z={roll:.1f} | target_front_z={front_z:.3f} | "
                "axis_offset=({ox:.3f},{oy:.3f}) | placement_offset=({px:.3f},{py:.3f},{pz:.3f}) | raw_span=({sx:.3f},{sy:.3f},{sz:.3f}) | "
                "aligned_bounds=({x0:.3f},{x1:.3f},{y0:.3f},{y1:.3f},{z0:.3f},{z1:.3f})".format(
                    label=label,
                    axis=axis_label,
                    front=face,
                    rot_x=x_rotation,
                    rot_y=y_rotation,
                    roll=roll,
                    front_z=float(target_front_z),
                    ox=float(offset_x),
                    oy=float(offset_y),
                    px=float(placement_offset[0]),
                    py=float(placement_offset[1]),
                    pz=float(placement_offset[2]),
                    sx=float(src_max[0] - src_min[0]),
                    sy=float(src_max[1] - src_min[1]),
                    sz=float(src_max[2] - src_min[2]),
                    x0=float(np.min(aligned[:, 0])),
                    x1=float(np.max(aligned[:, 0])),
                    y0=float(np.min(aligned[:, 1])),
                    y1=float(np.max(aligned[:, 1])),
                    z0=float(np.min(aligned[:, 2])),
                    z1=float(np.max(aligned[:, 2])),
                )
            )
        except Exception:
            pass
        return mesh

    def _transformed_imported_lens_step_mesh(self):
        if self.imported_lens_step_path is None:
            return None
        mesh = self._load_step_mesh(
            self.imported_lens_step_path,
            largest_component=bool(getattr(self, "lens_step_largest_component_only", True)),
        )
        cylinder_axis = self._step_primary_cylinder_axis(self.imported_lens_step_path)
        return self._cad_mesh_aligned_to_optical_axis(
            mesh,
            source_axis=cylinder_axis if cylinder_axis is not None else "pca0",
            front_face="max",
            target_front_z=self._lens_front_datum_z(),
            label="Lens STEP",
            roll_deg=float(getattr(self, "lens_step_rotation_z_deg", 0.0)),
            x_rotation_deg=float(getattr(self, "lens_step_rotation_x_deg", 0.0)),
            y_rotation_deg=float(getattr(self, "lens_step_rotation_y_deg", 0.0)),
            axis_offset_xy=self._step_axis_offset_xy("lens"),
            placement_offset_xyz=self._step_placement_offset_xyz("lens"),
        )

    def _transformed_imported_optical_step_mesh(self):
        if self.imported_optical_step_path is None:
            return None
        mesh = self._load_step_mesh(self.imported_optical_step_path, largest_component=False)
        return self._cad_mesh_aligned_to_optical_axis(
            mesh,
            source_axis="z",
            front_face="min",
            target_front_z=0.0,
            label="Optical STEP",
            roll_deg=float(getattr(self, "optical_step_rotation_z_deg", 0.0)),
            x_rotation_deg=float(getattr(self, "optical_step_rotation_x_deg", 0.0)),
            y_rotation_deg=float(getattr(self, "optical_step_rotation_y_deg", 0.0)),
            axis_offset_xy=self._step_axis_offset_xy("optical"),
            placement_offset_xyz=self._step_placement_offset_xyz("optical"),
        )

    def _transformed_imported_camera_step_mesh(self):
        if self.imported_camera_step_path is None:
            return None
        mesh = self._load_step_mesh(self.imported_camera_step_path, largest_component=True)
        camera_front_z = self._current_image_plane_z() - self._current_camera_front_to_sensor_mm()
        return self._cad_mesh_aligned_to_optical_axis(
            mesh,
            source_axis="z",
            front_face="max",
            target_front_z=camera_front_z,
            label="Camera STEP",
            roll_deg=float(getattr(self, "camera_step_rotation_z_deg", 0.0)),
            x_rotation_deg=float(getattr(self, "camera_step_rotation_x_deg", 0.0)),
            y_rotation_deg=float(getattr(self, "camera_step_rotation_y_deg", 0.0)),
            axis_offset_xy=self._step_axis_offset_xy("camera"),
            placement_offset_xyz=self._step_placement_offset_xyz("camera"),
        )

    def _transformed_imported_led_step_mesh(self):
        if self.imported_led_step_path is None:
            return None
        mesh = self._load_step_mesh(self.imported_led_step_path, largest_component=False)
        return self._cad_mesh_aligned_to_optical_axis(
            mesh,
            source_axis="z",
            front_face="min",
            target_front_z=self._led_step_z_translation(),
            label="LED STEP",
            roll_deg=float(getattr(self, "led_step_rotation_z_deg", 0.0)),
            x_rotation_deg=float(getattr(self, "led_step_rotation_x_deg", 0.0)),
            y_rotation_deg=float(getattr(self, "led_step_rotation_y_deg", 0.0)),
            axis_offset_xy=self._step_axis_offset_xy("led"),
            placement_offset_xyz=self._step_placement_offset_xyz("led"),
        )

    def _transformed_external_camera_mesh(self) -> pv.DataSet | None:
        spec = self._current_external_camera_spec()
        if spec is None:
            return None
        mesh = self._load_external_camera_mesh()
        if mesh is None or int(getattr(mesh, "n_points", 0)) == 0:
            return None
        pts = np.asarray(mesh.points, dtype=float)
        if pts.size == 0:
            return None
        reference = None
        try:
            reference = self._load_external_camera_reference()
        except Exception as exc:
            self.append_debug(f"Camera CAD reference error: {exc}")
        if isinstance(reference, dict):
            ref_xy = reference.get("reference_xy")
            if isinstance(ref_xy, (list, tuple)) and len(ref_xy) >= 2:
                pts[:, 0] -= float(ref_xy[0])
                pts[:, 1] -= float(ref_xy[1])
        else:
            bounds = np.array(mesh.bounds, dtype=float)
            pts[:, 0] -= 0.5 * (bounds[0] + bounds[1])
            pts[:, 1] -= 0.5 * (bounds[2] + bounds[3])
        rotate_xyz_deg = spec.get("rotate_xyz_deg")
        if rotate_xyz_deg is not None:
            rot = _rotation_matrix_xyz(rotate_xyz_deg)
            pts = pts @ rot.T
        bounds_min = np.min(pts, axis=0)
        bounds_max = np.max(pts, axis=0)
        front_face = str(spec.get("front_face", "min")).lower()
        front_z = float(bounds_min[2] if front_face == "min" else bounds_max[2])
        image_z = self._current_image_plane_z()
        pts[:, 2] += image_z - front_z
        mesh.points = pts
        try:
            self.append_debug(
                "Camera CAD transform | model={label} | raw_bounds=({rx0:.3f},{rx1:.3f},{ry0:.3f},{ry1:.3f},{rz0:.3f},{rz1:.3f}) | "
                "shifted_bounds=({sx0:.3f},{sx1:.3f},{sy0:.3f},{sy1:.3f},{sz0:.3f},{sz1:.3f}) | image_z={iz:.3f} | front_z={fz:.3f}".format(
                    label=str(spec.get("label", self._current_external_camera_name())),
                    rx0=float(bounds_min[0]),
                    rx1=float(bounds_max[0]),
                    ry0=float(bounds_min[1]),
                    ry1=float(bounds_max[1]),
                    rz0=float(bounds_min[2]),
                    rz1=float(bounds_max[2]),
                    sx0=float(np.min(pts[:, 0])),
                    sx1=float(np.max(pts[:, 0])),
                    sy0=float(np.min(pts[:, 1])),
                    sy1=float(np.max(pts[:, 1])),
                    sz0=float(np.min(pts[:, 2])),
                    sz1=float(np.max(pts[:, 2])),
                    iz=float(image_z),
                    fz=float(front_z),
                )
            )
            if isinstance(reference, dict):
                self.append_debug(
                    "Camera CAD reference | method={method} | ref_xy=({x:.3f},{y:.3f})".format(
                        method=str(reference.get("method", "unknown")),
                        x=float(reference.get("reference_xy", [0.0, 0.0])[0]),
                        y=float(reference.get("reference_xy", [0.0, 0.0])[1]),
                    )
                )
        except Exception:
            pass
        return mesh

    def _external_camera_overlay_polylines(self) -> list[np.ndarray]:
        spec = self._current_external_camera_spec()
        if spec is None:
            return []
        try:
            section_data = self._load_external_camera_section_profile()
        except Exception as exc:
            self.append_debug(f"Camera CAD section profile error: {exc}")
            section_data = None
        if isinstance(section_data, dict):
            profile_points = np.asarray(section_data.get("profile_points", []), dtype=float)
            ref_xy = np.asarray(section_data.get("reference_xy", [0.0, 0.0]), dtype=float)
            if profile_points.ndim == 2 and profile_points.shape[0] >= 4 and profile_points.shape[1] >= 3 and ref_xy.size >= 2:
                pts = profile_points[:, :3].copy()
                pts[:, 0] -= float(ref_xy[0])
                pts[:, 1] -= float(ref_xy[1])
                rotate_xyz_deg = spec.get("rotate_xyz_deg")
                if rotate_xyz_deg is not None:
                    rot = _rotation_matrix_xyz(rotate_xyz_deg)
                    pts = pts @ rot.T
                front_face = str(spec.get("front_face", "min")).lower()
                front_z = float(np.min(pts[:, 2]) if front_face == "min" else np.max(pts[:, 2]))
                pts[:, 2] += self._current_image_plane_z() - front_z
                poly = self._project_layout_polyline(pts[:, 2], pts[:, 1])
                if int(poly.shape[0]) >= 2:
                    self.append_debug(f"Camera CAD OCC section profile used | points={int(poly.shape[0])}")
                    return [poly]
        mesh = self._transformed_external_camera_mesh()
        if mesh is None or int(getattr(mesh, "n_points", 0)) == 0:
            return []
        bounds = tuple(float(v) for v in mesh.bounds)
        mesh_pts = np.asarray(mesh.points, dtype=float)
        full_outline = _profile_from_section_points(np.column_stack((mesh_pts[:, 2], mesh_pts[:, 1])))
        if int(full_outline.shape[0]) >= 4:
            poly = self._project_layout_polyline(full_outline[:, 0], full_outline[:, 1])
            if int(poly.shape[0]) >= 2:
                self.append_debug(f"Camera CAD silhouette outline | points={int(poly.shape[0])}")
                return [poly]
        try:
            center_x = 0.5 * (bounds[0] + bounds[1])
            section = mesh.slice(normal=(1.0, 0.0, 0.0), origin=(center_x, 0.0, 0.0))
            self.append_debug(
                "Camera CAD section | center_x={cx:.3f} | bounds=({x0:.3f},{x1:.3f},{y0:.3f},{y1:.3f},{z0:.3f},{z1:.3f}) | "
                "section_points={pts} | section_cells={cells}".format(
                    cx=float(center_x),
                    x0=bounds[0],
                    x1=bounds[1],
                    y0=bounds[2],
                    y1=bounds[3],
                    z0=bounds[4],
                    z1=bounds[5],
                    pts=int(getattr(section, "n_points", 0)),
                    cells=int(getattr(section, "n_cells", 0)),
                )
            )
        except Exception:
            section = None
        if section is not None and int(getattr(section, "n_points", 0)) >= 2:
            pts = np.asarray(section.points, dtype=float)
            outline = _profile_from_section_points(np.column_stack((pts[:, 2], pts[:, 1])))
            if int(outline.shape[0]) >= 4:
                poly = self._project_layout_polyline(outline[:, 0], outline[:, 1])
                if int(poly.shape[0]) >= 2:
                    self.append_debug(f"Camera CAD section outline | points={int(poly.shape[0])}")
                    return [poly]
            self.append_debug("Camera CAD section produced no usable outline; falling back to silhouette hull.")
        pts = mesh_pts
        if pts.shape[0] < 8:
            self.append_debug("Camera CAD fallback silhouette skipped: insufficient mesh points.")
            return []
        stride = max(1, pts.shape[0] // 3000)
        yz = np.column_stack((pts[::stride, 2], pts[::stride, 1]))
        yz = yz[np.all(np.isfinite(yz), axis=1)]
        if yz.shape[0] < 3:
            return []
        hull = _convex_hull_2d(yz)
        if hull.shape[0] < 3:
            self.append_debug("Camera CAD fallback silhouette skipped: hull extraction failed.")
            return []
        hull = np.vstack([hull, hull[0]])
        poly = self._project_layout_polyline(hull[:, 0], hull[:, 1])
        if int(poly.shape[0]) >= 2:
            self.append_debug("Camera CAD fallback silhouette used.")
            return [poly]
        self.append_debug("Camera CAD fallback silhouette produced no drawable polyline.")
        return []

    def _draw_external_camera_overlay(self) -> None:
        spec = self._current_external_camera_spec()
        if spec is None:
            return
        overlay_mode = self.camera_overlay_mode_var.get().strip() if hasattr(self, "camera_overlay_mode_var") else "Rough envelope"
        if overlay_mode == "Off":
            return
        try:
            polylines = self._external_camera_overlay_polylines()
        except Exception as exc:
            self.append_debug(f"Camera CAD overlay error: {exc}")
            return
        if not polylines:
            return
        color = str(spec.get("line_color_2d", "#6b7280"))
        for poly in polylines:
            self.ax.plot(poly[:, 0], poly[:, 1], color="white", linewidth=3.6, alpha=0.94, zorder=54)
            self.ax.plot(poly[:, 0], poly[:, 1], color=color, linewidth=1.35, alpha=0.98, zorder=55)

    def _supported_lens_mech_profile(self) -> dict[str, object] | None:
        if self.current_layout_file is None:
            return None
        stem = self.current_layout_file.stem.lower()
        if stem not in {
            "machine_vision_150mm_datasheet_1x",
            "machine_vision_150mm_datasheet_0_5x",
            "machine_vision_150mm_measured",
        }:
            return None
        if len(self.rows) < 4:
            return None
        front_z = float(self.rows[0].thickness)
        rear_z = None
        z_cursor = 0.0
        for row in self.rows:
            if row.name == "Lens Rear Datum":
                rear_z = z_cursor
                break
            z_cursor += float(row.thickness)
        if rear_z is None:
            mech_length = float(self.rows[1].thickness) + float(self.rows[2].thickness)
            rear_z = front_z + mech_length
        else:
            mech_length = max(float(rear_z) - front_z, 1e-9)
        # Approximate the housing from the datasheet front/knurled/rear barrel drawing.
        z_knurl_start = front_z + 0.24 * mech_length
        z_knurl_end = front_z + 0.70 * mech_length
        z_rear_step = front_z + 0.83 * mech_length
        r_front = 21.0
        r_body = 25.0
        r_rear = 19.5
        top = np.array(
            [
                [front_z, r_front],
                [z_knurl_start, r_front],
                [z_knurl_start, r_body],
                [z_knurl_end, r_body],
                [z_knurl_end, r_front + 1.5],
                [z_rear_step, r_front + 1.5],
                [z_rear_step, r_rear],
                [rear_z, r_rear],
            ],
            dtype=float,
        )
        bottom = top[::-1].copy()
        bottom[:, 1] *= -1.0
        outline = np.vstack([top, bottom, top[:1]])
        return {
            "outline": outline,
            "knurl_start": z_knurl_start,
            "knurl_end": z_knurl_end,
            "front_z": front_z,
            "rear_z": rear_z,
            "radius": r_body,
        }

    def _draw_lens_mech_overlay(self) -> None:
        profile = self._supported_lens_mech_profile()
        if not isinstance(profile, dict):
            return
        outline = np.asarray(profile["outline"], dtype=float)
        poly = self._project_layout_polyline(outline[:, 0], outline[:, 1])
        if int(poly.shape[0]) < 2:
            return
        self.ax.plot(poly[:, 0], poly[:, 1], color="white", linewidth=4.2, alpha=0.95, zorder=54)
        self.ax.plot(poly[:, 0], poly[:, 1], color="#6b7280", linewidth=1.4, alpha=0.98, zorder=55)
        z_knurl_start = float(profile["knurl_start"])
        z_knurl_end = float(profile["knurl_end"])
        radius = float(profile["radius"])
        knurl_count = 11
        tooth_width = (z_knurl_end - z_knurl_start) / max(knurl_count * 2, 1)
        for idx in range(knurl_count):
            z0 = z_knurl_start + idx * 2.0 * tooth_width
            z1 = min(z0 + tooth_width, z_knurl_end)
            z2 = min(z1 + tooth_width, z_knurl_end)
            top_pts = self._project_layout_polyline(
                [z0, z1, z2],
                [radius - 1.6, radius, radius - 1.6],
            )
            bot_pts = self._project_layout_polyline(
                [z0, z1, z2],
                [-(radius - 1.6), -radius, -(radius - 1.6)],
            )
            if int(top_pts.shape[0]) >= 2:
                self.ax.plot(top_pts[:, 0], top_pts[:, 1], color="#9ca3af", linewidth=0.9, alpha=0.9, zorder=56)
            if int(bot_pts.shape[0]) >= 2:
                self.ax.plot(bot_pts[:, 0], bot_pts[:, 1], color="#9ca3af", linewidth=0.9, alpha=0.9, zorder=56)

    @staticmethod
    def _system_transform_list(system):
        if system is None:
            return None
        pr3d = getattr(system, "Pr3D", None)
        for owner in (pr3d, system):
            transforms = getattr(owner, "TRANS_2A", None) if owner is not None else None
            if transforms is not None:
                return transforms
        return None

    def _row_layout_polylines(self, system, row_index: int, z_pos: float) -> list[np.ndarray]:
        if not (0 <= row_index < len(self.rows)):
            return []
        row = self.rows[row_index]
        polylines: list[np.ndarray] = []
        if row.surface in {"Mirror", BEAM_SPLITTER_SURFACE}:
            half_length = max(float(row.diameter) / 2.0, 0.5)
            transforms = self._system_transform_list(system)
            if transforms is not None and row_index < len(transforms):
                try:
                    transform = np.asarray(transforms[row_index], dtype=float)
                    center = np.asarray(transform[:3, 3], dtype=float)
                    tangent = np.asarray(transform[:3, 1], dtype=float)
                    norm = float(np.linalg.norm(tangent))
                    if norm > 1e-12:
                        tangent /= norm
                        poly = np.vstack((center - tangent * half_length, center + tangent * half_length))
                        if poly.size > 0:
                            polylines.append(poly)
                            return polylines
                except Exception:
                    pass
            angle = np.deg2rad(float(row.tilt_x))
            dz = np.sin(angle) * half_length
            dy = np.cos(angle) * half_length
            center_z = z_pos + float(row.desp_z)
            center_y = float(row.desp_y)
            poly = self._project_layout_polyline(
                [center_z - dz, center_z + dz],
                [center_y - dy, center_y + dy],
            )
            if poly.size > 0:
                polylines.append(poly)
            return polylines
        if row.surface in {"Object", "Image", "Aperture"}:
            half_height = max(float(row.diameter) / 2.0, 0.5)
            if row.surface == "Aperture":
                transforms = self._system_transform_list(system)
                if transforms is not None and row_index < len(transforms):
                    try:
                        transform = np.asarray(transforms[row_index], dtype=float)
                        center = np.asarray(transform[:3, 3], dtype=float)
                        tangent = np.asarray(transform[:3, 1], dtype=float)
                        norm = float(np.linalg.norm(tangent))
                        if norm > 1e-12:
                            tangent /= norm
                            poly = np.vstack((center - tangent * half_height, center + tangent * half_height))
                            if poly.size > 0:
                                polylines.append(poly)
                                return polylines
                    except Exception:
                        pass
            center_z = z_pos + float(row.desp_z)
            center_y = float(row.desp_y)
            poly = self._project_layout_polyline(
                [center_z, center_z],
                [center_y - half_height, center_y + half_height],
            )
            if poly.size > 0:
                polylines.append(poly)
            return polylines
        if row.surface == "Thin Lens":
            transforms = self._system_transform_list(system)
            transform = None
            if transforms is not None and row_index < len(transforms):
                transform = transforms[row_index]
            poly = thin_lens_glyph_polyline(
                row,
                z_pos,
                transform=transform,
                project_fn=self._project_xy,
            )
            if poly is not None and int(poly.shape[0]) >= 2:
                return [poly]
        surface_data = getattr(system, "SDT_0", None)
        surface_tools = getattr(system, "SuTo", None)
        transforms = getattr(getattr(system, "Pr3D", None), "TRANS_2A", None)
        if surface_data is None:
            return polylines
        if row_index >= len(surface_data):
            return polylines
        surface = surface_data[row_index]
        if int(getattr(surface, "Drawing", 1)) != 1:
            return polylines
        if str(getattr(surface, "Glass", "") or "").upper() == "NULL":
            return polylines
        solid = 1 if getattr(surface, "Solid_3d_stl", "None") != "None" else 0
        if solid:
            stl_polylines = self._stl_mesh_layout_polylines(system, row_index, z_pos)
            if stl_polylines:
                return stl_polylines
        if surface_tools is not None and transforms is not None and row_index < len(transforms):
            try:
                half_height = max(float(row.diameter) / 2.0, 0.5)
                transform = np.asarray(transforms[row_index], dtype=float)
                inner_half = min(max(float(row.in_diameter) / 2.0, 0.0), max(half_height - 1e-6, 0.0))
                local_y_segments = [np.linspace(-half_height, half_height, 181, dtype=float)]
                if inner_half > 1e-6:
                    local_y_segments = []
                    if -half_height < -inner_half:
                        local_y_segments.append(np.linspace(-half_height, -inner_half, 91, dtype=float))
                    if inner_half < half_height:
                        local_y_segments.append(np.linspace(inner_half, half_height, 91, dtype=float))
                for local_y in local_y_segments:
                    if local_y.size < 2:
                        continue
                    local_x = np.zeros_like(local_y)
                    local_z = np.asarray(surface_tools.SurfaceShape(local_x, local_y, row_index), dtype=float)
                    local_pts = np.column_stack(
                        (
                            local_x,
                            local_y,
                            local_z,
                            np.ones_like(local_y),
                        )
                    )
                    world_pts = (transform @ local_pts.T).T
                    finite = np.all(np.isfinite(world_pts[:, :3]), axis=1)
                    if not np.any(finite):
                        continue
                    poly = np.asarray(world_pts[finite, :3], dtype=float)
                    if int(poly.shape[0]) >= 2:
                        polylines.append(poly)
                if polylines:
                    return polylines
            except Exception:
                pass
        surfaces = getattr(system, "AAA", None)
        try:
            surface_block_count = int(getattr(surfaces, "n_blocks", len(surfaces)))
        except Exception:
            surface_block_count = 0
        if surfaces is None or row_index >= surface_block_count:
            return polylines
        mesh = surfaces[row_index]
        edge_3d_func, filter_face_2dplot_func, _color_func = _load_display_helpers()
        if edge_3d_func is None or filter_face_2dplot_func is None:
            return polylines
        for direction in (1, -1):
            try:
                _ax, ay, az = edge_3d_func(mesh, direction, 0, 0, solid)
                az, ay = filter_face_2dplot_func(np.asarray(az, dtype=float), np.asarray(ay, dtype=float), solid)
            except Exception:
                continue
            poly = self._project_layout_polyline(az, ay)
            if int(poly.shape[0]) >= 2:
                polylines.append(poly)
        return polylines

    def _optical_solid_face_layout_polylines(self, row, z_pos: float, transform=None) -> list[np.ndarray]:
        if transform is None:
            try:
                faces = optical_solid_face_world_records(row, z_pos, assigned_only=True)
            except Exception:
                return []
        else:
            try:
                metadata = normalize_optical_solid_face_metadata(
                    getattr(row, "advanced", {}).get(OPTICAL_SOLID_FACES_ADVANCED_ATTR, {})
                )
                matrix = np.asarray(transform, dtype=float).reshape(4, 4)
            except Exception:
                return []
            faces = []
            for face in list(metadata.get("faces", []) or []):
                if not isinstance(face, dict):
                    continue
                function = _normalize_optical_solid_face_function(face.get("function"), legacy_role=face.get("role"))
                side = _normalize_optical_solid_face_side(face.get("side_2d"))
                role = _legacy_role_from_optical_solid_face_function(function)
                if (
                    role == OPTICAL_SOLID_FACE_ROLE_DEFAULT
                    and function == OPTICAL_SOLID_FACE_FUNCTION_DEFAULT
                    and side == OPTICAL_SOLID_FACE_SIDE_DEFAULT
                ):
                    continue
                centroid_local = np.asarray(_point3_tuple(face.get("centroid", (0.0, 0.0, 0.0))), dtype=float)
                normal_local = np.asarray(_unit_vector_tuple(face.get("normal", (0.0, 0.0, 1.0))), dtype=float)
                if bool(face.get("flip_normal", False)):
                    normal_local = -normal_local
                centroid_world = matrix @ np.asarray(
                    (float(centroid_local[0]), float(centroid_local[1]), float(centroid_local[2]), 1.0),
                    dtype=float,
                )
                normal_world = np.asarray(matrix[:3, :3], dtype=float) @ normal_local[:3]
                normal_norm = float(np.linalg.norm(normal_world))
                if normal_norm <= 1e-12:
                    continue
                world_face = dict(face)
                world_face["role"] = role
                world_face["function"] = function
                world_face["side_2d"] = side
                world_face["centroid_world"] = tuple(float(value) for value in centroid_world[:3])
                world_face["normal_world"] = tuple(float(value) for value in normal_world[:3] / normal_norm)
                faces.append(world_face)
        polylines: list[np.ndarray] = []
        for face in list(faces or []):
            if not isinstance(face, dict):
                continue
            function = _normalize_optical_solid_face_function(face.get("function"), legacy_role=face.get("role"))
            if function == OPTICAL_SOLID_FACE_FUNCTION_DEFAULT:
                continue
            centroid = np.asarray(face.get("centroid_world", (np.nan, np.nan, np.nan)), dtype=float).reshape(-1)
            normal = np.asarray(face.get("normal_world", (np.nan, np.nan, np.nan)), dtype=float).reshape(-1)
            if centroid.size < 3 or normal.size < 3:
                continue
            if not (np.all(np.isfinite(centroid[:3])) and np.all(np.isfinite(normal[:3]))):
                continue
            x0, y0 = self._project_xy([float(centroid[2])], [float(centroid[1])])
            x1, y1 = self._project_xy(
                [float(centroid[2] + normal[2])],
                [float(centroid[1] + normal[1])],
            )
            center = np.asarray((float(x0[0]), float(y0[0])), dtype=float)
            normal_2d = np.asarray((float(x1[0] - x0[0]), float(y1[0] - y0[0])), dtype=float)
            normal_norm = float(np.linalg.norm(normal_2d))
            if normal_norm <= 1e-12:
                continue
            tangent = np.asarray((-normal_2d[1], normal_2d[0]), dtype=float) / normal_norm
            try:
                clear_aperture = float(face.get("clear_aperture_mm", 0.0) or 0.0)
            except Exception:
                clear_aperture = 0.0
            try:
                area_length = float(np.sqrt(max(float(face.get("area_mm2", 0.0) or 0.0), 0.0)))
            except Exception:
                area_length = 0.0
            try:
                row_length = max(float(getattr(row, "diameter", 0.0) or 0.0), 1.0)
            except Exception:
                row_length = 1.0
            length = clear_aperture if clear_aperture > 1e-9 else area_length
            if length <= 1e-9:
                length = row_length
            half_length = max(0.5, min(float(length), row_length * 1.25) * 0.5)
            polylines.append(np.vstack((center - tangent * half_length, center + tangent * half_length)))
        return polylines

    def _stl_mesh_layout_polylines(self, system, row_index: int, z_pos: float) -> list[np.ndarray]:
        face_polylines: list[np.ndarray] = []
        transform = None
        runtime_transform = optical_solid_output_port_runtime_transform_override(system, self.rows, row_index)
        transforms = getattr(system, "TRANS_2A", None)
        if runtime_transform is not None:
            transform = runtime_transform
        elif transforms is not None and 0 <= row_index < len(transforms):
            try:
                transform = np.asarray(transforms[row_index], dtype=float)
            except Exception:
                transform = None
        if 0 <= row_index < len(self.rows):
            face_polylines = self._optical_solid_face_layout_polylines(self.rows[row_index], z_pos, transform=transform)
        points = None
        runtime_meshes = getattr(system, "EEE", None)
        try:
            runtime_mesh_count = len(runtime_meshes) if runtime_meshes is not None else 0
        except Exception:
            runtime_mesh_count = 0
        if runtime_meshes is not None and row_index < runtime_mesh_count:
            try:
                mesh = runtime_meshes[row_index]
                points = np.asarray(mesh.points, dtype=float)
            except Exception:
                points = None
        if points is None and runtime_transform is not None:
            try:
                row = self.rows[row_index]
                path = self._stl_path_from_row(row)
                if path is not None:
                    _fmt, triangles = _read_stl_triangle_vertices(path)
                    local_points = triangles.reshape((-1, 3))
                    local_h = np.column_stack((local_points[:, 0], local_points[:, 1], local_points[:, 2], np.ones(local_points.shape[0])))
                    world_points = (np.asarray(runtime_transform, dtype=float).reshape(4, 4) @ local_h.T).T
                    points = np.asarray(world_points[:, :3], dtype=float)
            except Exception:
                points = None
        surfaces = getattr(system, "AAA", None)
        try:
            surface_block_count = int(getattr(surfaces, "n_blocks", len(surfaces)))
        except Exception:
            surface_block_count = 0
        if points is None and surfaces is not None and row_index < surface_block_count:
            try:
                mesh = surfaces[row_index]
                points = np.asarray(mesh.points, dtype=float)
            except Exception:
                points = None
        if points is None or points.ndim != 2 or points.shape[1] < 3 or points.shape[0] < 2:
            try:
                row = self.rows[row_index]
                path = self._stl_path_from_row(row)
                if path is None:
                    return []
                _fmt, triangles = _read_stl_triangle_vertices(path)
                local_points = triangles.reshape((-1, 3))
                rotation = _rotation_matrix_from_kraken_tilts(row.tilt_x, row.tilt_y, row.tilt_z)
                points = local_points @ rotation.T
                points[:, 0] += float(row.desp_x)
                points[:, 1] += float(row.desp_y)
                points[:, 2] += float(z_pos) + float(row.desp_z)
            except Exception:
                return face_polylines
        if points.ndim != 2 or points.shape[1] < 3 or points.shape[0] < 2:
            return face_polylines
        projected = self._project_layout_polyline(points[:, 2], points[:, 1])
        hull = convex_hull_2d(projected)
        if hull.shape[0] >= 2:
            return [hull]
        return face_polylines

    # _rebuild_layout_pick_regions removed in Phase 3 — pick regions
    # are now built from the SceneBundle in refresh_plot().

    @staticmethod
    def _distance_to_polyline(point_xy: np.ndarray, polyline_xy: np.ndarray) -> float:
        return distance_to_polyline(point_xy, polyline_xy)

    def _find_layout_pick_row(self, x_display: float, y_display: float) -> int | None:
        if self.ax is None or not self._layout_pick_regions:
            return None
        return find_nearest_pick_region(
            (x_display, y_display),
            self._layout_pick_regions,
            transform_points=self.ax.transData.transform,
        )

    def _find_layout_pick_ray(self, x_display: float, y_display: float) -> int | None:
        if self.ax is None or not self._layout_ray_pick_regions:
            return None
        return find_nearest_ray_region(
            (x_display, y_display),
            self._layout_ray_pick_regions,
            transform_points=self.ax.transData.transform,
        )

    def _select_ray_inspector_ray(self, ray_index: int) -> None:
        try:
            index = int(ray_index)
        except Exception:
            return
        if self._ray_inspector_window is None or not self._ray_inspector_window.winfo_exists():
            self.open_ray_inspector()
        else:
            self._refresh_ray_inspector()
        table = self._ray_inspector_ray_table
        if table is None:
            return
        iid = str(index)
        if not table.exists(iid):
            self.status_var.set(f"Ray {index} is not available in the current Ray Inspector data.")
            return
        self._layout_selected_ray_index = index
        table.selection_set(iid)
        table.focus(iid)
        table.see(iid)
        self._populate_ray_inspector_hits()
        self._update_layout_selection_overlay()
        self.status_var.set(self._ray_terminal_hint_text(index, label=f"Selected ray {index} in Ray Inspector"))

    def _draw_layout_selected_ray_overlay(self, ray_index: int) -> bool:
        ray = self._layout_projected_rays_by_index.get(int(ray_index))
        if ray is None or self.ax is None:
            return False
        pts = np.asarray(getattr(ray, "points_2d", []), dtype=float)
        if pts.ndim != 2 or pts.shape[0] < 1 or pts.shape[1] < 2:
            return False
        pts = pts[np.all(np.isfinite(pts[:, :2]), axis=1)]
        if pts.shape[0] < 1:
            return False
        artists: list = []
        if pts.shape[0] == 1:
            artists.append(
                self.ax.scatter(
                    pts[:, 0],
                    pts[:, 1],
                    s=58,
                    c="#f97316",
                    edgecolors="white",
                    linewidths=1.4,
                    zorder=982,
                )
            )
        else:
            underlay, = self.ax.plot(
                pts[:, 0],
                pts[:, 1],
                color="white",
                linewidth=6.0,
                alpha=0.94,
                zorder=980,
            )
            overlay, = self.ax.plot(
                pts[:, 0],
                pts[:, 1],
                color="#f97316",
                linewidth=2.8,
                alpha=1.0,
                zorder=981,
            )
            artists.extend([underlay, overlay])
        for ordinal, (label, point, event_kind) in enumerate(projected_ray_event_label_items(ray, limit=14)):
            marker_size = 42 if event_kind == "terminal" else 34
            artists.append(
                self.ax.scatter(
                    [point[0]],
                    [point[1]],
                    s=marker_size,
                    c="#f97316",
                    edgecolors="white",
                    linewidths=1.0,
                    zorder=984,
                )
            )
            offset_y = 7 if ordinal % 2 == 0 else -15
            artists.append(
                self.ax.annotate(
                    label,
                    xy=(float(point[0]), float(point[1])),
                    xytext=(8, offset_y),
                    textcoords="offset points",
                    fontsize=8,
                    color="#111827",
                    zorder=985,
                    clip_on=True,
                    bbox={
                        "boxstyle": "round,pad=0.24",
                        "facecolor": "white",
                        "edgecolor": "#f97316",
                        "linewidth": 0.8,
                        "alpha": 0.84,
                    },
                )
            )
        self._layout_selection_artists = artists
        return True

    def _update_layout_selection_overlay(self, row_index: int | None = None) -> None:
        self._clear_layout_selection_overlay()
        if self.ax is None:
            if hasattr(self, "canvas"):
                self.canvas.draw_idle()
            return
        if row_index is None:
            if self._layout_selected_ray_index is not None:
                if self._draw_layout_selected_ray_overlay(int(self._layout_selected_ray_index)):
                    self.canvas.draw_idle()
                    return
                self._layout_selected_ray_index = None
            row_index = self._current_selected_row_index()
        if row_index is None:
            if hasattr(self, "canvas"):
                self.canvas.draw_idle()
            return
        polylines = self._layout_pick_regions.get(int(row_index))
        if not polylines:
            if hasattr(self, "canvas"):
                self.canvas.draw_idle()
            return
        artists: list = []
        for polyline in polylines:
            pts = np.asarray(polyline, dtype=float)
            if pts.ndim != 2 or pts.shape[0] == 0:
                continue
            if pts.shape[0] == 1:
                artists.append(
                    self.ax.scatter(
                        pts[:, 0],
                        pts[:, 1],
                        s=55,
                        c="#f97316",
                        edgecolors="white",
                        linewidths=1.4,
                        zorder=950,
                    )
                )
                continue
            underlay, = self.ax.plot(
                pts[:, 0],
                pts[:, 1],
                color="white",
                linewidth=5.0,
                alpha=0.92,
                zorder=940,
            )
            overlay, = self.ax.plot(
                pts[:, 0],
                pts[:, 1],
                color="#f97316",
                linewidth=2.2,
                alpha=0.98,
                zorder=941,
            )
            artists.extend([underlay, overlay])
        self._layout_selection_artists = artists
        self.canvas.draw_idle()

    def _configure_plot_hover_hints(self) -> None:
        self._hover_hint_artists = {}
        self._hover_axis = None
        if hasattr(self, "canvas"):
            self.canvas.get_tk_widget().configure(cursor="")
        candidate_axes = [self.ax]
        candidate_axes.extend([axis for axis in self._analysis_axes if axis is not None])
        if self._analysis_ax is not None and self._analysis_ax not in candidate_axes:
            candidate_axes.append(self._analysis_ax)
        for axis in candidate_axes:
            if axis is None:
                continue
            highlight = Rectangle(
                (0.0, 0.0),
                1.0,
                1.0,
                transform=axis.transAxes,
                facecolor="#60a5fa",
                edgecolor="#2563eb",
                linewidth=1.0,
                alpha=0.06,
                visible=False,
                zorder=1000,
            )
            axis.add_patch(highlight)
            hint_text = (
                "Click surface to select, ray to inspect; empty area opens viewer"
                if axis is self.ax
                else "Click to open in viewer"
            )
            hint = axis.text(
                0.5,
                0.985,
                hint_text,
                transform=axis.transAxes,
                ha="center",
                va="top",
                fontsize=8,
                color="#334155",
                visible=False,
                zorder=1001,
                bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.65, "pad": 0.8},
            )
            self._hover_hint_artists[axis] = (highlight, hint)

    def _set_hover_hint_text(self, axis, text: str) -> None:
        artists = self._hover_hint_artists.get(axis)
        if not artists:
            return
        _highlight, hint = artists
        try:
            hint.set_text(str(text or ""))
        except Exception:
            pass

    def _set_hover_axis(self, axis) -> None:
        self._hover_axis = axis
        for current_ax, artists in self._hover_hint_artists.items():
            active = current_ax is axis
            for artist in artists:
                artist.set_visible(active)
        if hasattr(self, "canvas"):
            cursor = "hand2" if axis is not None else ""
            self.canvas.get_tk_widget().configure(cursor=cursor)
            self.canvas.draw_idle()

    @staticmethod
    def _viewer_open_command(image_path: Path) -> list[str] | None:
        preferred = os.getenv("KRAKEN_IMAGE_VIEWER", "").strip()
        if preferred:
            parts = preferred.split()
            binary = parts[0]
            if shutil.which(binary):
                return [*parts, str(image_path)]
        for binary in ("nomacs-x11", "nomacs"):
            if shutil.which(binary):
                return [binary, str(image_path)]
        if sys.platform == "darwin":
            return ["open", str(image_path)]
        if os.name == "nt":
            return None
        if shutil.which("xdg-open"):
            return ["xdg-open", str(image_path)]
        if shutil.which("gio"):
            return ["gio", "open", str(image_path)]
        for binary in ("imv", "feh", "eog", "gwenview", "ristretto", "pqiv", "sxiv", "nsxiv"):
            if shutil.which(binary):
                return [binary, str(image_path)]
        return None

    def _open_image_with_system_viewer(self, image_path: Path) -> None:
        if os.name == "nt":
            os.startfile(str(image_path))  # type: ignore[attr-defined]
            return
        command = self._viewer_open_command(image_path)
        if command is None:
            raise RuntimeError("No system image viewer command found.")
        subprocess.Popen(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)

    def _open_high_res_plot_in_system_viewer(self, target_ax=None) -> None:
        previous_hover_axis = self._hover_axis if self._hover_axis in self._hover_hint_artists else None
        hidden_axes: list[tuple[object, bool]] = []
        try:
            # Hide hover hint overlays so exported images only contain plot content.
            self._set_hover_axis(None)
            out_dir = SCREENSHOT_DIR
            try:
                out_dir.mkdir(parents=True, exist_ok=True)
            except Exception:
                out_dir = VIEWER_EXPORT_DIR
                out_dir.mkdir(parents=True, exist_ok=True)
            if target_ax is self.ax:
                axis_label = "layout"
            elif target_ax in self._analysis_axes:
                axis_index = self._analysis_axes.index(target_ax) + 1
                axis_label = f"analysis{axis_index}"
            else:
                axis_label = "analysis"
            image_path = out_dir / ("2D.png" if axis_label == "layout" else f"kraken_plot_{axis_label}.png")

            self.canvas.draw()
            if target_ax is not None and target_ax in self.figure.axes:
                renderer = self.figure.canvas.get_renderer()
                tight_bbox = target_ax.get_tightbbox(renderer)
                if tight_bbox is not None:
                    # savefig expects bbox_inches in inches, convert from display pixels
                    bbox = tight_bbox.transformed(self.figure.dpi_scale_trans.inverted()).padded(0.08)
                else:
                    fig_w, fig_h = self.figure.get_size_inches()
                    pos = target_ax.get_position()
                    bbox = Bbox.from_extents(
                        float(pos.x0) * fig_w,
                        float(pos.y0) * fig_h,
                        float(pos.x1) * fig_w,
                        float(pos.y1) * fig_h,
                    ).expanded(1.08, 1.12)
                for axis in self.figure.axes:
                    if axis is target_ax:
                        continue
                    hidden_axes.append((axis, bool(axis.get_visible())))
                    axis.set_visible(False)
                self.figure.savefig(image_path, dpi=320, bbox_inches=bbox)
            else:
                self.figure.savefig(image_path, dpi=320)

            self._open_image_with_system_viewer(image_path)
            self.status_var.set(f"Opened image in system viewer: {image_path.name}")
            self.append_progress(f"Opened high-res image: {image_path}")
        except Exception as exc:
            self.append_debug(f"High-resolution viewer launch failed: {exc}")
        finally:
            if hidden_axes:
                for axis, visible in hidden_axes:
                    try:
                        axis.set_visible(visible)
                    except Exception:
                        pass
                try:
                    self.canvas.draw_idle()
                except Exception:
                    pass
            if previous_hover_axis is not None:
                self._set_hover_axis(previous_hover_axis)

    def open_3d_view(self) -> None:
        try:
            _load_3d_backends()
            if vtkTkRenderWindowInteractor is not None:
                try:
                    if self._three_d_inspector is None or not self._three_d_inspector.winfo_exists():
                        self._three_d_inspector = Kraken3DInspector(self)
                    if self._three_d_inspector.available:
                        self._three_d_inspector.deiconify()
                        self._three_d_inspector.lift()
                        self._three_d_inspector.focus_force()
                        self._three_d_inspector.refresh_from_editor()
                        self.status_var.set("Opened Kraken 3D inspector")
                        self.append_debug("Opened Kraken 3D inspector")
                        return
                    reason = self._three_d_inspector.unavailable_reason or "VTK/Tk unavailable"
                    try:
                        self._three_d_inspector.destroy()
                    except Exception:
                        pass
                    self._three_d_inspector = None
                    self.append_debug(f"Embedded 3D inspector unavailable: {reason}. Falling back to legacy PyVista viewer.")
                except Exception as exc:
                    self.append_debug(f"Embedded 3D inspector failed: {exc}. Falling back to legacy PyVista viewer.")
                    if self._three_d_inspector is not None:
                        try:
                            self._three_d_inspector.destroy()
                        except Exception:
                            pass
                        self._three_d_inspector = None

            self._close_legacy_3d_plotter()
            current = self._current_preview_scene_trace()
            if current is not None:
                system, rays, scene_bundle = current
            else:
                system, rays, scene_bundle = self._build_preview_system_rays_bundle(
                    sampling_mode=self._preview_2d_sampling_mode(),
                    update_state=False,
                )
            plotter = self._build_legacy_3d_plotter(system, rays, scene_bundle=scene_bundle)
            plotter.show(auto_close=False, interactive=True, interactive_update=True)
            self._legacy_3d_plotter = plotter
            self._schedule_legacy_3d_poll()
            self.status_var.set("Opened legacy Kraken 3D view")
            self.append_debug("Opened legacy Kraken 3D view")
        except Exception as exc:
            self.append_debug(f"3D view error: {exc}")
            self.status_var.set(f"3D view failed: {exc}")

    def _schedule_legacy_3d_poll(self) -> None:
        if self._legacy_3d_after_id is not None:
            return
        try:
            self._legacy_3d_after_id = self.after(20, self._poll_legacy_3d_plotter)
        except Exception:
            self._legacy_3d_after_id = None

    def _poll_legacy_3d_plotter(self) -> None:
        self._legacy_3d_after_id = None
        plotter = self._legacy_3d_plotter
        if plotter is None:
            return
        if bool(getattr(plotter, "_closed", False)):
            self._legacy_3d_plotter = None
            self.status_var.set("Closed legacy Kraken 3D view")
            return
        try:
            plotter.update(stime=1, force_redraw=True)
        except Exception as exc:
            self.append_debug(f"Legacy 3D update failed: {exc}")
            self._close_legacy_3d_plotter()
            self.status_var.set(f"3D view closed: {_short_error_message(exc)}")
            return
        self._schedule_legacy_3d_poll()

    def _close_legacy_3d_plotter(self) -> None:
        if self._legacy_3d_after_id is not None:
            try:
                self.after_cancel(self._legacy_3d_after_id)
            except Exception:
                pass
            self._legacy_3d_after_id = None
        plotter = self._legacy_3d_plotter
        self._legacy_3d_plotter = None
        if plotter is None:
            return
        stl_placement_dirty = bool(getattr(plotter, "_kraken_stl_placement_dirty", False))
        # VTK's GLX teardown segfaults on Wayland / XWayland, so hide the
        # window and detach references instead of calling plotter.close().
        try:
            iren = getattr(plotter, "iren", None)
            if iren is not None:
                iren.terminate_app()
        except Exception:
            pass
        try:
            rw = getattr(plotter, "render_window", None)
            if rw is not None:
                rw.SetShowWindow(False)
        except Exception:
            pass
        if stl_placement_dirty:
            def refresh_2d_after_legacy_close() -> None:
                try:
                    self.refresh_plot(suppress_analysis=True)
                except Exception as exc:
                    self.status_var.set(f"CAD/STL placement saved; 2D refresh failed: {_short_error_message(exc)}")
                    self.append_debug(f"Legacy CAD/STL placement close refresh failed: {exc}")

            try:
                self.after(50, refresh_2d_after_legacy_close)
                self.status_var.set("Legacy 3D CAD/STL placement closed; refreshing 2D layout.")
            except Exception as exc:
                self.append_debug(f"Legacy CAD/STL placement close refresh failed: {exc}")

    def _build_preview_system_rays_bundle(
        self,
        *,
        sampling_mode: str | None = None,
        update_state: bool = True,
        include_live_step_overlays: bool = False,
    ):
        wavelength = self._current_wavelength()
        capture = io.StringIO()
        active_rows = self.rows
        live_step_records: list[dict[str, object]] = []
        if include_live_step_overlays:
            active_rows, live_step_records = self._live_step_overlay_trace_rows()
        else:
            self._last_live_step_overlay_trace_rows = None
            self._last_live_step_overlay_trace_records = []
            self._last_live_step_overlay_scene_bundle = None
        original_rows: list[SurfaceRow] | None = None
        scene_bundle = None
        try:
            if active_rows is not self.rows:
                original_rows = self.rows
                self.rows = active_rows
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", RuntimeWarning)
                with redirect_stdout(capture), redirect_stderr(capture):
                    system = self.build_system(
                        require_solids=True,
                        force_rebuild=bool(live_step_records),
                    )
                    rays = Kos.raykeeper(system)
                    max_radius = max((max(row.diameter / 2.0, 0.5) for row in self.rows), default=1.0)
                    mode = sampling_mode
                    if mode is None:
                        mode = self._preview_scene_sampling_mode()
                    self._trace_preview_rays(
                        system,
                        rays,
                        wavelength,
                        max_radius,
                        sampling_mode=mode,
                    )
            scene_bundle = self._build_scene_bundle(system, rays, max_radius)
            if include_live_step_overlays:
                self._last_live_step_overlay_trace_rows = list(self.rows)
                self._last_live_step_overlay_trace_records = list(live_step_records)
                self._last_live_step_overlay_scene_bundle = scene_bundle
        finally:
            if original_rows is not None:
                self.rows = original_rows
        self.append_debug(capture.getvalue())
        if update_state and not include_live_step_overlays:
            self.last_system = system
            self.last_rays = rays
            self._last_preview_trace_signature = self._preview_trace_signature()
            self._last_scene_bundle = scene_bundle
            self._preview_scene_trace_dirty = False
        return system, rays, scene_bundle

    def _live_step_overlay_trace_rows(self) -> tuple[list[SurfaceRow], list[dict[str, object]]]:
        if self._step_path_for_label("optical") is None:
            return self.rows, []
        base_rows = [SurfaceRow(**asdict(row)) for row in self.rows]
        cache_key = self._live_step_overlay_trace_cache_key("optical", base_rows)
        cached_plan = self._cached_live_step_overlay_trace_plan(cache_key)
        if cached_plan is not None:
            row = cached_plan.get("row")
            if isinstance(row, SurfaceRow):
                row_index = int(cached_plan.get("row_index", len(base_rows)))
                base_rows.insert(max(1, min(row_index, len(base_rows))), row)
                return base_rows, [cached_plan]
        original_rows = self.rows
        try:
            self.rows = base_rows
            plan = self._step_overlay_optical_solid_row_plan(
                "optical",
                cache_subdir="live_step_overlays",
                transient_live_trace=True,
                use_current_selection=False,
                quiet=True,
            )
            if plan is None:
                return original_rows, []
            row = plan.get("row")
            if not isinstance(row, SurfaceRow):
                return original_rows, []
            row_index = int(plan.get("row_index", len(base_rows)))
            base_rows.insert(max(1, min(row_index, len(base_rows))), row)
            self._remember_live_step_overlay_trace_plan(cache_key, plan)
            return base_rows, [plan]
        finally:
            self.rows = original_rows

    def _live_step_overlay_trace_cache_key(self, label: str, rows: list[SurfaceRow]) -> object | None:
        label = str(label).strip().lower()
        source_path = self._step_path_for_label(label)
        if source_path is None:
            return None
        try:
            row_signature = _row_specs_signature(self._serializable_specs_for_rows(rows))
        except Exception:
            row_signature = tuple(
                (
                    str(getattr(row, "surface", "") or ""),
                    float(getattr(row, "thickness", 0.0) or 0.0),
                    float(getattr(row, "diameter", 0.0) or 0.0),
                    float(getattr(row, "desp_x", 0.0) or 0.0),
                    float(getattr(row, "desp_y", 0.0) or 0.0),
                    float(getattr(row, "desp_z", 0.0) or 0.0),
                )
                for row in rows
            )
        return (
            label,
            str(Path(source_path).resolve()),
            float(self._step_x_rotation_deg(label)),
            float(self._step_y_rotation_deg(label)),
            float(self._step_roll_deg(label)),
            tuple(float(value) for value in self._step_axis_offset_xy(label)),
            tuple(float(value) for value in self._step_placement_offset_xyz(label)),
            bool(getattr(self, "lens_step_largest_component_only", True)) if label == "lens" else None,
            row_signature,
        )

    def _cached_live_step_overlay_trace_plan(self, cache_key: object | None) -> dict[str, object] | None:
        if cache_key is None:
            return None
        cache = getattr(self, "_live_step_overlay_trace_plan_cache", {}) or {}
        cached = cache.get(cache_key)
        if not isinstance(cached, dict):
            return None
        row = cached.get("row")
        if not isinstance(row, SurfaceRow):
            return None
        copied = dict(cached)
        copied["row"] = SurfaceRow(**asdict(row))
        copied["cache_hit"] = True
        return copied

    def _remember_live_step_overlay_trace_plan(self, cache_key: object | None, plan: dict[str, object]) -> None:
        if cache_key is None or not isinstance(plan, dict):
            return
        row = plan.get("row")
        if not isinstance(row, SurfaceRow):
            return
        cache = dict(getattr(self, "_live_step_overlay_trace_plan_cache", {}) or {})
        cached = dict(plan)
        cached["row"] = SurfaceRow(**asdict(row))
        cache[cache_key] = cached
        while len(cache) > 4:
            try:
                cache.pop(next(iter(cache)))
            except Exception:
                break
        self._live_step_overlay_trace_plan_cache = cache

    def _preview_render_rows(self, scene_bundle: SceneBundle | None = None) -> list[SurfaceRow]:
        if (
            scene_bundle is not None
            and scene_bundle is self.__dict__.get("_last_live_step_overlay_scene_bundle")
        ):
            rows = self.__dict__.get("_last_live_step_overlay_trace_rows")
            if rows:
                return list(rows)
        return list(self.rows)

    def _preview_render_row_names(self, scene_bundle: SceneBundle | None = None) -> list[str]:
        return [str(getattr(row, "name", "") or "") for row in self._preview_render_rows(scene_bundle)]

    def _preview_scene_sampling_mode(self) -> str:
        """Sampling mode for the shared traced scene used by 2D and Open 3D."""
        if self._is_full_pupil_mode():
            return "full_pupil"
        try:
            trace_state = self._resolved_trace_mode(system=self.__dict__.get("last_system"))
        except Exception:
            trace_state = {}
        if bool(trace_state.get("use_nonseq")) or bool(trace_state.get("use_folded")):
            return "world_envelope"
        return "display_slice"

    def _preview_2d_sampling_mode(self) -> str:
        """Sampling mode for the editable 2D projections.

        Sequential 2D plots now trace a real 3-D cross-section bundle and let
        each projection pane filter the resulting world paths to its slice.
        """
        if self._is_full_pupil_mode():
            return "full_pupil"
        try:
            trace_state = self._resolved_trace_mode(system=self.__dict__.get("last_system"))
        except Exception:
            trace_state = {}
        if bool(trace_state.get("use_nonseq")) or bool(trace_state.get("use_folded")):
            return self._preview_scene_sampling_mode()
        if self._current_source_model() == SOURCE_MODEL_DEFAULT:
            return "world_sections"
        return self._preview_scene_sampling_mode()

    def _preview_3d_sampling_mode(self) -> str:
        """Sampling mode for Open 3D.

        Open 3D should show the physical 3D launch whenever the user has not
        explicitly requested a filled full-pupil trace. The default Pupil/field
        sampler remains a prescription reference; use a physical source model
        for point-cone illumination.
        """
        if self._is_full_pupil_mode():
            return "full_pupil"
        return "world_envelope"

    def _current_preview_scene_trace(self):
        if bool(getattr(self, "_preview_scene_trace_dirty", False)):
            return None
        if self.last_system is None or self.last_rays is None or self._last_scene_bundle is None:
            return None
        if not preview_trace_signature_matches(self._last_preview_trace_signature, self._preview_trace_signature()):
            return None
        return self.last_system, self.last_rays, self._last_scene_bundle

    def _build_preview_system_and_rays(self):
        system, rays, _scene_bundle = self._build_preview_system_rays_bundle(update_state=True)
        return system, rays

    def _iter_3d_optical_surface_meshes(
        self,
        system,
        *,
        include_reference_surfaces: bool,
    ) -> list[SurfaceMesh3D]:
        transforms = getattr(system, "TRANS_2A", None)
        surfaces = getattr(system, "AAA", None)
        if transforms is None or surfaces is None:
            return []
        surface_descriptors = getattr(system, "SDT_0", None)
        try:
            surface_count = len(surface_descriptors)
        except Exception:
            surface_count = 0
        block_count = min(len(self.rows), getattr(surfaces, "n_blocks", 0), len(transforms), surface_count)
        mesh_items: list[SurfaceMesh3D] = []
        pose_overrides = optical_solid_output_port_pose_overrides(system, self.rows)
        for index in range(block_count):
            row = self.rows[index]
            if not include_reference_surfaces and row.surface in {"Object", "Image"}:
                continue
            row_transform = optical_solid_output_port_runtime_transform_override(system, self.rows, index)
            mesh = None
            advanced = row.advanced if isinstance(row.advanced, dict) else {}
            file_backed_optical_solid = self._scene_graph_value_present(advanced.get("Solid_3d_stl"))
            if file_backed_optical_solid or index in pose_overrides:
                mesh = KrakenLayoutEditor._runtime_trace_surface_mesh(system, index)
            if row_transform is None:
                row_transform = transforms[index]
            if file_backed_optical_solid and row_transform is not None and mesh is None:
                solid_mesh = self._stl_mesh_with_world_transform(row, row_transform)
                if solid_mesh is not None and int(getattr(solid_mesh, "n_points", 0)) > 0:
                    mesh = solid_mesh
            if mesh is None:
                mesh = Kraken3DInspector._mesh_with_transform(surfaces[index], row_transform)
            if mesh is None and row_transform is not None:
                mesh = self._stl_mesh_with_world_transform(row, row_transform)
            if mesh is None or int(getattr(mesh, "n_points", 0)) == 0:
                continue
            mesh = KrakenLayoutEditor._reference_mesh_with_row_diameter(mesh, row)
            surface = surface_descriptors[index]
            mesh_color = (0.10, 0.62, 0.72) if file_backed_optical_solid else Kraken3DInspector._surface_color(surface)
            mesh_opacity = 0.30 if file_backed_optical_solid else (0.88 if row.surface == "Mirror" else 0.68)
            mesh_items.append(
                SurfaceMesh3D(
                    row_index=index,
                    kind=str(row.surface or "standard").lower().replace(" ", "_"),
                    row=row,
                    surface=surface,
                    mesh=mesh,
                    color=mesh_color,
                    opacity=mesh_opacity,
                    is_stop=self._legacy_3d_is_stop_plane(row),
                )
            )
        return mesh_items

    @staticmethod
    def _runtime_trace_surface_mesh(system, row_index: int) -> pv.DataSet | None:
        if pv is None or system is None:
            return None
        meshes = getattr(system, "EEE", None)
        try:
            if meshes is None or not (0 <= int(row_index) < len(meshes)):
                return None
            mesh = pv.wrap(meshes[int(row_index)])
        except Exception:
            return None
        try:
            mesh = mesh.extract_surface(algorithm="dataset_surface")
        except Exception:
            pass
        try:
            mesh = mesh.copy(deep=True)
        except Exception:
            return None
        try:
            pts = np.asarray(mesh.points, dtype=float)
        except Exception:
            return None
        if pts.ndim != 2 or pts.shape[0] < 1 or not np.any(np.all(np.isfinite(pts[:, :3]), axis=1)):
            return None
        return mesh

    @staticmethod
    def _reference_mesh_with_row_diameter(mesh, row: SurfaceRow):
        if pv is None or mesh is None:
            return mesh
        surface = str(getattr(row, "surface", "") or "").strip()
        if surface not in {"Object", "Image"}:
            return mesh
        try:
            target_radius = max(float(getattr(row, "diameter", 0.0) or 0.0) * 0.5, 0.0)
        except Exception:
            return mesh
        if target_radius <= 1e-12:
            return mesh
        try:
            scaled = mesh.copy(deep=True)
            pts = np.asarray(scaled.points, dtype=float)
        except Exception:
            return mesh
        if pts.ndim != 2 or pts.shape[0] < 1 or pts.shape[1] < 3:
            return mesh
        finite = np.all(np.isfinite(pts[:, :3]), axis=1)
        if not np.any(finite):
            return mesh
        center = np.mean(pts[finite, :3], axis=0)
        radii = np.linalg.norm(pts[finite, :3] - center, axis=1)
        current_radius = float(np.max(radii)) if radii.size else 0.0
        if current_radius <= 1e-12:
            return mesh
        pts[:, :3] = center + (pts[:, :3] - center) * (target_radius / current_radius)
        try:
            scaled.points = pts
            return scaled
        except Exception:
            return mesh

    def _stl_mesh_with_world_transform(self, row: SurfaceRow, transform: np.ndarray) -> pv.DataSet | None:
        if pv is None:
            return None
        path = self._stl_path_from_row(row)
        if path is None:
            return None
        try:
            _fmt, triangles = _read_stl_triangle_vertices(path)
            triangles = np.asarray(triangles, dtype=float)
            if triangles.ndim != 3 or triangles.shape[1:] != (3, 3) or triangles.shape[0] == 0:
                return None
            points = triangles.reshape((-1, 3))
            local_h = np.column_stack(
                (
                    points[:, 0],
                    points[:, 1],
                    points[:, 2],
                    np.ones(points.shape[0], dtype=float),
                )
            )
            matrix = np.asarray(transform, dtype=float).reshape(4, 4)
            world = (matrix @ local_h.T).T[:, :3]
            faces = np.column_stack(
                (
                    np.full(triangles.shape[0], 3, dtype=np.int64),
                    np.arange(points.shape[0], dtype=np.int64).reshape((-1, 3)),
                )
            ).ravel()
            return pv.PolyData(world, faces)
        except Exception:
            return None

    def _iter_3d_side_body_meshes(
        self,
        system,
        *,
        include_reference_surfaces: bool,
    ) -> list[SurfaceMesh3D]:
        surface_descriptors = getattr(system, "SDT_0", None)
        try:
            surface_count = len(surface_descriptors)
        except Exception:
            surface_count = 0
        mesh_items: list[SurfaceMesh3D] = []
        side_index = 0
        for row_index in getattr(system, "side_number", []):
            try:
                row_index_int = int(row_index)
            except Exception:
                side_index += 1
                continue
            if row_index_int >= len(self.rows) or row_index_int >= surface_count:
                side_index += 1
                continue
            row = self.rows[row_index_int]
            if not include_reference_surfaces and row.surface in {"Object", "Image"}:
                side_index += 1
                continue
            advanced = row.advanced if isinstance(row.advanced, dict) else {}
            if self._geometry_value_present(advanced.get("Solid_3d_stl")):
                side_index += 1
                continue
            try:
                body = pv.wrap(system.BBB[side_index]).extract_surface().copy(deep=True)
            except Exception:
                side_index += 1
                continue
            side_index += 1
            if int(getattr(body, "n_points", 0)) == 0:
                continue
            surface = surface_descriptors[row_index_int]
            mesh_items.append(
                SurfaceMesh3D(
                    row_index=row_index_int,
                    kind=f"{str(row.surface or 'standard').lower().replace(' ', '_')}_solid",
                    row=row,
                    surface=surface,
                    mesh=body,
                    color=Kraken3DInspector._surface_color(surface),
                    opacity=0.18,
                    is_stop=self._legacy_3d_is_stop_plane(row),
                    is_body=True,
                )
            )
        return mesh_items

    def _iter_3d_surface_meshes(
        self,
        system,
        *,
        include_reference_surfaces: bool,
    ) -> list[SurfaceMesh3D]:
        return [
            *self._iter_3d_optical_surface_meshes(system, include_reference_surfaces=include_reference_surfaces),
            *self._iter_3d_side_body_meshes(system, include_reference_surfaces=include_reference_surfaces),
        ]

    def _scene_surface_meshes(
        self,
        system,
        scene_bundle: SceneBundle | None = None,
        *,
        include_reference_surfaces: bool,
    ) -> list[SurfaceMesh3D]:
        bundle = scene_bundle if scene_bundle is not None else self._last_scene_bundle
        mesh_items = list(getattr(bundle, "surface_meshes", []) or []) if bundle is not None else []
        if not mesh_items and system is not None:
            mesh_items = self._iter_3d_surface_meshes(system, include_reference_surfaces=True)
            if bundle is not None:
                bundle.surface_meshes = list(mesh_items)
        if include_reference_surfaces:
            return mesh_items
        return [
            mesh_item
            for mesh_item in mesh_items
            if getattr(mesh_item.row, "surface", "") not in {"Object", "Image"}
        ]

    def _build_legacy_3d_plotter(self, system, rays, *, scene_bundle: SceneBundle | None = None):
        _load_3d_backends()
        if pv is None:
            raise RuntimeError("PyVista is required for legacy 3D view")
        plotter = pv.Plotter(shape=(1, 1), title="KrakenOS 3D", notebook=False)
        plotter.set_background("white", top="white")
        plotter.enable_anti_aliasing()
        try:
            plotter.render_window.SetStereoTypeToFake()
            plotter.render_window.StereoRenderOff()
            plotter.render_window.StereoCapableWindowOff()
        except Exception:
            pass
        plotter.add_axes(line_width=3)
        plotter.show_grid(font_size=6, color="black", n_xlabels=2, n_ylabels=2, n_zlabels=2, fmt="%.0f", bold=False)
        scene_bundle = scene_bundle if scene_bundle is not None else self._last_scene_bundle
        scene_info = self._populate_legacy_3d_plotter_scene(
            plotter,
            system,
            rays,
            scene_bundle=scene_bundle,
            add_clip_plane=False,
            add_labels=True,
        )
        self._configure_legacy_3d_plotter(
            plotter,
            ray_actors=scene_info["ray_actors"],
            mirror_actors=scene_info["mirror_actors"],
            lens_actors=scene_info["lens_actors"],
            helper_actors=scene_info["helper_actors"],
        )
        self._enable_legacy_3d_close_handling(plotter)
        setattr(plotter, "_kraken_scene", scene_info)
        setattr(plotter, "_kraken_scene_bundle", scene_bundle)
        setattr(plotter, "_kraken_system", system)
        setattr(plotter, "_kraken_rays", rays)
        return plotter

    def _legacy_3d_scene_service(self) -> Legacy3DSceneService:
        service = self.__dict__.get("_legacy_3d_scene_service_instance")
        if service is None:
            service = Legacy3DSceneService(self)
            self._legacy_3d_scene_service_instance = service
        return service

    def _populate_legacy_3d_plotter_scene(
        self,
        plotter,
        system,
        rays,
        *,
        scene_bundle: SceneBundle | None = None,
        add_clip_plane: bool,
        add_labels: bool,
    ) -> dict[str, list]:
        return self._legacy_3d_scene_service()._populate_legacy_3d_plotter_scene(
            plotter,
            system,
            rays,
            scene_bundle=scene_bundle,
            add_clip_plane=add_clip_plane,
            add_labels=add_labels,
        )

    def _build_clean_legacy_3d_plotter(self, system, rays):
        _load_3d_backends()
        if pv is None:
            raise RuntimeError("PyVista is required for 3D screenshot export")
        plotter = pv.Plotter(off_screen=True, window_size=(2200, 1400), notebook=False)
        plotter.set_background("white", top="white")
        plotter.enable_anti_aliasing()
        try:
            plotter.render_window.SetStereoTypeToFake()
            plotter.render_window.StereoRenderOff()
            plotter.render_window.StereoCapableWindowOff()
        except Exception:
            pass
        plotter.add_axes(line_width=3)
        plotter.show_grid(font_size=6, color="black", n_xlabels=2, n_ylabels=2, n_zlabels=2, fmt="%.0f", bold=False)
        scene_bundle = self._last_scene_bundle
        scene_info = self._populate_legacy_3d_plotter_scene(
            plotter,
            system,
            rays,
            scene_bundle=scene_bundle,
            add_clip_plane=False,
            add_labels=False,
        )
        setattr(plotter, "_kraken_scene", scene_info)
        setattr(plotter, "_kraken_scene_bundle", scene_bundle)
        return plotter

    @staticmethod
    def _legacy_3d_is_stop_plane(row: SurfaceRow) -> bool:
        name = (row.name or "").strip().lower()
        return "stop" in name or "aperture" in name

    @staticmethod
    def _legacy_3d_stop_ring_mesh(mesh, row: SurfaceRow):
        try:
            pts = np.asarray(mesh.points, dtype=float)
        except Exception:
            return None
        if pts.size == 0:
            return None
        center = np.mean(pts, axis=0)
        centered = pts - center
        try:
            _u, _s, vh = np.linalg.svd(centered, full_matrices=False)
            normal = np.asarray(vh[-1], dtype=float)
        except Exception:
            normal = np.array([0.0, 0.0, 1.0], dtype=float)
        norm = max(float(np.linalg.norm(normal)), 1e-12)
        normal = normal / norm
        outer = max(float(row.diameter) * 0.5, 0.5)
        inner = max(outer * 0.82, outer - 0.8)
        if inner >= outer:
            inner = outer * 0.9
        try:
            return pv.Disc(center=center, inner=inner, outer=outer, normal=normal, r_res=1, c_res=96)
        except Exception:
            return None

    def _legacy_3d_ray_radius(self, system, rays) -> float:
        try:
            bounds = np.asarray(system.AAA.bounds, dtype=float)
        except Exception:
            bounds = np.array([0.0, 100.0, -25.0, 25.0, -25.0, 25.0], dtype=float)
        span = max(
            float(bounds[1] - bounds[0]) if bounds.size >= 2 else 0.0,
            float(bounds[3] - bounds[2]) if bounds.size >= 4 else 0.0,
            float(bounds[5] - bounds[4]) if bounds.size >= 6 else 0.0,
            1.0,
        )
        ray_count = max(len(getattr(rays, "CC", [])), 1)
        return max(span * 0.0009 / max(np.sqrt(ray_count), 1.0), 0.05)

    def _physical_dimension_values(self) -> tuple[float, float, float, float, float] | None:
        if not self.rows or len(self.rows) < 3:
            return None
        housing_front_z = self._lens_front_datum_z()
        object_z = 0.0
        image_z = self._current_image_plane_z()
        camera_front_z = image_z - self._current_camera_front_to_sensor_mm()
        if not all(np.isfinite(value) for value in (object_z, housing_front_z, camera_front_z)):
            return None
        return (
            float(object_z),
            float(housing_front_z),
            float(camera_front_z),
            abs(float(housing_front_z - object_z)),
            abs(float(camera_front_z - housing_front_z)),
        )

    def _add_legacy_3d_physical_dimensions(self, plotter, helper_actors: list) -> None:
        self._legacy_3d_scene_service()._add_legacy_3d_physical_dimensions(plotter, helper_actors)

    def _iter_3d_display_rays(self, rays):
        return [(wave, path) for _index, wave, path in self._iter_3d_display_ray_items(rays)]

    def _iter_3d_display_ray_items(self, rays):
        waves = list(getattr(rays, "RayWave", []))
        paths = list(getattr(rays, "CC", []))
        total = min(len(waves), len(paths))
        if total <= 0:
            return []
        waves = waves[:total]
        paths = paths[:total]
        if total <= 300:
            return [(index, waves[index], paths[index]) for index in range(total)]
        step = max(total // 300, 1)
        return [(index, waves[index], paths[index]) for index in range(0, total, step)]

    def _iter_3d_scene_ray_items(
        self,
        rays=None,
        scene_bundle: SceneBundle | None = None,
    ) -> list[tuple[int, tuple[float, float, float], np.ndarray]]:
        return [
            (ray_index, color, points)
            for ray_index, color, points, _terminal_status in self._iter_3d_scene_ray_records(rays, scene_bundle)
        ]

    def _iter_3d_scene_ray_records(
        self,
        rays=None,
        scene_bundle: SceneBundle | None = None,
    ) -> list[tuple[int, tuple[float, float, float], np.ndarray, str]]:
        bundle = scene_bundle if scene_bundle is not None else self._last_scene_bundle
        scene_paths = list(getattr(bundle, "ray_paths", []) or []) if bundle is not None else []
        if scene_paths:
            total = len(scene_paths)
            step = max(total // 300, 1) if total > 300 else 1
            rendered: list[tuple[int, tuple[float, float, float], np.ndarray, str]] = []
            for fallback_index, path in enumerate(scene_paths[0:total:step]):
                points = np.asarray(path.points_world, dtype=float)
                if points.ndim != 2 or points.shape[0] < 2 or points.shape[1] < 3:
                    continue
                wavelength = getattr(path, "wavelength", None)
                if wavelength is not None:
                    color = tuple(_wavelength_to_rgb(float(wavelength) * 1000.0))
                else:
                    color = _color_to_rgb_tuple(getattr(path, "color", "#39FF14"))
                try:
                    ray_index = int(getattr(path, "ray_index"))
                except Exception:
                    ray_index = int(fallback_index * step)
                rendered.append((ray_index, color, points[:, :3], ray_path_terminal_status_from_events(path)))
            if rendered:
                return rendered

        fallback_rays = rays if rays is not None else self.last_rays
        return [
            (int(ray_index), tuple(_wavelength_to_rgb(float(wave) * 1000.0)), np.asarray(ray_pts, dtype=float), "")
            for ray_index, wave, ray_pts in self._iter_3d_display_ray_items(fallback_rays)
        ]

    @staticmethod
    def _scene_center_radius_from_bounds(bounds) -> tuple[np.ndarray, float]:
        try:
            values = np.asarray(bounds, dtype=float).reshape(-1)[:6]
        except Exception:
            values = np.asarray([], dtype=float)
        if values.size != 6 or not np.all(np.isfinite(values)) or values[0] > values[1]:
            return np.zeros(3, dtype=float), 1.0
        center = np.array(
            [
                0.5 * (values[0] + values[1]),
                0.5 * (values[2] + values[3]),
                0.5 * (values[4] + values[5]),
            ],
            dtype=float,
        )
        radius = max(values[1] - values[0], values[3] - values[2], values[5] - values[4], 1.0)
        return center, float(radius)

    @staticmethod
    def _scene_ray_path_by_index(scene_bundle: SceneBundle | None) -> dict[int, object]:
        if scene_bundle is None:
            return {}
        paths: dict[int, object] = {}
        for path in list(getattr(scene_bundle, "ray_paths", []) or []):
            try:
                paths[int(getattr(path, "ray_index"))] = path
            except Exception:
                continue
        return paths

    @staticmethod
    def _missed_detector_target_for_path(scene_bundle: SceneBundle | None, path: object | None) -> SceneTarget3D | None:
        if scene_bundle is None or path is None:
            return None
        if ray_path_terminal_status_from_events(path) != "missed_detector":
            return None
        metadata = ray_path_terminal_metadata(path)
        surface = metadata.get("detector_miss_surface")
        if surface in (None, ""):
            event = ray_path_terminal_event(path)
            if event is not None:
                surface = getattr(event, "surface_id", None)
        try:
            surface_index = int(surface)
        except Exception:
            return None
        for target in list(getattr(scene_bundle, "targets", []) or []):
            trace_surface = getattr(target, "trace_surface", None)
            try:
                if trace_surface is not None and int(trace_surface) == surface_index:
                    return target
            except Exception:
                continue
        return None

    @staticmethod
    def _terminal_display_direction_for_path(path: object | None) -> np.ndarray | None:
        if path is None:
            return None
        event = ray_path_terminal_event(path)
        if event is not None:
            for attribute in ("outgoing_direction", "incoming_direction"):
                direction = KrakenLayoutEditor._unit_3d_vector_or_none(getattr(event, attribute, None))
                if direction is not None:
                    return direction
        try:
            points = np.asarray(getattr(path, "points_world", []), dtype=float)
        except Exception:
            return None
        if points.ndim == 2 and points.shape[0] >= 2 and points.shape[1] >= 3:
            return KrakenLayoutEditor._unit_3d_vector_or_none(points[-1, :3] - points[-2, :3])
        return None

    @staticmethod
    def _unit_3d_vector_or_none(value) -> np.ndarray | None:
        try:
            vector = np.asarray(value, dtype=float).reshape(-1)[:3]
        except Exception:
            return None
        if vector.size < 3 or not np.all(np.isfinite(vector[:3])):
            return None
        norm = float(np.linalg.norm(vector[:3]))
        if not np.isfinite(norm) or norm <= 1.0e-12:
            return None
        return vector[:3] / norm

    @staticmethod
    def _target_frame_axes_for_display(target: SceneTarget3D | None) -> tuple[np.ndarray, np.ndarray, np.ndarray] | None:
        if target is None:
            return None
        try:
            center = np.asarray(getattr(target, "center_world", ()), dtype=float).reshape(-1)[:3]
            normal = np.asarray(getattr(target, "normal_world", ()), dtype=float).reshape(-1)[:3]
            tangent = np.asarray(getattr(target, "tangent_world", ()), dtype=float).reshape(-1)[:3]
        except Exception:
            return None
        if (
            center.size < 3
            or normal.size < 3
            or tangent.size < 3
            or not np.all(np.isfinite(center[:3]))
            or not np.all(np.isfinite(normal[:3]))
            or not np.all(np.isfinite(tangent[:3]))
        ):
            return None
        normal_norm = float(np.linalg.norm(normal[:3]))
        if not np.isfinite(normal_norm) or normal_norm <= 1.0e-12:
            return None
        normal = normal[:3] / normal_norm
        tangent = tangent[:3] - normal * float(np.dot(tangent[:3], normal))
        tangent_norm = float(np.linalg.norm(tangent))
        if not np.isfinite(tangent_norm) or tangent_norm <= 1.0e-12:
            for candidate in (
                np.asarray((1.0, 0.0, 0.0), dtype=float),
                np.asarray((0.0, 1.0, 0.0), dtype=float),
                np.asarray((0.0, 0.0, 1.0), dtype=float),
            ):
                tangent = candidate - normal * float(np.dot(candidate, normal))
                tangent_norm = float(np.linalg.norm(tangent))
                if np.isfinite(tangent_norm) and tangent_norm > 1.0e-12:
                    break
        if not np.isfinite(tangent_norm) or tangent_norm <= 1.0e-12:
            return None
        tangent = tangent / tangent_norm
        bitangent = np.cross(normal, tangent)
        bitangent_norm = float(np.linalg.norm(bitangent))
        if not np.isfinite(bitangent_norm) or bitangent_norm <= 1.0e-12:
            return None
        return center[:3], tangent, bitangent / bitangent_norm

    @staticmethod
    def _target_active_dimensions_for_display(target: SceneTarget3D | None) -> tuple[float, float] | None:
        if target is None:
            return None
        try:
            diameter = max(float(getattr(target, "diameter", 0.0) or 0.0), 0.0)
        except Exception:
            diameter = 0.0
        try:
            width = max(float(getattr(target, "active_width_mm", 0.0) or 0.0), 0.0)
        except Exception:
            width = 0.0
        try:
            height = max(float(getattr(target, "active_height_mm", 0.0) or 0.0), 0.0)
        except Exception:
            height = 0.0
        if width <= 1.0e-12:
            width = diameter
        if height <= 1.0e-12:
            height = diameter
        if width <= 1.0e-12 or height <= 1.0e-12:
            return None
        return float(width), float(height)

    @staticmethod
    def _display_detector_miss_limit(target: SceneTarget3D | None, radius: float) -> float:
        try:
            scene_radius = float(radius)
        except Exception:
            scene_radius = 1.0
        if not np.isfinite(scene_radius) or scene_radius <= 0.0:
            scene_radius = 1.0
        dimensions = KrakenLayoutEditor._target_active_dimensions_for_display(target)
        aperture_span = max(dimensions) if dimensions is not None else 1.0
        scene_limit = max(25.0, min(scene_radius * 0.35, 250.0))
        return float(max(aperture_span * 1.25, scene_limit))

    @staticmethod
    def _display_detector_miss_point_on_plane(
        point,
        target: SceneTarget3D | None,
        radius: float,
    ) -> tuple[np.ndarray | None, bool]:
        try:
            terminal = np.asarray(point, dtype=float).reshape(-1)[:3]
        except Exception:
            return None, False
        if terminal.size < 3 or not np.all(np.isfinite(terminal[:3])):
            return None, False
        axes = KrakenLayoutEditor._target_frame_axes_for_display(target)
        if axes is None:
            return terminal[:3], False
        center, tangent, bitangent = axes
        rel = terminal[:3] - center
        u = float(np.dot(rel, tangent))
        v = float(np.dot(rel, bitangent))
        limit = KrakenLayoutEditor._display_detector_miss_limit(target, radius)
        radial = float(np.hypot(u, v))
        capped = False
        if np.isfinite(radial) and radial > limit > 0.0:
            scale = limit / radial
            u *= scale
            v *= scale
            capped = True
        display_point = center + tangent * u + bitangent * v
        if not np.allclose(display_point, terminal[:3], rtol=0.0, atol=1.0e-9):
            capped = True
        return display_point, capped

    @staticmethod
    def _detector_miss_crosshair_polylines_for_display(
        path: object,
        target: SceneTarget3D | None,
        *,
        display_center=None,
        display_radius: float = 1.0,
        cap_to_scene: bool = False,
    ) -> list[np.ndarray]:
        if not bool(cap_to_scene):
            return scene_target_detector_miss_crosshair_polylines(path, target)
        if ray_path_terminal_status_from_events(path) != "missed_detector":
            return []
        event = ray_path_terminal_event(path)
        if event is None:
            return []
        point, _capped = KrakenLayoutEditor._display_detector_miss_point_on_plane(
            getattr(event, "point_world", None),
            target,
            display_radius,
        )
        axes = KrakenLayoutEditor._target_frame_axes_for_display(target)
        dimensions = KrakenLayoutEditor._target_active_dimensions_for_display(target)
        if point is None or axes is None or dimensions is None:
            return []
        _center, tangent, bitangent = axes
        width, height = dimensions
        arm = max(min(float(min(width, height)) * 0.18, float(max(width, height)) * 0.35), 0.35)
        return [
            np.vstack((point - tangent * arm, point + tangent * arm)),
            np.vstack((point - bitangent * arm, point + bitangent * arm)),
        ]

    @staticmethod
    def _bounded_3d_ray_points_for_display(
        points,
        center,
        radius: float,
        *,
        terminal_status: str = "",
        terminal_target: SceneTarget3D | None = None,
        terminal_direction=None,
    ) -> tuple[np.ndarray, bool]:
        return bounded_ray_points_for_scene_display(
            points,
            center,
            radius,
            terminal_status=terminal_status,
            terminal_target=terminal_target,
            terminal_direction=terminal_direction,
        )

    @staticmethod
    def _ray_vertex_display_inset(radius: float) -> float:
        try:
            scene_radius = float(radius)
        except Exception:
            scene_radius = 1.0
        if not np.isfinite(scene_radius) or scene_radius <= 0.0:
            scene_radius = 1.0
        return float(max(min(scene_radius * 0.0015, 0.18), 0.035))

    @staticmethod
    def _ray_segment_mesh_for_3d_display(points, *, vertex_inset: float = 0.0):
        """Build disconnected VTK line segments for physical ray events.

        Rendering a reflected ray as one connected polyline can let the line
        join/cap project through a mirror-hit vertex and mimic transmission.
        Open 3D should draw each physical segment independently.
        """
        if pv is None:
            try:
                _load_3d_backends()
            except Exception:
                pass
        if pv is None:
            return None
        try:
            pts = np.asarray(points, dtype=float)
        except Exception:
            return None
        if pts.ndim != 2 or pts.shape[0] < 2 or pts.shape[1] < 3:
            return None
        finite = np.all(np.isfinite(pts[:, :3]), axis=1)
        pts = pts[finite, :3]
        if pts.shape[0] < 2:
            return None
        try:
            inset = max(float(vertex_inset), 0.0)
        except Exception:
            inset = 0.0
        out_points: list[np.ndarray] = []
        lines: list[int] = []
        last_segment_index = pts.shape[0] - 2
        for segment_index, (start, end) in enumerate(zip(pts[:-1], pts[1:])):
            start = np.asarray(start, dtype=float)
            end = np.asarray(end, dtype=float)
            delta = end - start
            length = float(np.linalg.norm(delta))
            if not np.isfinite(length) or length <= 1.0e-12:
                continue
            a = start.copy()
            b = end.copy()
            local_inset = min(inset, length * 0.20)
            if local_inset > 0.0:
                unit = delta / length
                if segment_index > 0:
                    a = a + unit * local_inset
                if segment_index < last_segment_index:
                    b = b - unit * local_inset
            if float(np.linalg.norm(b - a)) <= 1.0e-12:
                continue
            base = len(out_points)
            out_points.extend((a, b))
            lines.extend((2, base, base + 1))
        if not out_points:
            return None
        try:
            mesh = pv.PolyData(np.asarray(out_points, dtype=float))
            mesh.lines = np.asarray(lines, dtype=np.int64)
            return mesh
        except Exception:
            return None

    @staticmethod
    def _should_draw_3d_terminal_endpoint(
        terminal_status: str,
        *,
        show_terminal_diagnostics: bool = False,
    ) -> bool:
        status = str(terminal_status or "").strip().lower()
        if status == "hit_detector":
            return bool(show_terminal_diagnostics)
        if status in {"absorbed", "stopped"}:
            return bool(show_terminal_diagnostics)
        return False

    @staticmethod
    def _ray_terminal_3d_style(
        color: tuple[float, float, float],
        terminal_status: str,
    ) -> dict[str, object]:
        status = str(terminal_status or "").strip().lower()
        status_colors = {
            "hit_detector": (0.02, 0.48, 0.35),
            "missed_detector": (0.98, 0.45, 0.05),
            "absorbed": (0.35, 0.11, 0.55),
            "escaped": (0.36, 0.42, 0.50),
            "stopped": (0.50, 0.11, 0.11),
        }
        # Escaped rays are ordinary physical exits from the modeled scene. Keep
        # their source/wavelength color so prism output bundles do not look like
        # a different class of ray; reserve full-line diagnostic recoloring for
        # absorption and true stop conditions.
        diagnostic_line_color = status_colors.get(status, color) if status in {"absorbed", "stopped"} else color
        return {
            "line_color": diagnostic_line_color,
            "line_opacity": 0.80 if status == "escaped" else 0.74 if status == "missed_detector" else 0.88,
            "line_width": 1.5 if status == "missed_detector" else 1.0,
            "endpoint_color": status_colors.get(status, color),
            "endpoint_scale": 4.2 if status == "missed_detector" else 2.8,
        }

    def _scene_detector_overlay_specs(
        self,
        scene_bundle: SceneBundle | None,
        *,
        include_footprints: bool = True,
        include_miss_crosshairs: bool = True,
        cap_miss_crosshairs_to_scene: bool = False,
        display_center=None,
        display_radius: float = 1.0,
    ) -> list[dict[str, object]]:
        if scene_bundle is None:
            return []
        specs: list[dict[str, object]] = []
        targets = list(getattr(scene_bundle, "targets", []) or [])
        if bool(include_footprints):
            for target in targets:
                try:
                    row_index = int(getattr(target, "row_index", -1))
                except Exception:
                    row_index = -1
                for index, points in enumerate(scene_target_active_footprint_polylines(target)):
                    specs.append(
                        {
                            "kind": "detector_active_footprint" if index == 0 else "detector_active_center",
                            "row_index": row_index,
                            "points": np.asarray(points, dtype=float),
                            "color": (0.98, 0.45, 0.05),
                            "opacity": 0.92 if index == 0 else 0.72,
                            "line_width": 2.2 if index == 0 else 1.2,
                            "pickable": index == 0,
                        }
                    )

        if bool(include_miss_crosshairs):
            targets_by_surface = {}
            for target in targets:
                trace_surface = getattr(target, "trace_surface", None)
                if trace_surface is None:
                    continue
                try:
                    targets_by_surface[int(trace_surface)] = target
                except Exception:
                    continue
            for path in list(getattr(scene_bundle, "ray_paths", []) or []):
                metadata = ray_path_terminal_metadata(path)
                surface = metadata.get("detector_miss_surface")
                event = ray_path_terminal_event(path)
                if surface in (None, "") and event is not None:
                    surface = getattr(event, "surface_id", None)
                try:
                    target = targets_by_surface.get(int(surface))
                except Exception:
                    target = None
                if target is None:
                    continue
                try:
                    row_index = int(getattr(target, "row_index", -1))
                except Exception:
                    row_index = -1
                for points in self._detector_miss_crosshair_polylines_for_display(
                    path,
                    target,
                    display_center=display_center,
                    display_radius=display_radius,
                    cap_to_scene=bool(cap_miss_crosshairs_to_scene),
                ):
                    specs.append(
                        {
                            "kind": "detector_miss_crosshair",
                            "row_index": row_index,
                            "points": np.asarray(points, dtype=float),
                            "color": (0.92, 0.25, 0.05),
                            "opacity": 0.98,
                            "line_width": 2.4,
                            "pickable": False,
                        }
                    )
        return specs

    def _iter_3d_scene_rays(
        self,
        rays=None,
        scene_bundle: SceneBundle | None = None,
    ) -> list[tuple[tuple[float, float, float], np.ndarray]]:
        return [(color, points) for _ray_index, color, points in self._iter_3d_scene_ray_items(rays, scene_bundle)]

    def _configure_legacy_3d_plotter(
        self,
        plotter,
        *,
        ray_actors=None,
        mirror_actors=None,
        lens_actors=None,
        helper_actors=None,
    ) -> None:
        self._legacy_3d_scene_service()._configure_legacy_3d_plotter(
            plotter,
            ray_actors=ray_actors,
            mirror_actors=mirror_actors,
            lens_actors=lens_actors,
            helper_actors=helper_actors,
        )

    def _add_legacy_stl_placement_controls(self, plotter, positions: dict[str, object]) -> None:
        controls = (
            ("Fit+Z", lambda _state: self._legacy_3d_stl_fit_axis(plotter, "+Z")),
            ("Fit+X", lambda _state: self._legacy_3d_stl_fit_axis(plotter, "+X")),
            ("Fit+Y", lambda _state: self._legacy_3d_stl_fit_axis(plotter, "+Y")),
            ("X-90", lambda _state: self._legacy_3d_stl_rotate(plotter, "x", -90.0)),
            ("X+90", lambda _state: self._legacy_3d_stl_rotate(plotter, "x", 90.0)),
            ("Y-90", lambda _state: self._legacy_3d_stl_rotate(plotter, "y", -90.0)),
            ("Y+90", lambda _state: self._legacy_3d_stl_rotate(plotter, "y", 90.0)),
            ("Center", lambda _state: self._legacy_3d_stl_center_xy(plotter)),
            ("Front", lambda _state: self._legacy_3d_stl_front_on_row(plotter)),
            ("Done2D", lambda _state: self._legacy_3d_finish_stl_placement(plotter)),
        )
        for label, callback in controls:
            if label not in positions:
                continue
            self._add_legacy_3d_action_button(
                plotter,
                label=label,
                position=positions[label],
                callback=callback,
                color="#0891b2" if label != "Done2D" else "#0f766e",
            )

    def _legacy_3d_start_stl_placement(self, plotter, row_index: int) -> None:
        if plotter is None:
            return
        try:
            row_index = int(row_index)
        except Exception:
            self.status_var.set("Select an optical CAD/STL row first.")
            return
        if self._file_backed_stl_row_at(row_index) is None:
            self.status_var.set("Selected row is not a file-backed optical CAD/STL solid.")
            return
        setattr(plotter, "_kraken_stl_placement_row", row_index)
        self._select_table_row(row_index)
        self._legacy_3d_set_selected_row(plotter, row_index)
        self.status_var.set(f"Legacy 3D CAD/STL placement target S{row_index}. Use the placement buttons, then Done2D or close.")

    def _legacy_3d_active_stl_row(self, plotter) -> int | None:
        if plotter is None:
            self.status_var.set("Open 3D view before CAD/STL placement.")
            return None
        for candidate in (
            getattr(plotter, "_kraken_stl_placement_row", None),
            getattr(plotter, "_kraken_selected_row", None),
            self._current_selected_row_index(),
        ):
            if candidate is None:
                continue
            try:
                row_index = int(candidate)
            except Exception:
                continue
            if self._file_backed_stl_row_at(row_index) is not None:
                setattr(plotter, "_kraken_stl_placement_row", row_index)
                return row_index
        self.status_var.set("Select an optical CAD/STL row before using placement controls.")
        return None

    def _legacy_3d_stl_fit_axis(self, plotter, axis: str) -> None:
        row_index = self._legacy_3d_active_stl_row(plotter)
        if row_index is None:
            return
        try:
            self.apply_stl_axis_fit(row_index, axis)
            self._legacy_3d_update_stl_row_actor(plotter, row_index)
            self.status_var.set(f"STL S{row_index}: fitted {axis} to layout +Z.")
        except Exception as exc:
            self.status_var.set(f"STL fit failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL fit failed: {exc}")

    def _legacy_3d_stl_rotate(self, plotter, axis: str, delta_deg: float) -> None:
        row_index = self._legacy_3d_active_stl_row(plotter)
        if row_index is None:
            return
        try:
            self.rotate_stl_row_pose(row_index, axis, delta_deg)
            self._legacy_3d_update_stl_row_actor(plotter, row_index)
            self.status_var.set(f"STL S{row_index}: rotated {axis.upper()} {float(delta_deg):+.0f} deg.")
        except Exception as exc:
            self.status_var.set(f"STL rotation failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL rotation failed: {exc}")

    def _legacy_3d_stl_center_xy(self, plotter) -> None:
        row_index = self._legacy_3d_active_stl_row(plotter)
        if row_index is None:
            return
        try:
            self.center_stl_row_xy(row_index)
            self._legacy_3d_update_stl_row_actor(plotter, row_index)
            self.status_var.set(f"STL S{row_index}: centered X/Y.")
        except Exception as exc:
            self.status_var.set(f"STL centering failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL centering failed: {exc}")

    def _legacy_3d_stl_front_on_row(self, plotter) -> None:
        row_index = self._legacy_3d_active_stl_row(plotter)
        if row_index is None:
            return
        try:
            self.place_stl_row_front_on_station(row_index)
            self._legacy_3d_update_stl_row_actor(plotter, row_index)
            self.status_var.set(f"STL S{row_index}: min Z placed on row plane.")
        except Exception as exc:
            self.status_var.set(f"STL front placement failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL front placement failed: {exc}")

    def _legacy_3d_finish_stl_placement(self, plotter) -> None:
        if plotter is not None:
            setattr(plotter, "_kraken_stl_placement_dirty", False)
        try:
            self.refresh_plot(suppress_analysis=True)
            self.status_var.set("CAD/STL placement applied to 2D layout.")
        except Exception as exc:
            self.status_var.set(f"CAD/STL placement saved; 2D refresh failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL Done2D failed: {exc}")

    def _legacy_3d_update_stl_row_actor(self, plotter, row_index: int) -> None:
        if plotter is None or pv is None:
            return
        selected = self._file_backed_stl_row_at(row_index)
        if selected is None:
            raise RuntimeError("Selected row is not a file-backed optical STL solid")
        row, path = selected
        mesh = pv.read(path).extract_surface(algorithm="dataset_surface").copy(deep=True)
        pts = np.asarray(mesh.points, dtype=float)
        if pts.ndim != 2 or pts.shape[0] == 0 or pts.shape[1] < 3:
            raise RuntimeError("STL mesh has no previewable points")
        rotation = _rotation_matrix_from_kraken_tilts(row.tilt_x, row.tilt_y, row.tilt_z)
        transformed = pts[:, :3] @ rotation.T
        transformed[:, 0] += float(row.desp_x)
        transformed[:, 1] += float(row.desp_y)
        transformed[:, 2] += self._stl_row_z_station(row_index) + float(row.desp_z)
        mesh.points = transformed

        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        row_actor_map = scene_info.setdefault("row_actor_map", {})
        actor_row_map = scene_info.setdefault("actor_row_map", {})
        for actor in list(row_actor_map.get(int(row_index), []) or []):
            try:
                actor_key = Kraken3DInspector._actor_key(actor)
                if actor_key is not None:
                    actor_row_map.pop(actor_key, None)
                plotter.remove_actor(actor, render=False)
            except Exception:
                try:
                    actor.SetVisibility(False)
                except Exception:
                    pass

        new_actors = []
        actor = plotter.add_mesh(
            mesh,
            color="#0ccfe8",
            opacity=0.68,
            smooth_shading=True,
            show_edges=False,
            pickable=True,
        )
        self._legacy_3d_register_row_actor(actor, int(row_index), actor_row_map, new_actors)
        try:
            edges = mesh.extract_feature_edges(
                feature_angle=15,
                boundary_edges=True,
                feature_edges=True,
                manifold_edges=False,
            )
            if int(getattr(edges, "n_points", 0)) > 0:
                edge_actor = plotter.add_mesh(edges, color="#1f2937", line_width=1.0, pickable=False)
                self._legacy_3d_register_row_actor(edge_actor, int(row_index), actor_row_map, new_actors)
        except Exception:
            pass
        row_actor_map[int(row_index)] = new_actors
        setattr(plotter, "_kraken_scene", scene_info)
        setattr(plotter, "_kraken_stl_placement_row", int(row_index))
        setattr(plotter, "_kraken_stl_placement_dirty", True)
        setattr(plotter, "_kraken_selected_row", None)
        self._legacy_3d_set_selected_row(plotter, int(row_index))
        try:
            plotter.render()
        except Exception:
            pass

    @staticmethod
    def _legacy_3d_register_row_actor(actor, row_index: int, actor_row_map: dict, row_actors: list) -> None:
        if actor is None:
            return
        try:
            actor.SetPickable(True)
        except Exception:
            pass
        actor_key = Kraken3DInspector._actor_key(actor)
        if actor_key is not None:
            actor_row_map[actor_key] = int(row_index)
        try:
            prop = actor.GetProperty()
            if prop is not None:
                actor._kraken_base_style = {
                    "edge_visibility": int(prop.GetEdgeVisibility()),
                    "line_width": float(prop.GetLineWidth()),
                    "edge_color": tuple(float(v) for v in prop.GetEdgeColor()),
                    "opacity": float(prop.GetOpacity()),
                    "ambient": float(prop.GetAmbient()),
                    "diffuse": float(prop.GetDiffuse()),
                }
        except Exception:
            pass
        row_actors.append(actor)

    @staticmethod
    def _legacy_3d_control_positions(plotter) -> dict[str, object]:
        try:
            width = int(plotter.window_size[0])
        except Exception:
            width = 1200
        # Use the full lower edge and reserve a left gutter for category names.
        category_x = 18
        start_x = 118 if width >= 900 else 96
        right_margin = 110
        rows = [
            ("View", ["Save", "Close", "Iso", "YZ", "XZ", "Top", "Bottom", "Home"], "#334155"),
            ("Show/CAD", ["Rays", "Mirrors", "Lenses", "Helpers", "Full Pupil", "Lens CAD", "LED CAD", "Cam CAD"], "#0f766e"),
            (
                "STEP",
                ["X -90", "X +90", "Y -90", "Y +90", "Z -90", "Z +90", "Center STEP", "Obj-LED", "Clear Axis"],
                "#7c3aed",
            ),
            ("STL", ["Fit+Z", "Fit+X", "Fit+Y", "X-90", "X+90", "Y-90", "Y+90", "Center", "CenterRay", "Front", "Done2D"], "#0891b2"),
        ]
        y_positions = [12, 50, 88, 126]
        positions: dict[str, object] = {"__categories__": []}
        usable = max(width - start_x - right_margin, 480)
        for (category, row, color), y_pos in zip(rows, y_positions):
            positions["__categories__"].append((category, (category_x, y_pos + 4), color))
            step_x = max(int(usable / max(len(row) - 1, 1)), 96)
            for index, label in enumerate(row):
                positions[label] = (start_x + int(index * step_x), y_pos)
        return positions

    def _enable_legacy_3d_close_handling(self, plotter) -> None:
        def request_close(*_args):
            try:
                self.after(0, self._close_legacy_3d_plotter)
            except Exception:
                self._close_legacy_3d_plotter()

        try:
            if getattr(plotter, "iren", None) is not None:
                plotter.iren.add_observer("ExitEvent", request_close)
        except Exception as exc:
            self.append_debug(f"Legacy 3D close observer unavailable: {exc}")
        try:
            if getattr(plotter, "render_window", None) is not None:
                plotter.render_window.AddObserver("DeleteEvent", request_close)
        except Exception:
            pass

    def _enable_legacy_3d_picking(self, plotter) -> None:
        if vtkCellPicker is None or getattr(plotter, "iren", None) is None:
            return
        try:
            picker = vtkCellPicker()
            picker.SetTolerance(0.0015)
            setattr(plotter, "_kraken_picker", picker)
            setattr(plotter, "_kraken_selected_row", None)
            setattr(plotter, "_kraken_selected_ray", None)
            setattr(plotter, "_kraken_center_row_to_ray_mode", False)
            setattr(plotter, "_kraken_center_row_to_ray_index", None)
            plotter.iren.add_observer(
                "LeftButtonPressEvent",
                lambda *_args: self._legacy_3d_pick_click(plotter),
            )
            plotter.iren.add_observer(
                "MouseMoveEvent",
                lambda *_args: self._legacy_3d_hover_move(plotter),
            )
        except Exception as exc:
            self.append_debug(f"Legacy 3D picking unavailable: {exc}")

    def _legacy_3d_hover_move(self, plotter) -> None:
        requested_label = self._cad_axis_pick_label
        axis_pick_any = bool(getattr(self, "_cad_axis_pick_any", False))
        led_edge_pick = bool(getattr(self, "_cad_led_object_edge_pick", False))
        target_label = "led" if led_edge_pick else requested_label
        if target_label is None and not axis_pick_any:
            self._legacy_3d_set_step_hover_outline(plotter, None, None)
            self._legacy_3d_set_cursor(plotter, False)
            return
        picker = getattr(plotter, "_kraken_picker", None)
        if picker is None or getattr(plotter, "iren", None) is None:
            return
        try:
            x, y = plotter.iren.get_event_position()
            renderer = plotter.iren.get_poked_renderer(x, y)
            if renderer is None:
                renderer = getattr(plotter, "renderer", None)
            if renderer is None:
                return
            picker.Pick(x, y, 0.0, renderer)
            actor = picker.GetActor()
        except Exception:
            actor = None
        actor_key = Kraken3DInspector._actor_key(actor)
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        step_label = scene_info.get("cad_step_actor_map", {}).get(actor_key) if actor_key is not None else None
        if step_label is not None and (axis_pick_any or step_label == target_label):
            try:
                cell_id = int(picker.GetCellId())
            except Exception:
                cell_id = -1
            hover_key = (actor_key, cell_id)
            outline = None
            if hover_key != getattr(plotter, "_kraken_step_hover_key", None):
                feature = Kraken3DInspector._picked_feature_info(actor, picker)
                outline = Kraken3DInspector._hover_overlay_for_feature(feature[0], feature[1]) if feature is not None else None
            self._legacy_3d_set_step_hover_outline(plotter, outline, hover_key)
            self._legacy_3d_set_cursor(plotter, True)
            if led_edge_pick:
                self.status_var.set("Click orange LED edge used for Object-to-LED distance.")
            elif axis_pick_any:
                self.status_var.set(f"Click orange {step_label} feature to center it on the optical axis.")
            else:
                self.status_var.set(f"Click orange {step_label} feature to center it on the optical axis.")
            return
        self._legacy_3d_set_step_hover_outline(plotter, None, None)
        self._legacy_3d_set_cursor(plotter, False)

    def _legacy_3d_set_step_hover_outline(self, plotter, outline_mesh, hover_key) -> None:
        if hover_key is not None and hover_key == getattr(plotter, "_kraken_step_hover_key", None):
            return
        previous = getattr(plotter, "_kraken_step_hover_outline_actor", None)
        if previous is not None:
            try:
                plotter.remove_actor(previous, render=False)
            except Exception:
                try:
                    previous.SetVisibility(False)
                except Exception:
                    pass
        setattr(plotter, "_kraken_step_hover_outline_actor", None)
        setattr(plotter, "_kraken_step_hover_key", hover_key)
        if outline_mesh is not None and int(getattr(outline_mesh, "n_points", 0)) > 0:
            try:
                actor = plotter.add_mesh(
                    outline_mesh,
                    color="#ff2d00",
                    line_width=9.0,
                    opacity=1.0,
                    lighting=False,
                    ambient=1.0,
                    render_lines_as_tubes=True,
                    pickable=False,
                )
                try:
                    actor.SetPickable(False)
                except Exception:
                    pass
                setattr(plotter, "_kraken_step_hover_outline_actor", actor)
            except Exception as exc:
                self.append_debug(f"3D STEP hover outline failed: {exc}")
        try:
            plotter.render()
        except Exception:
            pass

    @staticmethod
    def _legacy_3d_set_cursor(plotter, hand: bool) -> None:
        try:
            if getattr(plotter, "iren", None) is not None and getattr(plotter.iren, "interactor", None) is not None:
                cursor = 9 if hand else 0
                plotter.iren.interactor.SetCurrentCursor(cursor)
                try:
                    render_window = plotter.iren.interactor.GetRenderWindow()
                    if render_window is not None:
                        render_window.SetCurrentCursor(cursor)
                except Exception:
                    pass
        except Exception:
            pass

    def _legacy_3d_pick_click(self, plotter) -> None:
        picker = getattr(plotter, "_kraken_picker", None)
        if picker is None or getattr(plotter, "iren", None) is None:
            return
        try:
            x, y = plotter.iren.get_event_position()
            renderer = plotter.iren.get_poked_renderer(x, y)
            if renderer is None:
                renderer = getattr(plotter, "renderer", None)
            if renderer is None:
                return
            picker.Pick(x, y, 0.0, renderer)
            actor = picker.GetActor()
        except Exception as exc:
            self.append_debug(f"Legacy 3D pick failed: {exc}")
            return
        actor_key = Kraken3DInspector._actor_key(actor)
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        step_label = scene_info.get("cad_step_actor_map", {}).get(actor_key) if actor_key is not None else None
        axis_pick_any = bool(getattr(self, "_cad_axis_pick_any", False))
        if step_label is not None:
            if self._cad_led_object_edge_pick:
                if step_label != "led":
                    self.status_var.set("Pick an edge on the LED STEP for Object-to-LED distance.")
                    return
                feature = Kraken3DInspector._picked_feature_info(actor, picker)
                if feature is None:
                    try:
                        center = np.asarray(picker.GetPickPosition(), dtype=float)
                    except Exception:
                        center = None
                else:
                    center = feature[0]
                if center is None or center.size < 3 or not np.all(np.isfinite(center[:3])):
                    self.status_var.set("Could not detect LED object-edge center.")
                    return
                self._legacy_3d_set_step_hover_outline(plotter, None, None)
                self._legacy_3d_set_cursor(plotter, False)
                self.apply_led_object_edge_pick(center[:3])
                return
            requested_label = self._cad_axis_pick_label
            if requested_label is None and not axis_pick_any:
                self.select_step_component(step_label)
                self._legacy_3d_set_selected_step(plotter, step_label)
                return
            if requested_label is not None and requested_label != step_label:
                self.status_var.set(f"CAD STEP picked: {step_label}. Center mode is armed for {str(requested_label).upper()}.")
                return
            feature = Kraken3DInspector._picked_feature_info(actor, picker)
            if feature is None:
                try:
                    center = np.asarray(picker.GetPickPosition(), dtype=float)
                except Exception:
                    center = None
            else:
                center = feature[0]
            if center is None or center.size < 3 or not np.all(np.isfinite(center[:3])):
                self.status_var.set(f"Could not detect {step_label} feature center.")
                return
            self._legacy_3d_set_step_hover_outline(plotter, None, None)
            self._legacy_3d_set_cursor(plotter, False)
            self._cad_axis_pick_any = False
            self.apply_step_axis_pick(step_label, center[:3])
            return
        row_index = scene_info.get("actor_row_map", {}).get(actor_key) if actor_key is not None else None
        ray_index = scene_info.get("actor_ray_map", {}).get(actor_key) if actor_key is not None else None
        requested_label = self._cad_axis_pick_label
        surface_target_label = requested_label
        if surface_target_label is None and axis_pick_any:
            selected_label = getattr(self, "_selected_step_label", None)
            if selected_label in STEP_OVERLAY_LABEL_SET and self._step_path_for_label(str(selected_label)) is not None:
                surface_target_label = str(selected_label)
        if surface_target_label is not None and row_index is not None:
            if bool(getattr(self, "_cad_led_object_edge_pick", False)):
                self.status_var.set("Pick an edge on the LED STEP for Object-to-LED distance.")
                return
            try:
                result = self.center_step_axis_on_surface(str(surface_target_label), int(row_index))
            except Exception as exc:
                self.status_var.set(f"Axis {str(surface_target_label).upper()} failed: {_short_error_message(exc)}")
                self.append_debug(f"Legacy 3D STEP surface-axis pick failed: {exc}")
                return
            self._legacy_3d_set_step_hover_outline(plotter, None, None)
            self._legacy_3d_set_cursor(plotter, False)
            self._legacy_3d_set_selected_row(plotter, int(row_index))
            self._legacy_3d_set_selected_ray(plotter, None)
            row_name = self.rows[int(row_index)].name if 0 <= int(row_index) < len(self.rows) else "Surface"
            if result is not None:
                target = result.get("target", (float("nan"), float("nan"), float("nan")))
                self.status_var.set(
                    f"{str(surface_target_label).upper()} STEP axis centered on S{int(row_index)}: {row_name} "
                    f"at X/Y=({float(target[0]):.6g}, {float(target[1]):.6g}) mm."
                )
            return
        if axis_pick_any and row_index is not None:
            self.status_var.set("Center STEP Axis: click a STEP feature, or select a STEP component before clicking a KrakenOS surface.")
            return
        if ray_index is not None:
            if bool(getattr(plotter, "_kraken_center_row_to_ray_mode", False)):
                self._legacy_3d_apply_center_row_to_ray(plotter, int(ray_index))
                return
            self._legacy_3d_set_selected_row(plotter, None)
            self._legacy_3d_set_selected_ray(plotter, int(ray_index))
            self._select_ray_inspector_ray(int(ray_index))
            self.status_var.set(self._ray_terminal_hint_text(int(ray_index), label=f"3D selected ray {int(ray_index)} in Ray Inspector"))
            return
        if row_index is None:
            self._legacy_3d_set_selected_row(plotter, None)
            self._legacy_3d_set_selected_ray(plotter, None)
            self.status_var.set("3D view ready")
            return
        self._legacy_3d_set_selected_row(plotter, int(row_index))
        self._legacy_3d_set_selected_ray(plotter, None)
        self._select_table_row(int(row_index))
        row_name = self.rows[int(row_index)].name if 0 <= int(row_index) < len(self.rows) else "Surface"
        if bool(getattr(plotter, "_kraken_center_row_to_ray_mode", False)):
            if 0 <= int(row_index) < len(self.rows) and self.rows[int(row_index)].surface in {"Object", "Image"}:
                self.status_var.set("CenterRay: choose a physical surface/CAD row, not Object/Image.")
                return
            setattr(plotter, "_kraken_center_row_to_ray_index", int(row_index))
            self.status_var.set(f"CenterRay: selected S{int(row_index)}: {row_name}. Now click the target ray.")
            return
        if self._file_backed_stl_row_at(int(row_index)) is not None:
            setattr(plotter, "_kraken_stl_placement_row", int(row_index))
            self.status_var.set(f"3D selected CAD/STL row {int(row_index)}: {row_name}. Use the placement buttons, then Done2D or close.")
        else:
            self.status_var.set(f"3D selected row {int(row_index)}: {row_name}")

    def _legacy_3d_start_center_row_to_ray(self, plotter) -> None:
        if plotter is None:
            return
        row_index = getattr(plotter, "_kraken_selected_row", None)
        if row_index is None:
            row_index = self._current_selected_row_index()
        setattr(plotter, "_kraken_center_row_to_ray_mode", True)
        if row_index is not None:
            try:
                row_index = int(row_index)
            except Exception:
                row_index = None
        if row_index is not None and 0 <= row_index < len(self.rows) and self.rows[row_index].surface not in {"Object", "Image"}:
            setattr(plotter, "_kraken_center_row_to_ray_index", row_index)
            self._legacy_3d_set_selected_row(plotter, row_index)
            self.status_var.set(f"CenterRay: selected S{row_index}. Click the ray that should pass through its center.")
            return
        setattr(plotter, "_kraken_center_row_to_ray_index", None)
        self.status_var.set("CenterRay: click the surface/CAD row to move, then click the target ray.")

    def _legacy_3d_apply_center_row_to_ray(self, plotter, ray_index: int) -> None:
        row_index = getattr(plotter, "_kraken_center_row_to_ray_index", None)
        if row_index is None:
            self.status_var.set("CenterRay: click a surface/CAD row first, then click the target ray.")
            return
        try:
            row_index = int(row_index)
            ray_index = int(ray_index)
            result = self.center_surface_row_on_ray(row_index, ray_index)
        except Exception as exc:
            self.status_var.set(f"CenterRay failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy CenterRay failed: {exc}")
            return
        setattr(plotter, "_kraken_center_row_to_ray_mode", False)
        setattr(plotter, "_kraken_center_row_to_ray_index", None)
        try:
            if self._file_backed_stl_row_at(row_index) is not None:
                self._legacy_3d_update_stl_row_actor(plotter, row_index)
            self._legacy_3d_replace_rays(plotter)
            self._legacy_3d_set_selected_row(plotter, row_index)
            self._legacy_3d_set_selected_ray(plotter, ray_index)
        except Exception as exc:
            self.append_debug(f"Legacy CenterRay refresh failed: {exc}")
        target = result.get("target", (float("nan"), float("nan"), float("nan")))
        self.status_var.set(
            "Centered S{row} on ray {ray} at ({x:.6g}, {y:.6g}, {z:.6g}) mm. "
            "Click Done2D or Update to refresh 2D.".format(
                row=row_index,
                ray=ray_index,
                x=float(target[0]),
                y=float(target[1]),
                z=float(target[2]),
            )
        )

    def _legacy_3d_set_selected_row(self, plotter, row_index: int | None) -> None:
        current = getattr(plotter, "_kraken_selected_row", None)
        if current == row_index:
            return
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        row_actor_map = dict(scene_info.get("row_actor_map", {}) or {})
        if current is not None:
            for actor in row_actor_map.get(int(current), []):
                self._legacy_3d_set_actor_highlight(actor, False)
        if row_index is not None:
            for actor in row_actor_map.get(int(row_index), []):
                self._legacy_3d_set_actor_highlight(actor, True)
        setattr(plotter, "_kraken_selected_row", row_index)
        try:
            plotter.render()
        except Exception:
            pass

    def _legacy_3d_set_selected_ray(self, plotter, ray_index: int | None) -> None:
        current = getattr(plotter, "_kraken_selected_ray", None)
        if current == ray_index:
            return
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        ray_actor_map = dict(scene_info.get("ray_actor_map", {}) or {})
        if current is not None:
            for actor in ray_actor_map.get(int(current), []):
                Kraken3DInspector._set_ray_actor_selected(actor, False)
        if ray_index is not None:
            for actor in ray_actor_map.get(int(ray_index), []):
                Kraken3DInspector._set_ray_actor_selected(actor, True)
        setattr(plotter, "_kraken_selected_ray", ray_index)
        try:
            plotter.render()
        except Exception:
            pass

    def _legacy_3d_set_selected_step(self, plotter, label: str | None) -> None:
        label = str(label).strip().lower() if label is not None else None
        if label not in STEP_OVERLAY_LABEL_SET:
            label = None
        current = getattr(plotter, "_kraken_selected_step", None)
        if current == label:
            return
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        cad_step_actors = dict(scene_info.get("cad_step_actors", {}) or {})
        if current is not None:
            for _kind, actor in list(cad_step_actors.get(current, []) or []):
                Kraken3DInspector._set_step_actor_selected(actor, False)
        if label is not None:
            for _kind, actor in list(cad_step_actors.get(label, []) or []):
                Kraken3DInspector._set_step_actor_selected(actor, True)
        setattr(plotter, "_kraken_selected_step", label)
        try:
            plotter.render()
        except Exception:
            pass

    @staticmethod
    def _legacy_3d_set_actor_highlight(actor, selected: bool) -> None:
        if actor is None:
            return
        try:
            prop = actor.GetProperty()
        except Exception:
            return
        if prop is None:
            return
        base = getattr(actor, "_kraken_base_style", None)
        if not isinstance(base, dict):
            try:
                base = {
                    "edge_visibility": int(prop.GetEdgeVisibility()),
                    "line_width": float(prop.GetLineWidth()),
                    "edge_color": tuple(float(v) for v in prop.GetEdgeColor()),
                    "opacity": float(prop.GetOpacity()),
                    "ambient": float(prop.GetAmbient()),
                    "diffuse": float(prop.GetDiffuse()),
                }
                actor._kraken_base_style = base
            except Exception:
                base = {}
        if selected:
            try:
                prop.SetEdgeVisibility(1)
                prop.SetEdgeColor(1.0, 0.45, 0.05)
                prop.SetLineWidth(max(float(base.get("line_width", 1.0)), 2.5))
                prop.SetOpacity(min(max(float(base.get("opacity", 1.0)), 0.3) + 0.08, 1.0))
                prop.SetAmbient(max(float(base.get("ambient", 0.0)), 0.18))
            except Exception:
                return
            return
        try:
            prop.SetEdgeVisibility(int(base.get("edge_visibility", 0)))
            edge_color = tuple(base.get("edge_color", (0.0, 0.0, 0.0)))
            if len(edge_color) == 3:
                prop.SetEdgeColor(*edge_color)
            prop.SetLineWidth(float(base.get("line_width", 1.0)))
            prop.SetOpacity(float(base.get("opacity", 1.0)))
            prop.SetAmbient(float(base.get("ambient", 0.0)))
            prop.SetDiffuse(float(base.get("diffuse", 1.0)))
        except Exception:
            pass

    def _add_legacy_3d_action_button(
        self,
        plotter,
        *,
        label: str,
        position: tuple[int, int],
        callback,
        value: bool = False,
        color: str = "#2563eb",
    ) -> None:
        plotter.add_checkbox_button_widget(
            callback,
            value=value,
            position=position,
            size=22,
            border_size=3,
            color_on=color,
            color_off=color,
            background_color="white",
        )
        plotter.add_text(
            label,
            position=(position[0] + 28, position[1] + 1),
            font_size=9,
            color="black",
        )

    def _legacy_3d_set_actor_visibility(self, actors, visible: bool, plotter, group: str | None = None) -> None:
        if group:
            state = dict(getattr(plotter, "_kraken_visibility", {}) or {})
            state[group] = bool(visible)
            setattr(plotter, "_kraken_visibility", state)
        for actor in actors:
            try:
                actor.SetVisibility(bool(visible))
            except Exception:
                continue
        plotter.render()

    def _legacy_3d_set_scene_actor_visibility(self, plotter, actor_key: str, visible: bool, group: str) -> None:
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        self._legacy_3d_set_actor_visibility(scene_info.get(actor_key, []) or [], visible, plotter, group)

    def _legacy_3d_set_step_visibility(self, plotter, label: str, visible: bool) -> None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return
        state = dict(getattr(plotter, "_kraken_visibility", {}) or {})
        state[f"step_{label}"] = bool(visible)
        setattr(plotter, "_kraken_visibility", state)
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        actors = list(scene_info.get("cad_step_actors", {}).get(label, []) or [])
        for _kind, actor in actors:
            try:
                actor.SetVisibility(bool(visible))
            except Exception:
                continue
        if not visible and self._selected_step_label == label:
            self._legacy_3d_set_selected_step(plotter, None)
            self._selected_step_label = None
        self.status_var.set(f"{label.upper()} STEP {'shown' if visible else 'hidden'}.")
        try:
            plotter.render()
        except Exception:
            pass

    def _legacy_3d_toggle_full_pupil(self, plotter, state: bool) -> None:
        """Toggle full-pupil ray mode and retrace.

        Only the ray actors are swapped — buttons / lens / mirror actors stay
        put. Rebuilding the entire scene used to stack a fresh Full Pupil
        checkbox on top of the previous one each click, which made the toggle
        appear to be one-way (ON → ON → ON…).
        """
        # PyVista fires the callback on widget creation with the initial value.
        # Skip the no-op so we don't retrace on startup.
        if bool(state) == self._is_full_pupil_mode():
            return
        self.emit_full_ray_var.set(bool(state))
        try:
            self._legacy_3d_replace_rays(plotter)
        except Exception as exc:
            self.append_debug(f"Full Pupil refresh failed: {exc}")

    def _legacy_3d_replace_rays(self, plotter) -> None:
        """Rebuild only the ray actors in the existing 3D scene, in place."""
        scene_info = getattr(plotter, "_kraken_scene", None)
        if not isinstance(scene_info, dict):
            scene_info = {}
            setattr(plotter, "_kraken_scene", scene_info)
        ray_actors = scene_info.setdefault("ray_actors", [])
        for actor in list(ray_actors):
            try:
                plotter.renderer.RemoveActor(actor)
            except Exception:
                pass
        ray_actors.clear()
        scene_info["actor_ray_map"] = {}
        scene_info["ray_actor_map"] = {}
        setattr(plotter, "_kraken_selected_ray", None)
        system, rays = self._build_preview_system_and_rays()
        scene_bundle = self._last_scene_bundle
        setattr(plotter, "_kraken_system", system)
        setattr(plotter, "_kraken_rays", rays)
        setattr(plotter, "_kraken_scene_bundle", scene_bundle)
        rays_visible = bool(dict(getattr(plotter, "_kraken_visibility", {}) or {}).get("rays", True))
        ray_radius = self._legacy_3d_ray_radius(system, rays)
        if scene_bundle is not None:
            ray_center, ray_scene_radius = scene_display_center_radius(scene_bundle)
        else:
            ray_center, ray_scene_radius = self._scene_center_radius_from_bounds(plotter.bounds)
        paths_by_ray_index = self._scene_ray_path_by_index(scene_bundle)
        suppressed_endpoint_count = 0
        for ray_index, color, ray_pts, terminal_status in self._iter_3d_scene_ray_records(rays, scene_bundle):
            ray_path = paths_by_ray_index.get(int(ray_index))
            terminal_target = self._missed_detector_target_for_path(scene_bundle, ray_path)
            terminal_direction = self._terminal_display_direction_for_path(ray_path)
            display_ray_pts, _was_bounded = self._bounded_3d_ray_points_for_display(
                ray_pts,
                ray_center,
                ray_scene_radius,
                terminal_status=terminal_status,
                terminal_target=terminal_target,
                terminal_direction=terminal_direction,
            )
            line = self._ray_segment_mesh_for_3d_display(
                display_ray_pts,
                vertex_inset=self._ray_vertex_display_inset(ray_scene_radius),
            )
            if line is None:
                continue
            if int(getattr(line, "n_points", 0)) < 2:
                continue
            style = KrakenLayoutEditor._ray_terminal_3d_style(color, terminal_status)
            actor = plotter.add_mesh(
                line,
                color=style["line_color"],
                opacity=float(style["line_opacity"]),
                line_width=float(style["line_width"]),
                pickable=True,
            )
            actor_key = Kraken3DInspector._actor_key(actor)
            if actor_key is not None:
                scene_info["actor_ray_map"][actor_key] = int(ray_index)
                scene_info["ray_actor_map"].setdefault(int(ray_index), []).append(actor)
            try:
                actor.SetPickable(True)
                prop = actor.GetProperty()
                if prop is not None:
                    actor._kraken_ray_select_style = {
                        "color": tuple(float(v) for v in prop.GetColor()),
                        "line_width": float(prop.GetLineWidth()),
                        "opacity": float(prop.GetOpacity()),
                        "ambient": float(prop.GetAmbient()),
                        "diffuse": float(prop.GetDiffuse()),
                    }
            except Exception:
                pass
            try:
                actor.SetVisibility(rays_visible)
            except Exception:
                pass
            ray_actors.append(actor)
            if not self._should_draw_3d_terminal_endpoint(
                terminal_status,
                show_terminal_diagnostics=bool(self.show_terminal_diagnostics_var.get()),
            ):
                suppressed_endpoint_count += 1
                continue
            try:
                endpoint = np.asarray(display_ray_pts[-1], dtype=float).reshape(-1)[:3]
                if endpoint.size >= 3 and np.all(np.isfinite(endpoint)):
                    marker = pv.Sphere(
                        radius=max(float(ray_radius) * float(style["endpoint_scale"]), 0.08),
                        center=tuple(endpoint[:3]),
                        theta_resolution=16 if terminal_status == "missed_detector" else 12,
                        phi_resolution=10 if terminal_status == "missed_detector" else 8,
                    )
                    marker_actor = plotter.add_mesh(
                        marker,
                        color=style["endpoint_color"],
                        opacity=0.96,
                        smooth_shading=False,
                        pickable=True,
                    )
                    marker_key = Kraken3DInspector._actor_key(marker_actor)
                    if marker_key is not None:
                        scene_info["actor_ray_map"][marker_key] = int(ray_index)
                        scene_info["ray_actor_map"].setdefault(int(ray_index), []).append(marker_actor)
                    try:
                        marker_actor.SetVisibility(rays_visible)
                    except Exception:
                        pass
                    ray_actors.append(marker_actor)
            except Exception:
                pass
        if suppressed_endpoint_count:
            self.append_debug(f"Legacy 3D suppressed {suppressed_endpoint_count} non-physical escaped/missed terminal endpoint markers.")
        try:
            plotter.render()
        except Exception:
            pass

    def _save_legacy_3d_screenshot(self, plotter) -> None:
        try:
            default_name = f"kraken_3d_{time.strftime('%Y%m%d_%H%M%S')}.png"
            try:
                SCREENSHOT_DIR.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            selected_path = filedialog.asksaveasfilename(
                parent=self,
                title="Save 3D view as PNG",
                initialdir=str(SCREENSHOT_DIR),
                initialfile=default_name,
                defaultextension=".png",
                filetypes=[("PNG image", "*.png")],
            )
            if not selected_path:
                self.status_var.set("3D PNG save cancelled")
                return
            image_path = Path(selected_path)
            system = getattr(plotter, "_kraken_system", None)
            rays = getattr(plotter, "_kraken_rays", None)
            scene_bundle = getattr(plotter, "_kraken_scene_bundle", None)
            if system is None or rays is None:
                raise RuntimeError("3D scene data unavailable for clean screenshot")
            self._last_scene_bundle = scene_bundle if isinstance(scene_bundle, SceneBundle) else self._last_scene_bundle
            clean_plotter = self._build_clean_legacy_3d_plotter(system, rays)
            clean_scene = dict(getattr(clean_plotter, "_kraken_scene", {}) or {})
            visibility = dict(getattr(plotter, "_kraken_visibility", {}) or {})
            if not visibility.get("rays", True):
                self._legacy_3d_set_actor_visibility(clean_scene.get("ray_actors", []), False, clean_plotter)
            if not visibility.get("mirrors", True):
                self._legacy_3d_set_actor_visibility(clean_scene.get("mirror_actors", []), False, clean_plotter)
            if not visibility.get("lenses", True):
                self._legacy_3d_set_actor_visibility(clean_scene.get("lens_actors", []), False, clean_plotter)
            if not visibility.get("helpers", True):
                self._legacy_3d_set_actor_visibility(clean_scene.get("helper_actors", []), False, clean_plotter)
            try:
                clean_plotter.camera_position = plotter.camera_position
                clean_plotter.camera.parallel_projection = bool(plotter.camera.parallel_projection)
                clean_plotter.camera.parallel_scale = float(plotter.camera.parallel_scale)
            except Exception:
                self._set_legacy_3d_camera(clean_plotter, "iso")
            clean_plotter.screenshot(str(image_path))
            try:
                rw = getattr(clean_plotter, "render_window", None)
                if rw is not None:
                    rw.Finalize()
                clean_plotter.close()
            except Exception:
                pass
            self.status_var.set(f"Saved 3D PNG: {image_path.name}")
            self.append_progress(f"Saved 3D PNG: {image_path}")
        except Exception as exc:
            self.append_debug(f"3D screenshot failed: {exc}")
            self.status_var.set(f"3D screenshot failed: {_short_error_message(exc)}")

    @staticmethod
    def _legacy_3d_camera_preset_from_display_orientation(orientation: str) -> str:
        plane = normalize_projection_plane(orientation)
        if plane == "XZ":
            return "xz"
        if plane == "XY":
            return "top"
        return "yz"

    @staticmethod
    def _set_legacy_3d_camera(plotter, preset: str) -> None:
        cx, cy, cz = plotter.center
        bounds = np.asarray(plotter.bounds, dtype=float)
        span_x = float(bounds[1] - bounds[0]) if bounds.size >= 2 else 0.0
        span_y = float(bounds[3] - bounds[2]) if bounds.size >= 4 else 0.0
        span_z = float(bounds[5] - bounds[4]) if bounds.size >= 6 else 0.0
        span = max(span_x, span_y, span_z, 1.0)
        distance = max(span * 2.6, 180.0)
        try:
            width, height = plotter.window_size
            aspect = max(float(width) / max(float(height), 1.0), 0.1)
        except Exception:
            aspect = 1.4

        def orthographic_scale(horizontal_span: float, vertical_span: float) -> float:
            horizontal_scale = float(horizontal_span) / (2.0 * aspect)
            vertical_scale = float(vertical_span) * 0.5
            return max(horizontal_scale, vertical_scale, 1.0) * 1.08

        if preset == "yz":
            position = (cx - distance, cy, cz)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = orthographic_scale(span_z, span_y)
        elif preset == "top":
            # Exact top view. This used to conflict only because VTK binds the numeric `3` key to stereo.
            position = (cx, cy, cz + distance)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = orthographic_scale(span_x, span_y)
        elif preset == "bottom":
            position = (cx, cy, cz - distance)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = orthographic_scale(span_x, span_y)
        elif preset == "xz":
            position = (cx, cy + distance, cz)
            view_up = (1.0, 0.0, 0.0)
            parallel_scale = orthographic_scale(span_z, span_x)
        else:
            position = (cx - distance, cy + distance * 0.55, cz + distance * 0.75)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = None
        plotter.camera_position = [position, (cx, cy, cz), view_up]
        try:
            plotter.camera.parallel_projection = parallel_scale is not None
            if parallel_scale is not None:
                plotter.camera.parallel_scale = float(parallel_scale)
        except Exception:
            pass
        plotter.reset_camera_clipping_range()
        plotter.set_background("white", top="white")
        plotter.render()

    def _open3d_trace_refresh_service(self) -> Open3DTraceRefreshService:
        service = getattr(self, "_open3d_trace_refresh_service_instance", None)
        if service is None:
            service = Open3DTraceRefreshService(self)
            self._open3d_trace_refresh_service_instance = service
        return service

    def _open3d_step_state_service(self) -> Open3DStepStateService:
        service = getattr(self, "_open3d_step_state_service_instance", None)
        if service is None:
            service = Open3DStepStateService(self, valid_labels=STEP_OVERLAY_LABEL_SET)
            self._open3d_step_state_service_instance = service
        return service

    def _refresh_3d_inspector_if_open(self, *, system=None, rays=None, scene_bundle: SceneBundle | None = None) -> None:
        try:
            self._open3d_trace_refresh_service().sync_open_inspector(
                system=system,
                rays=rays,
                scene_bundle=scene_bundle,
                reset_camera=False,
            )
        except Exception as exc:
            self.append_debug(f"3D inspector sync failed: {exc}")

    @staticmethod
    def _flatten_table_item_args(*items: object) -> list[str]:
        flattened: list[str] = []
        for item in items:
            if item is None:
                continue
            if isinstance(item, str):
                if item:
                    flattened.append(item)
                continue
            if isinstance(item, (list, tuple, set)):
                flattened.extend(KrakenLayoutEditor._flatten_table_item_args(*item))
                continue
            text = str(item)
            if text:
                flattened.append(text)
        return flattened

    def _install_border_only_table_selection(self) -> None:
        self._native_table_selection = self.table.selection
        self._native_table_selection_set = self.table.selection_set
        self._native_table_selection_remove = self.table.selection_remove

        def selection() -> tuple[str, ...]:
            selected = tuple(item for item in self._table_selected_items if self.table.exists(item))
            if len(selected) != len(self._table_selected_items):
                self._table_selected_items = list(selected)
            return selected

        def selection_set(*items: object) -> None:
            ordered: list[str] = []
            seen: set[str] = set()
            for item in self._flatten_table_item_args(*items):
                if self.table.exists(item) and item not in seen:
                    ordered.append(item)
                    seen.add(item)
            self._table_selected_items = ordered
            self._clear_native_table_selection()
            self._schedule_custom_table_selection_changed()

        def selection_remove(*items: object) -> None:
            remove = set(self._flatten_table_item_args(*items))
            if remove:
                self._table_selected_items = [item for item in self._table_selected_items if item not in remove]
            self._clear_native_table_selection()
            self._schedule_custom_table_selection_changed()

        def selection_add(*items: object) -> None:
            selected = list(selection())
            seen = set(selected)
            for item in self._flatten_table_item_args(*items):
                if self.table.exists(item) and item not in seen:
                    selected.append(item)
                    seen.add(item)
            self._table_selected_items = selected
            self._clear_native_table_selection()
            self._schedule_custom_table_selection_changed()

        def selection_toggle(*items: object) -> None:
            selected = list(selection())
            selected_set = set(selected)
            for item in self._flatten_table_item_args(*items):
                if not self.table.exists(item):
                    continue
                if item in selected_set:
                    selected_set.remove(item)
                    selected = [candidate for candidate in selected if candidate != item]
                else:
                    selected.append(item)
                    selected_set.add(item)
            self._table_selected_items = selected
            self._clear_native_table_selection()
            self._schedule_custom_table_selection_changed()

        self.table.selection = selection  # type: ignore[method-assign]
        self.table.selection_set = selection_set  # type: ignore[method-assign]
        self.table.selection_remove = selection_remove  # type: ignore[method-assign]
        self.table.selection_add = selection_add  # type: ignore[method-assign]
        self.table.selection_toggle = selection_toggle  # type: ignore[method-assign]

    def _clear_native_table_selection(self) -> None:
        native_selection = self._native_table_selection
        native_remove = self._native_table_selection_remove
        if native_selection is None or native_remove is None:
            return
        try:
            selected = tuple(native_selection())
        except Exception:
            selected = ()
        if selected:
            try:
                native_remove(*selected)
            except Exception:
                pass

    def _schedule_custom_table_selection_changed(self) -> None:
        if self._table_selection_after_id is not None:
            return
        try:
            self._table_selection_after_id = self.after_idle(self._emit_custom_table_selection_changed)
        except tk.TclError:
            self._table_selection_after_id = None

    def _emit_custom_table_selection_changed(self) -> None:
        self._table_selection_after_id = None
        self._on_table_selection_changed()

    def _current_selected_row_index(self) -> int | None:
        items = self.table.selection()
        if not items:
            return None
        return self._table_item_row_index(items[0])

    def _on_table_selection_changed(self, _event: tk.Event | None = None) -> None:
        self._update_selection_row_borders()
        selected = self.table.selection()
        if selected:
            source_record = self._table_item_scene_record(selected[0])
            if source_record is not None and getattr(source_record, "kind", "") == SCENE_ROW_SOURCE:
                metadata = dict(getattr(source_record, "metadata", {}) or {})
                model = str(metadata.get("model", "") or "Source")
                rays = metadata.get("ray_count", "-")
                self._sync_surface_selection(None, from_table=False)
                self.status_var.set(
                    f"Selected {getattr(source_record, 'label', 'Src')}: {getattr(source_record, 'name', 'Source')} "
                    f"({model}, rays={rays}). Edit source parameters in the Source panel; this row does not consume a KrakenOS surface index."
                )
                return
        self._sync_surface_selection(self._current_selected_row_index(), from_table=True)

    def _clear_table_selection(self) -> None:
        items = list(self.table.get_children())
        if items:
            self.table.selection_remove(*items)
        self.table.focus("")
        self._active_cell = None
        self._hide_active_cell_border()
        self._clear_selection_row_borders()
        self._selection_anchor_row = None
        self._sync_surface_selection(None, from_table=True)
        self.status_var.set("No surface selected")

    def _select_table_indices(self, indices: list[int], *, focus_index: int | None = None) -> None:
        selected_items = [
            item
            for index in indices
            for item in [self._table_item_for_row_index(index)]
            if item is not None
        ]
        if not selected_items:
            return
        self.table.selection_set(selected_items)
        focus_item = self._table_item_for_row_index(focus_index) if focus_index is not None else None
        if focus_item is None:
            focus_item = selected_items[0]
        self.table.focus(focus_item)
        self.table.see(focus_item)
        self._selection_anchor_row = focus_item
        self._schedule_active_cell_border_update()

    def _clear_table_selection_event(self, _event: tk.Event | None = None) -> str:
        self._clear_table_selection()
        return "break"

    def _sync_surface_selection(self, row_index: int | None, *, from_table: bool = False) -> None:
        self._layout_selected_ray_index = None
        if self._three_d_inspector is not None:
            try:
                if self._three_d_inspector.winfo_exists() and self._three_d_inspector.available:
                    self._three_d_inspector.highlight_row(row_index)
            except Exception:
                pass
        if self._legacy_3d_plotter is not None:
            try:
                self._legacy_3d_set_selected_row(self._legacy_3d_plotter, row_index)
            except Exception:
                pass
        self._update_layout_selection_overlay(row_index)
        if from_table and row_index is not None and 0 <= row_index < len(self.rows):
            self.status_var.set(f"Selected row {row_index}: {self.rows[row_index].name}")

    def _select_table_row(self, index: int) -> None:
        row_id = self._table_item_for_row_index(index)
        if row_id is None:
            return
        self.table.selection_set(row_id)
        self.table.focus(row_id)
        self.table.see(row_id)
        self._active_cell = (row_id, "#1")
        self._update_active_cell_border()
        self._sync_surface_selection(index)

    def _startup_refresh_plot(self) -> None:
        if not self.rows:
            return
        self.refresh_plot(suppress_analysis=True)

    def _set_optional_var(self, attr_name: str, value: object) -> None:
        var = self.__dict__.get(attr_name)
        if var is None:
            return
        try:
            var.set(value)
        except Exception:
            pass

